	| "reviews"
	| "referrals"
	| "memberships"
	| "community"
	| "shop"
	| "socialSyndication"
	// Discoverability
	| "structuredData"
	| "sitemaps"
	| "mapsLocal"
	// Integrations
	| "analytics"
	| "heatmaps"
	| "abTesting"
	| "email"
	| "liveChat"
	| "imageCdn"
	| "search"
	| "cdnPurge"
	| "monitoring"
	| "apiTokens"
	| "webhooks"
	| "deployHooks"
	| "plugins"
	// Operations
	| "data"
	| "backups";

export interface AstropressResolvedAdminUiConfig {
	branding: {
		appName: string;
		productName: string;
		shellName: string;
		logoSrc: string | null;
		logoHref: string;
