import { writeFile } from "node:fs/promises";
import sanitizeHtml from "sanitize-html";
import {
	ALLOWED_CONTENT_TYPES,
	MAX_MEDIA_BYTES,
	PRIVATE_HOST_RE,
	SVG_ALLOWED_ATTRS,
	SVG_ALLOWED_TAGS,
	TRANSCODABLE_TYPES,
} from "./download-media-data.js";
import { transcodeViaSharp } from "./sharp-transcode.js";

export function validateMediaSourceUrl(rawUrl: string): URL {
	let parsed: URL;
	try {
		parsed = new URL(rawUrl);
	} catch {
		throw new Error(`Invalid URL: ${rawUrl}`);
	}
	if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
		throw new Error(`Blocked non-HTTP URL scheme: ${parsed.protocol}`);
	}
	if (PRIVATE_HOST_RE.test(parsed.hostname)) {
		throw new Error(`Blocked request to private/loopback host: ${parsed.hostname}`);
	}
	return parsed;
}

function sanitizeSvgBytes(bytes: Uint8Array): Uint8Array {
	const text = new TextDecoder().decode(bytes);
	const sanitized = sanitizeHtml(text, {
		allowedTags: SVG_ALLOWED_TAGS,
		allowedAttributes: { "*": SVG_ALLOWED_ATTRS },
		allowedSchemes: ["http", "https"],
		disallowedTagsMode: "discard",
	});
	return new TextEncoder().encode(sanitized);
}

async function transcodeImageBytes(bytes: Uint8Array, mimeType: string): Promise<Uint8Array> {
	if (mimeType === "image/svg+xml") {
		return sanitizeSvgBytes(bytes);
	}
	if (!TRANSCODABLE_TYPES.has(mimeType)) {
		return bytes;
	}
	const buf = await transcodeViaSharp(Buffer.from(bytes));
	return new Uint8Array(buf);
}

export async function downloadMedia(rawUrl: string): Promise<Uint8Array> {
	validateMediaSourceUrl(rawUrl);
	const response = await fetch(rawUrl);
	if (!response.ok) throw new Error(`HTTP ${response.status}`);
	const contentType = (response.headers.get("content-type") ?? "")
		.split(";")[0]
		.trim()
		.toLowerCase();
	if (!ALLOWED_CONTENT_TYPES.some((t) => contentType === t || contentType.startsWith("image/"))) {
		throw new Error(`Blocked: unexpected media content-type "${contentType}"`);
	}
	const contentLength = Number(response.headers.get("content-length") ?? 0);
	if (contentLength > MAX_MEDIA_BYTES) {
		throw new Error(`Blocked: content-length ${contentLength} exceeds ${MAX_MEDIA_BYTES} bytes`);
	}
	const bytes = new Uint8Array(await response.arrayBuffer());
	if (bytes.length > MAX_MEDIA_BYTES) {
		throw new Error(`Blocked: download size ${bytes.length} exceeds ${MAX_MEDIA_BYTES} bytes`);
	}
	return transcodeImageBytes(bytes, contentType);
}

export async function downloadMediaToFile(rawUrl: string, targetPath: string): Promise<void> {
	const bytes = await downloadMedia(rawUrl);
	await writeFile(targetPath, bytes); // lgtm[js/http-to-file-access]
}

src/import/page-crawler.ts.source:
import sanitizeHtml from "sanitize-html";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type BrowserCrawlOptions = {
	siteUrl: string;
	maxPages?: number;
	timeoutMs?: number;
};

export type CrawledPage = {
	url: string;
	title: string;
	body: string;
	slug: string;
	fetchedAt: string;
};

export type CrawlOptions = {
	siteUrl: string;
	startPaths?: string[];
	maxPages?: number;
	timeoutMs?: number;
	userAgent?: string;
};

export type CrawlResult = {
	pages: CrawledPage[];
	failed: { url: string; reason: string }[];
	warnings: string[];
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function _resolveUrl(base: string, href: string): string | null {
	try {
		return new URL(href, base).toString();
	} catch {
		return null;
	}
}

function isSameOrigin(base: string, url: string): boolean {
	try {
		return new URL(base).origin === new URL(url).origin;
	} catch {
		return false;
	}
}

function slugFromUrl(url: string): string {
	try {
		const parsed = new URL(url);
		const segments = parsed.pathname.split("/").filter(Boolean);
		return segments[segments.length - 1] ?? "home";
	} catch {
		return "page";
	}
}

function extractTitle(html: string): string {
	const match = html.match(/<title[^>]*>([^<]+)<\/title>/i);
	return match?.[1]?.trim() ?? "";
}

function extractBody(html: string): string {
	// Prefer <main>, then <article>, then <body> stripped of nav/header/footer
	const mainMatch = html.match(/<main[^>]*>([\s\S]*?)<\/main>/i);
	if (mainMatch) {
		return cleanHtml(mainMatch[1] as string);
	}

	const articleMatch = html.match(/<article[^>]*>([\s\S]*?)<\/article>/i);
	if (articleMatch) {
		return cleanHtml(articleMatch[1] as string);
	}

	// Strip structural chrome from the full body
	const bodyMatch = html.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
	if (bodyMatch) {
		let body = bodyMatch[1] as string;
		body = body.replace(/<header[\s\S]*?<\/header>/gi, "");
		body = body.replace(/<footer[\s\S]*?<\/footer>/gi, "");
		body = body.replace(/<nav[\s\S]*?<\/nav>/gi, "");
		return cleanHtml(body);
	}

	return cleanHtml(html);
}

function cleanHtml(html: string): string {
	return sanitizeHtml(html, {
		allowedTags: sanitizeHtml.defaults.allowedTags.concat([
			"img",
			"figure",
			"figcaption",
			"picture",
			"source",
		]),
		allowedAttributes: {
			...sanitizeHtml.defaults.allowedAttributes,
			"*": ["id", "class"],
			img: ["src", "alt", "width", "height", "loading"],
			a: ["href", "title", "rel"],
		},
	}).trim();
}

function parseSitemapUrls(xml: string, siteOrigin: string): string[] {
	const urls: string[] = [];
	const locRegex = /<loc>\s*([^<]+)\s*<\/loc>/gi;
	let match = locRegex.exec(xml);
	while (match !== null) {
		const url = match[1]?.trim();
		if (isSameOrigin(siteOrigin, url)) {
			urls.push(url);
		}
		match = locRegex.exec(xml);
	}
	return urls;
}

// ---------------------------------------------------------------------------
// Crawler
// ---------------------------------------------------------------------------

export async function crawlSitePages(opts: CrawlOptions): Promise<CrawlResult> {
	const {
		siteUrl,
		maxPages = 500,
		timeoutMs = 15_000,
		userAgent = "Astropress-Crawler/1.0",
	} = opts;

	const origin = new URL(siteUrl).origin;
	const fetchOpts: RequestInit = {
		headers: { "User-Agent": userAgent },
		signal: AbortSignal.timeout(timeoutMs),
	};

	const pages: CrawledPage[] = [];
	const failed: { url: string; reason: string }[] = [];
	const warnings: string[] = [];
	const visited = new Set<string>();

	// Step 1: try sitemap.xml
	let urlsToVisit: string[] = [];
	try {
		const sitemapUrl = `${origin}/sitemap.xml`;
		const sitemapRes = await fetch(sitemapUrl, fetchOpts);
		if (sitemapRes.ok) {
			const xml = await sitemapRes.text();
			urlsToVisit = parseSitemapUrls(xml, origin);
		} else {
			warnings.push(
				`No sitemap.xml found at ${sitemapUrl} (HTTP ${sitemapRes.status}) — crawling from homepage`,
			);
			urlsToVisit = [`${origin}/`];
		}
	} catch (err) {
		warnings.push(
			`Could not fetch sitemap.xml: ${err instanceof Error ? err.message : String(err)} — crawling from homepage`,
		);
		urlsToVisit = [`${origin}/`];
	}

	// Deduplicate
	urlsToVisit = [...new Set(urlsToVisit)];

	// Step 2: fetch each page
	for (const url of urlsToVisit) {
		if (visited.has(url)) continue;
		if (pages.length >= maxPages) break;
		visited.add(url);

		try {
			const res = await fetch(url, fetchOpts);
			if (!res.ok) {
				failed.push({ url, reason: `HTTP ${res.status}` });
				continue;
			}
			const contentType = res.headers.get("content-type") ?? "";
			if (!contentType.includes("text/html")) {
				continue; // skip non-HTML resources
			}
			const html = await res.text();
			pages.push({
				url,
				title: extractTitle(html),
				body: extractBody(html),
				slug: slugFromUrl(url),
				fetchedAt: new Date().toISOString(),
			});
		} catch (err) {
			failed.push({
				url,
				reason: err instanceof Error ? err.message : String(err),
			});
		}
	}

	return { pages, failed, warnings };
}

// ---------------------------------------------------------------------------
// Browser crawler (Playwright) — handles JS-rendered pages (e.g. Wix)
// ---------------------------------------------------------------------------

/**
 * Full browser crawl using Playwright. Use this when the target site renders
 * content via JavaScript (e.g. Wix sites) that plain fetch cannot capture.
 *
 * Requires Playwright to be installed: `bunx playwright install chromium`
 */
export async function crawlSitePagesWithBrowser(opts: BrowserCrawlOptions): Promise<CrawlResult> {
	const { siteUrl, maxPages = 500, timeoutMs = 30_000 } = opts;

	// Lazy-load Playwright so it isn't required for fetch-mode crawls.
	let chromium: import("playwright").BrowserType;
	try {
		const pw = await import("playwright");
		chromium = pw.chromium;
	} catch {
		return {
			pages: [],
			failed: [
				{
					url: siteUrl,
					reason: "Playwright is not installed — run: bunx playwright install chromium",
				},
			],
			warnings: ["Playwright not available; falling back is recommended"],
		};
	}

	const origin = new URL(siteUrl).origin;
	const pages: CrawledPage[] = [];
	const failed: { url: string; reason: string }[] = [];
	const warnings: string[] = [];
	const visited = new Set<string>();

	const browser = await chromium.launch({ headless: true });
	const context = await browser.newContext({
		userAgent: "Astropress-Crawler/1.0",
	});

	try {
		// Try sitemap first to get a full URL list.
		let urlsToVisit: string[] = [];
		try {
			const sitemapPage = await context.newPage();
			const resp = await sitemapPage.goto(`${origin}/sitemap.xml`, {
				timeout: timeoutMs,
			});
			if (resp?.ok()) {
				const xml = await sitemapPage.content();
				urlsToVisit = parseSitemapUrls(xml, origin);
			}
			await sitemapPage.close();
		} catch {
			warnings.push("Could not fetch sitemap.xml with browser — crawling from homepage");
		}
		if (urlsToVisit.length === 0) urlsToVisit = [`${origin}/`];
		urlsToVisit = [...new Set(urlsToVisit)];

		for (const url of urlsToVisit) {
			if (visited.has(url)) continue;
			if (pages.length >= maxPages) break;
			visited.add(url);

			const page = await context.newPage();
			try {
				const resp = await page.goto(url, {
					timeout: timeoutMs,
					waitUntil: "networkidle",
				});
				if (!resp?.ok()) {
					failed.push({ url, reason: `HTTP ${resp?.status() ?? "unknown"}` });
					continue;
				}
				const html = await page.content();
				pages.push({
					url,
					title: extractTitle(html),
					body: extractBody(html),
					slug: slugFromUrl(url),
					fetchedAt: new Date().toISOString(),
				});
			} catch (err) {
				failed.push({
					url,
					reason: err instanceof Error ? err.message : String(err),
				});
			} finally {
				await page.close();
			}
		}
	} finally {
		await browser.close();
	}

	return { pages, failed, warnings };
}

src/import/wix.ts.source:
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { downloadMediaToFile } from "./download-media.js";
import type { WixParsedBundle } from "./wix-apply.js";
import { applyWixImportToLocalRuntime } from "./wix-apply.js";
import {
	cleanWixHtml,
	guessExtension,
	guessMimeTypeWix,
	lastPathSegment,
	normalizeWixImageUrl,
	scrapeImageUrls,
	slugify,
	splitCsvRows,
	splitTermList,
} from "./wix-csv.js";

type DownloadState = {
	completed: string[];
	failed: { id: string; sourceUrl: string; reason: string }[];
};

export function parseWixExport(csvText: string): WixParsedBundle {
	const rows = splitCsvRows(csvText);
	if (rows.length < 2) {
		return {
			authors: [],
			terms: [],
			contentRecords: [],
			mediaAssets: [],
			warnings: ["No rows found in Wix CSV export."],
		};
	}

	const headerRow = rows[0] as string[];
	const headerIndex = new Map<string, number>();
	headerRow.forEach((col, i) => {
		headerIndex.set(col.toLowerCase().trim(), i);
	});

	function col(row: string[], names: string[]): string {
		for (const name of names) {
			const idx = headerIndex.get(name);
			if (idx !== undefined && row[idx] !== undefined) return row[idx]?.trim();
		}
		return "";
	}

	const authorSet = new Map<string, WixParsedBundle["authors"][0]>();
	const categorySet = new Map<string, WixParsedBundle["terms"][0]>();
	const tagSet = new Map<string, WixParsedBundle["terms"][0]>();
	const mediaSet = new Map<string, WixParsedBundle["mediaAssets"][0]>();
	const contentRecords: WixParsedBundle["contentRecords"] = [];
	const warnings: string[] = [];
	let mediaIndex = 0;

	for (const row of rows.slice(1)) {
		const title = col(row, ["title"]);
		const body = col(row, ["body", "content", "richtext", "html"]);
		const isDraft = col(row, ["isdraft", "draft"]).toLowerCase() === "true";
		const status: "draft" | "published" = isDraft ? "draft" : "published";
		const authorName = col(row, ["author", "writer"]) || "Unknown";
		const authorLogin = slugify(authorName);
		const rawSlug = col(row, ["slug", "url", "posturl", "link"]);
		const slug = rawSlug ? lastPathSegment(rawSlug) || slugify(title) : slugify(title);
		const legacyUrl = rawSlug || `/${slug}`;
		const publishedAt =
			col(row, ["publisheddate", "publicationdate", "published", "date"]) || undefined;
		const excerpt = col(row, ["excerpt", "description", "summary"]) || undefined;
		const coverImageRaw = col(row, ["coverimage", "featuredimage", "image", "thumbnail"]);

		if (!title && !body) continue;

		if (!authorSet.has(authorLogin))
			authorSet.set(authorLogin, {
				login: authorLogin,
				displayName: authorName,
			});

		const categorySlugs: string[] = [];
		for (const cat of splitTermList(col(row, ["categories", "category"]))) {
			const catSlug = slugify(cat);
			categorySlugs.push(catSlug);
			if (!categorySet.has(catSlug))
				categorySet.set(catSlug, {
					kind: "category",
					slug: catSlug,
					name: cat,
				});
		}

		const tagSlugs: string[] = [];
		for (const tag of splitTermList(col(row, ["tags", "tag"]))) {
			const tagSlug = slugify(tag);
			tagSlugs.push(tagSlug);
			if (!tagSet.has(tagSlug)) tagSet.set(tagSlug, { kind: "tag", slug: tagSlug, name: tag });
		}

		if (coverImageRaw) {
			const normalized = normalizeWixImageUrl(coverImageRaw);
			if (!mediaSet.has(normalized)) {
				const id = `wix-media-${mediaIndex++}`;
				const filename = `${id}${guessExtension(normalized)}`;
				mediaSet.set(normalized, {
					id,
					slug: id,
					title: title || id,
					sourceUrl: normalized,
					filename,
					mimeType: guessMimeTypeWix(normalized),
				});
			}
		}

		for (const imgUrl of scrapeImageUrls(body)) {
			const normalized = normalizeWixImageUrl(imgUrl);
			if (!mediaSet.has(normalized)) {
				const id = `wix-media-${mediaIndex++}`;
				const filename = `${id}${guessExtension(normalized)}`;
				mediaSet.set(normalized, {
					id,
					slug: id,
					title: id,
					sourceUrl: normalized,
					filename,
					mimeType: guessMimeTypeWix(normalized),
				});
			}
		}

		contentRecords.push({
			id: `wix-post-${contentRecords.length}`,
			kind: "post",
			slug,
			title,
			body: cleanWixHtml(body),
			excerpt,
			status,
			legacyUrl,
			publishedAt,
			authorLogins: [authorLogin],
			categorySlugs,
			tagSlugs,
		});
	}

	if (contentRecords.length === 0) {
		warnings.push(
			"No blog posts were found in the Wix CSV export. Only blog post exports are supported (Wix pages cannot be exported).",
		);
	}

	return {
		authors: Array.from(authorSet.values()),
		terms: [...Array.from(categorySet.values()), ...Array.from(tagSet.values())],
		contentRecords,
		mediaAssets: Array.from(mediaSet.values()),
		warnings,
	};
}

async function loadDownloadState(stateFile: string): Promise<DownloadState> {
	try {
		return JSON.parse(await readFile(stateFile, "utf8")) as DownloadState;
	} catch {
		return { completed: [], failed: [] };
	}
}

async function downloadWixMedia(
	assets: WixParsedBundle["mediaAssets"],
	artifactDir: string,
	resumeFrom?: string,
): Promise<{
	downloadedMedia: number;
	failedMedia: DownloadState["failed"];
	downloadStateFile: string;
}> {
	const downloadsDir = path.join(artifactDir, "downloads");
	await mkdir(downloadsDir, { recursive: true });
	const stateFile = resumeFrom ?? path.join(artifactDir, "download-state.json");
	const state = await loadDownloadState(stateFile);
	const completedSet = new Set(state.completed);
	let downloadedMedia = state.completed.length;

	for (const asset of assets) {
		if (completedSet.has(asset.id)) continue;
		try {
			await downloadMediaToFile(
				asset.sourceUrl,
				path.join(downloadsDir, path.basename(asset.filename)),
			);
			state.completed.push(asset.id);
			downloadedMedia++;
		} catch (err) {
			state.failed.push({
				id: asset.id,
				sourceUrl: asset.sourceUrl,
				reason: err instanceof Error ? err.message : String(err),
			});
		}
		await writeFile(stateFile, JSON.stringify(state, null, 2));
	}

	return {
		downloadedMedia,
		failedMedia: state.failed,
		downloadStateFile: stateFile,
	};
}

async function stageWixArtifacts(artifactDir: string, bundle: WixParsedBundle) {
	await mkdir(artifactDir, { recursive: true });
	const files = {
		contentFile: path.join(artifactDir, "content-records.json"),
		mediaFile: path.join(artifactDir, "media-manifest.json"),
		userFile: path.join(artifactDir, "user-records.json"),
		taxonomyFile: path.join(artifactDir, "taxonomy-records.json"),
		downloadStateFile: path.join(artifactDir, "download-state.json"),
	};
	await writeFile(files.contentFile, JSON.stringify(bundle.contentRecords, null, 2));
	await writeFile(files.mediaFile, JSON.stringify(bundle.mediaAssets, null, 2));
	await writeFile(files.userFile, JSON.stringify(bundle.authors, null, 2));
	await writeFile(files.taxonomyFile, JSON.stringify(bundle.terms, null, 2));
	return files;
}

export function createAstropressWixImportSource() {
	return {
		async importWix(input: {
			exportFile: string;
			artifactDir?: string;
			downloadMedia?: boolean;
			applyLocal?: boolean;
			workspaceRoot?: string;
			adminDbPath?: string;
			resumeFrom?: string;
		}) {
			const csvText = await readFile(input.exportFile, "utf8");
			const bundle = parseWixExport(csvText);

			let artifacts: Awaited<ReturnType<typeof stageWixArtifacts>> | undefined;
			if (input.artifactDir) artifacts = await stageWixArtifacts(input.artifactDir, bundle);

			let downloadedMedia = 0;
			const failedMedia: DownloadState["failed"] = [];
			if (input.downloadMedia && input.artifactDir && bundle.mediaAssets.length > 0) {
				const dl = await downloadWixMedia(bundle.mediaAssets, input.artifactDir, input.resumeFrom);
				downloadedMedia = dl.downloadedMedia;
				failedMedia.push(...dl.failedMedia);
			}

			let localApply: Awaited<ReturnType<typeof applyWixImportToLocalRuntime>> | undefined;
			if (input.applyLocal && input.workspaceRoot) {
				localApply = await applyWixImportToLocalRuntime({
					bundle,
					artifactDir: input.artifactDir,
					workspaceRoot: input.workspaceRoot,
					adminDbPath: input.adminDbPath,
				});
			}

			return {
				status: failedMedia.length > 0 ? "partial" : "complete",
				imported_records: bundle.contentRecords.length,
				imported_media: bundle.mediaAssets.length,
				imported_authors: bundle.authors.length,
				downloaded_media: downloadedMedia,
				failed_media: failedMedia,
				warnings: bundle.warnings,
				artifacts: artifacts
					? {
							artifact_dir: input.artifactDir ?? null,
							content_file: artifacts.contentFile,
							media_file: artifacts.mediaFile,
							user_file: artifacts.userFile,
							taxonomy_file: artifacts.taxonomyFile,
							download_state_file: artifacts.downloadStateFile,
						}
					: null,
				local_apply: localApply
					? {
							applied_records: localApply.appliedRecords,
							applied_media: localApply.appliedMedia,
							applied_authors: localApply.appliedAuthors,
							admin_db_path: localApply.adminDbPath,
						}
					: null,
			};
		},
	};
}

