/**
 * D1 sibling of `flash.ts`. Implements the same {@link FlashStore} contract,
 * but every method awaits D1's promise-returning SDK calls. The SQL bodies are
 * byte-for-byte the same as the sqlite store so both backends behave
 * identically; the only difference is the async driver shape. The dispatch
 * seam (`admin-store-dispatch.ts` `resolveFlashStore`) picks the backend. See
 * the secret-in-URL class, issues #113/#115/#133.
 */

import type { D1DatabaseLike } from "../d1-database";
import type { FlashStore } from "../platform-contracts-helpers";
import { FLASH_DEFAULT_TTL_MS, newFlashId } from "./flash";

interface FlashRow {
	payload: string;
	expires_at_ms: number;
}

export function createD1FlashStore(db: D1DatabaseLike): FlashStore {
	return {
		async put(payload, ttlMs = FLASH_DEFAULT_TTL_MS) {
			const now = Date.now();
			await db.prepare("DELETE FROM admin_flash WHERE expires_at_ms <= ?").bind(now).run();
			const id = newFlashId();
			await db
				.prepare(
					"INSERT INTO admin_flash (id, payload, created_at_ms, expires_at_ms) VALUES (?, ?, ?, ?)",
				)
				.bind(id, payload, now, now + ttlMs)
				.run();
			return { id };
		},

		async consume(id) {
			const row = await db
				.prepare("SELECT payload, expires_at_ms FROM admin_flash WHERE id = ?")
				.bind(id)
				.first<FlashRow>();
			// Delete unconditionally so a replay of the same id can never succeed.
			await db.prepare("DELETE FROM admin_flash WHERE id = ?").bind(id).run();
			if (!row || row.expires_at_ms <= Date.now()) {
				return null;
			}
			return row.payload;
		},
	};
}

src/sqlite-runtime/integrations.ts.source:
/**
 * Repository over the connected_integrations + integration_secrets
 * tables. Two halves with deliberately separated surfaces:
 *
 *   - Status surface (findStatus, listStatuses, updateStatus,
 *     disconnect): never reads from `integration_secrets`. Sidebar
 *     status badges and dashboards must call only these methods, so
 *     ciphertext stays off the read path.
 *
 *   - Secret surface (findSecret, upsertSecret): explicit
 *     `rootSecrets` argument gates every plaintext access. After a
 *     successful previous-key decrypt, opportunistically reseals
 *     under current with a guarded UPDATE so a concurrent admin
 *     write isn't clobbered.
 *
 * Design doc: tooling/docs/phase-2-secret-store-design.md
 */

import type {
	RootSecretCandidates,
	SealedSecret,
	SecretContext,
} from "../integration-secret-envelope";
import { openIntegrationSecret, sealIntegrationSecret } from "../integration-secret-envelope";
import {
	SQL_CLEAR_ACTIVE_IN_DOMAIN,
	SQL_COUNT_ACTIVE_IN_DOMAIN,
	SQL_DISCONNECT,
	SQL_FIND_SECRET,
	SQL_FIND_STATUS,
	SQL_LIST_PREVIOUS_SECRETS,
	SQL_LIST_STATUSES,
	SQL_MARK_ACTIVE,
	SQL_RESEAL_GUARDED,
	SQL_UPDATE_STATUS,
	SQL_UPSERT_SECRET,
	SQL_UPSERT_STATUS,
} from "./integrations-data.js";
import type { AstropressSqliteDatabaseLike } from "./utils";

export type IntegrationStatusValue = "connected" | "error" | "paused";

export interface IntegrationStatusRow {
	domain: string;
	provider: string;
	status: IntegrationStatusValue;
	configJson: string;
	connectedAt: string;
	lastCheckAt: string | null;
	lastError: string | null;
	/** Explicit per-domain active selection (#127). At most one true per domain. */
	isActive: boolean;
}

export interface ConnectIntegrationInput<
	TFields extends Record<string, string> = Record<string, string>,
> {
	domain: string;
	provider: string;
	configJson: string;
	secretFields: TFields;
	now: string; // ISO 8601
}

export interface IntegrationsRepositoryOptions {
	getDb: () => AstropressSqliteDatabaseLike;
	now: () => string;
}

interface RawStatusRow {
	domain: string;
	provider: string;
	status: string;
	config_json: string;
	connected_at: string;
	last_check_at: string | null;
	last_error: string | null;
	is_active: number;
}

interface RawSecretRow {
	domain: string;
	provider: string;
	envelope_v: number;
	kid: string;
	wrap_salt: string;
	wrap_iv: string;
	dek_wrap: string;
	data_iv: string;
	ciphertext: string;
	rotated_at: string;
}

function rowToStatus(row: RawStatusRow): IntegrationStatusRow {
	return {
		domain: row.domain,
		provider: row.provider,
		status: row.status as IntegrationStatusValue,
		configJson: row.config_json,
		connectedAt: row.connected_at,
		lastCheckAt: row.last_check_at,
		lastError: row.last_error,
		isActive: row.is_active === 1,
	};
}

function rowToSealed(row: RawSecretRow): SealedSecret {
	return {
		v: row.envelope_v as 1,
		kid: row.kid as "current" | "previous",
		wrap_salt: row.wrap_salt,
		wrap_iv: row.wrap_iv,
		dek_wrap: row.dek_wrap,
		data_iv: row.data_iv,
		ciphertext: row.ciphertext,
	};
}

export interface IntegrationsRepository {
	findStatus(domain: string, provider: string): IntegrationStatusRow | undefined;
	listStatuses(): IntegrationStatusRow[];
	updateStatus(input: {
		domain: string;
		provider: string;
		status: IntegrationStatusValue;
		lastCheckAt: string;
		lastError?: string | null;
	}): boolean;
	disconnect(domain: string, provider: string): boolean;

	/**
	 * Makes `provider` the single active provider for `domain` (#127), clearing
	 * any prior active row in the domain. Returns false when the target is not a
	 * connected provider (you can only activate something that's connected).
	 */
	setActiveProvider(domain: string, provider: string): boolean;

	connect<TFields extends Record<string, string> = Record<string, string>>(
		input: ConnectIntegrationInput<TFields>,
		rootSecret: string,
	): Promise<void>;

	findSecret<TFields extends Record<string, string> = Record<string, string>>(
		domain: string,
		provider: string,
		rootSecrets: RootSecretCandidates,
	): Promise<TFields | undefined>;

	listPreviousKidContexts(): SecretContext[];
}

export function createIntegrationsRepository(
	options: IntegrationsRepositoryOptions,
): IntegrationsRepository {
	const { getDb, now } = options;

	function findStatus(domain: string, provider: string): IntegrationStatusRow | undefined {
		const row = getDb().prepare(SQL_FIND_STATUS).get(domain, provider) as RawStatusRow | undefined;
		return row ? rowToStatus(row) : undefined;
	}

	function listStatuses(): IntegrationStatusRow[] {
		const rows = getDb().prepare(SQL_LIST_STATUSES).all() as RawStatusRow[];
		return rows.map(rowToStatus);
	}

	function updateStatus(input: {
		domain: string;
		provider: string;
		status: IntegrationStatusValue;
		lastCheckAt: string;
		lastError?: string | null;
	}): boolean {
		const result = getDb()
			.prepare(SQL_UPDATE_STATUS)
			.run(input.status, input.lastCheckAt, input.lastError ?? null, input.domain, input.provider);
		// Defensive `?? 0`: node:sqlite run() always returns a numeric `changes`.
		/* v8 ignore start */
		return result.changes > 0;
		/* v8 ignore stop */
	}

	function disconnect(domain: string, provider: string): boolean {
		const result = getDb().prepare(SQL_DISCONNECT).run(domain, provider);
		// Defensive `?? 0`: node:sqlite run() always returns a numeric `changes`.
		/* v8 ignore start */
		return result.changes > 0;
		/* v8 ignore stop */
	}

	function setActiveProvider(domain: string, provider: string): boolean {
		const db = getDb();
		db.prepare(SQL_CLEAR_ACTIVE_IN_DOMAIN).run(domain);
		const result = db.prepare(SQL_MARK_ACTIVE).run(domain, provider);
		// Defensive `?? 0`: node:sqlite run() always returns a numeric `changes`.
		/* v8 ignore start */
		return result.changes > 0;
		/* v8 ignore stop */
	}

	function hasActiveProvider(domain: string): boolean {
		const row = getDb().prepare(SQL_COUNT_ACTIVE_IN_DOMAIN).get(domain) as
			| { n: number }
			| undefined;
		// COUNT(*) always returns one row, so `row?.`/`?? 0` are defensive only.
		/* v8 ignore start */
		return (row?.n ?? 0) > 0;
		/* v8 ignore stop */
	}

	async function connect<TFields extends Record<string, string> = Record<string, string>>(
		input: ConnectIntegrationInput<TFields>,
		rootSecret: string,
	): Promise<void> {
		const sealed = await sealIntegrationSecret(
			input.secretFields,
			{ domain: input.domain, provider: input.provider },
			rootSecret,
		);
		const db = getDb();
		db.prepare(SQL_UPSERT_STATUS).run(
			input.domain,
			input.provider,
			"connected",
			input.configJson,
			input.now,
		);
		db.prepare(SQL_UPSERT_SECRET).run(
			input.domain,
			input.provider,
			sealed.v,
			sealed.kid,
			sealed.wrap_salt,
			sealed.wrap_iv,
			sealed.dek_wrap,
			sealed.data_iv,
			sealed.ciphertext,
			input.now,
		);
		// First provider connected in a domain becomes active automatically;
		// once a domain already has an active provider, connecting another does
		// NOT steal the selection — switching is an explicit admin action (#127).
		if (!hasActiveProvider(input.domain)) {
			db.prepare(SQL_MARK_ACTIVE).run(input.domain, input.provider);
		}
	}

	async function findSecret<TFields extends Record<string, string> = Record<string, string>>(
		domain: string,
		provider: string,
		rootSecrets: RootSecretCandidates,
	): Promise<TFields | undefined> {
		const row = getDb().prepare(SQL_FIND_SECRET).get(domain, provider) as RawSecretRow | undefined;
		if (!row) return undefined;
		const sealed = rowToSealed(row);
		const ctx: SecretContext = { domain, provider };
		const opened = await openIntegrationSecret<TFields>(sealed, ctx, rootSecrets);
		// Reseal-on-read: when we just decrypted with the previous key, push
		// the record forward under current in a guarded UPDATE.
		if (opened.usedKid === "previous" && rootSecrets.previous) {
			const resealed = await sealIntegrationSecret(opened.fields, ctx, rootSecrets.current);
			getDb()
				.prepare(SQL_RESEAL_GUARDED)
				.run(
					resealed.v,
					resealed.kid,
					resealed.wrap_salt,
					resealed.wrap_iv,
					resealed.dek_wrap,
					resealed.data_iv,
					resealed.ciphertext,
					now(),
					domain,
					provider,
					row.ciphertext,
					row.kid,
				);
		}
		return opened.fields;
	}

	function listPreviousKidContexts(): SecretContext[] {
		const rows = getDb().prepare(SQL_LIST_PREVIOUS_SECRETS).all() as RawSecretRow[];
		return rows.map((row) => ({
			domain: row.domain,
			provider: row.provider,
		}));
	}

	return {
		findStatus,
		listStatuses,
		updateStatus,
		disconnect,
		setActiveProvider,
		connect,
		findSecret,
		listPreviousKidContexts,
	};
}

