	it("createStructuredPageRoute succeeds when cms config is available", () => {
		const result = cmsRegistry.createStructuredPageRoute(
			"/new-hero-page",
			{
				title: "New Hero Page",
				templateKey: "hero",
				sections: { hero: "hello" },
