// ─── GET /ap-api/v1/settings ─────────────────────────────────────────────────

describe("GET /ap-api/v1/settings", () => {
	it("returns 200 with site settings for settings:read scope", async () => {
		const res = await settingsGET(
			ctx(req("GET", "/ap-api/v1/settings", { token: settingsReadToken })),
		);
		expect(res.status).toBe(200);
		const body = (await res.json()) as { siteTitle: string };
		expect(body.siteTitle).toBe("Test Site");
	});
});

// ─── GET + POST /ap-api/v1/webhooks ──────────────────────────────────────────

describe("GET /ap-api/v1/webhooks + POST /ap-api/v1/webhooks", () => {
	it("returns 200 with webhook list for webhooks:manage scope", async () => {
		const res = await webhooksGET(
			ctx(req("GET", "/ap-api/v1/webhooks", { token: webhooksManageToken })),
		);
		expect(res.status).toBe(200);
		const body = (await res.json()) as { records: unknown[] };
		expect(Array.isArray(body.records)).toBe(true);
	});

	it("POST creates a webhook and returns verification metadata once", async () => {
		const res = await webhooksPOST(
			ctx(
				req("POST", "/ap-api/v1/webhooks", {
					token: webhooksManageToken,
					body: {
						url: "https://example.com/hook",
						events: ["content.published"],
					},
				}),
			),
		);
		expect(res.status).toBe(201);
		const body = (await res.json()) as {
			verification: { algorithm: string; publicKey: string };
		};
		expect(body.verification.algorithm).toBe("ML-DSA-65");
		expect(body.verification.publicKey.length).toBeGreaterThan(0);
	});

	// Parity with the admin form action (issue #141): the token-authenticated
	// REST path must reject the same input the admin UI would, and must never
	// persist an unvalidated webhook target/event.
	it("POST rejects a non-http(s) url with 422 and does not persist", async () => {
		mocks.webhooksCreate.mockClear();
		const res = await webhooksPOST(
			ctx(
				req("POST", "/ap-api/v1/webhooks", {
					token: webhooksManageToken,
					body: { url: "ftp://example.com/hook", events: ["content.published"] },
				}),
			),
		);
		expect(res.status).toBe(422);
		const body = (await res.json()) as { error: string; code: string };
		expect(body.code).toBe("validation_error");
		expect(body.error).toContain("http://");
		expect(mocks.webhooksCreate).not.toHaveBeenCalled();
	});

	it("POST rejects an unsupported event name with 422 and does not persist", async () => {
		mocks.webhooksCreate.mockClear();
		const res = await webhooksPOST(
			ctx(
				req("POST", "/ap-api/v1/webhooks", {
					token: webhooksManageToken,
					body: {
						url: "https://example.com/hook",
						events: ["content.published", "content.created"],
					},
				}),
			),
		);
		expect(res.status).toBe(422);
		const body = (await res.json()) as { error: string };
		expect(body.error).toContain("not supported");
		expect(mocks.webhooksCreate).not.toHaveBeenCalled();
	});

	it("POST rejects an empty events array with 422 and does not persist", async () => {
		mocks.webhooksCreate.mockClear();
		const res = await webhooksPOST(
			ctx(
				req("POST", "/ap-api/v1/webhooks", {
					token: webhooksManageToken,
					body: { url: "https://example.com/hook", events: [] },
				}),
			),
		);
		expect(res.status).toBe(422);
		expect(mocks.webhooksCreate).not.toHaveBeenCalled();
	});
});

// ─── GET /ap-api/v1/openapi.json ─────────────────────────────────────────────

describe("GET /ap-api/v1/openapi.json", () => {
	it("returns 200 with a valid OpenAPI 3.1 JSON object", async () => {
		const res = await openapiGET();
		expect(res.status).toBe(200);
		const body = (await res.json()) as { openapi: string };
		expect(body.openapi).toBe("3.1.0");
	});

	it("includes securitySchemes with BearerAuth", async () => {
		const res = await openapiGET();
		const body = (await res.json()) as {
			components: { securitySchemes: Record<string, unknown> };
		};
		expect(body.components.securitySchemes.BearerAuth).toBeDefined();
	});

	it("includes all /ap-api/v1/* paths", async () => {
		const res = await openapiGET();
		const body = (await res.json()) as { paths: Record<string, unknown> };
		const paths = Object.keys(body.paths);
		expect(paths).toContain("/content");
		expect(paths).toContain("/content/{id}");
		expect(paths).toContain("/media");
		expect(paths).toContain("/revisions/{recordId}");
		expect(paths).toContain("/settings");
		expect(paths).toContain("/webhooks");
		expect(paths).toContain("/openapi.json");
	});

	it("does not require Authorization header", async () => {
		// No token provided — openapi endpoint has no auth check
		const res = await openapiGET();
		expect(res.status).toBe(200);
	});
});

