import { existsSync, mkdirSync, readdirSync, rmSync, statSync } from "node:fs";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

// ---------------------------------------------------------------------------
// vi.mock is hoisted above all let/const initializers, so any variable used
// inside the factory must be defined via vi.hoisted(). The module also captures
// getLocalUploadsDir() once at init time, so we use a fixed path and clean the
// directory between tests rather than creating a new path per run.
// ---------------------------------------------------------------------------

const { testUploadsDir } = vi.hoisted(() => {
	// eslint-disable-next-line @typescript-eslint/no-require-imports
	const { mkdtempSync } = require("node:fs") as typeof import("node:fs");
	// eslint-disable-next-line @typescript-eslint/no-require-imports
	const { join } = require("node:path") as typeof import("node:path");
	// eslint-disable-next-line @typescript-eslint/no-require-imports
	const { tmpdir } = require("node:os") as typeof import("node:os");
	return { testUploadsDir: mkdtempSync(join(tmpdir(), "astropress-media-")) };
});

vi.mock("../src/local-image-storage", () => ({
	ensureLocalUploadsDir: vi.fn(),
	getLocalUploadsDir: vi.fn(() => testUploadsDir),
	guessImageMimeType: vi.fn((path: string) => {
		if (path.endsWith(".png")) return "image/png";
		if (path.endsWith(".jpg") || path.endsWith(".jpeg")) return "image/jpeg";
		if (path.endsWith(".webp")) return "image/webp";
		if (path.endsWith(".gif")) return "image/gif";
		if (path.endsWith(".avif")) return "image/avif";
		if (path.endsWith(".svg")) return "image/svg+xml";
		return "application/octet-stream";
	}),
}));

import {
	buildLocalMediaDescriptor,
	createLocalMediaUpload,
	deleteLocalMediaUpload,
	guessMediaMimeType,
} from "../src/local-media-storage";

const validPng = new Uint8Array(1024); // 1 KB image bytes (fake PNG)
const oversizedFile = new Uint8Array(11 * 1024 * 1024); // 11 MB — exceeds limit

beforeEach(() => {
	rmSync(testUploadsDir, { recursive: true, force: true });
	mkdirSync(testUploadsDir, { recursive: true });
});

afterEach(() => {
	rmSync(testUploadsDir, { recursive: true, force: true });
});

// ---------------------------------------------------------------------------
// guessMediaMimeType
// ---------------------------------------------------------------------------

describe("guessMediaMimeType", () => {
	it("delegates to guessImageMimeType from local-image-storage", () => {
		expect(guessMediaMimeType("photo.png")).toBe("image/png");
		expect(guessMediaMimeType("photo.jpg")).toBe("image/jpeg");
		expect(guessMediaMimeType("photo.webp")).toBe("image/webp");
	});
});

// ---------------------------------------------------------------------------
// buildLocalMediaDescriptor
// ---------------------------------------------------------------------------

describe("buildLocalMediaDescriptor", () => {
	it("returns a valid descriptor for a PNG upload", () => {
		const result = buildLocalMediaDescriptor({
			filename: "photo.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(result.asset.mimeType).toBe("image/png");
		expect(result.asset.fileSize).toBe(1024);
		expect(result.asset.publicPath).toMatch(/^\/images\/uploads\//);
		expect(result.asset.r2Key).toMatch(/^uploads\//);
		expect(result.asset.storedFilename).toMatch(/^media-[0-9a-f-]{36}$/);
	});

	it("uses provided title and altText", () => {
		const result = buildLocalMediaDescriptor({
			filename: "banner.png",
			bytes: validPng,
			title: "My Banner",
			altText: "A colourful banner",
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(result.asset.title).toBe("My Banner");
		expect(result.asset.altText).toBe("A colourful banner");
	});

	it("falls back to sanitised basename as title", () => {
		const result = buildLocalMediaDescriptor({
			filename: "my awesome photo.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(result.asset.title).toBe("my-awesome-photo");
	});

	it("rejects empty filename", () => {
		const result = buildLocalMediaDescriptor({ filename: "", bytes: validPng });
		expect(result).toMatchObject({ ok: false });
		expect((result as { error: string }).error).toContain("Select a file");
	});

	it("rejects zero-byte file", () => {
		const result = buildLocalMediaDescriptor({
			filename: "empty.png",
			bytes: new Uint8Array(0),
		});
		expect(result).toMatchObject({ ok: false });
	});

	it("rejects file exceeding 10 MB", () => {
		const result = buildLocalMediaDescriptor({
			filename: "huge.png",
			bytes: oversizedFile,
		});
		expect(result).toMatchObject({ ok: false });
		expect((result as { error: string }).error).toContain("10 MB");
	});

	it("rejects disallowed extension (.php)", () => {
		const result = buildLocalMediaDescriptor({
			filename: "malicious.php",
			bytes: validPng,
		});
		expect(result).toMatchObject({ ok: false });
		expect((result as { error: string }).error).toContain("not allowed");
	});

	it("rejects disallowed extension (.exe)", () => {
		const result = buildLocalMediaDescriptor({
			filename: "evil.exe",
			bytes: validPng,
		});
		expect(result).toMatchObject({ ok: false });
	});

	it("accepts all allowed extensions", () => {
		const allowed = [
			"photo.jpg",
			"photo.jpeg",
			"photo.png",
			"photo.webp",
			"photo.gif",
			"photo.avif",
			"photo.svg",
		];
		for (const filename of allowed) {
			const result = buildLocalMediaDescriptor({ filename, bytes: validPng });
			expect(result.ok, `Expected ok for ${filename}`).toBe(true);
		}
	});

	it("rejects file exactly equal to maxUploadBytes is also accepted (kills L56 EqualityOperator >= mutant on the size guard)", () => {
		// boundary: byteLength === maxUploadBytes is allowed (the guard uses >).
		// Mutated `>= maxUploadBytes`: rejects exactly-at-limit uploads.
		const exactlyMax = new Uint8Array(10 * 1024 * 1024);
		const result = buildLocalMediaDescriptor({
			filename: "limit.png",
			bytes: exactlyMax,
		});
		expect(result.ok).toBe(true);
	});

	it("treats a no-extension filename as disallowed via the '.bin' fallback (kills L60 StringLiteral '.bin' → '')", () => {
		// path.extname("noext") === "" → || ".bin" → ".bin" (not in allowedExtensions).
		// Mutant: || "" → still "" → not in allowedExtensions, still rejected. Both yield the
		// same rejection, but the ERROR phrasing path is identical too. To observe the
		// difference, use a filename whose lowercased extname is "" but whose basename ends in
		// something that would change the .extname trip-point. The simplest observable check:
		// after the mutant, allowedExtensions.has("") would let "" through; ensure it stays
		// rejected.
		const result = buildLocalMediaDescriptor({ filename: "noextension", bytes: validPng });
		expect(result).toMatchObject({ ok: false });
		expect((result as { error: string }).error).toContain("not allowed");
	});

	it("collapses runs of non-alphanumerics into single dashes (kills L81 Regex '+' quantifier)", () => {
		// Original /[^a-z0-9]+/gi: runs collapse to a single "-".
		// Mutant /[^a-z0-9]/gi: each non-alphanumeric becomes "-".
		const result = buildLocalMediaDescriptor({
			filename: "my   awesome---photo.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		// Three spaces and three dashes collapse together → exactly one "-" each gap.
		expect(result.asset.title).toBe("my-awesome-photo");
	});

	it("strips leading/trailing dashes from the sanitised basename (kills L82 StringLiteral 'Stryker was here!')", () => {
		// "-foo-.png" → replace strips runs to "-foo-" → strip leading/trailing → "foo".
		// Mutant replaces "" with "Stryker was here!" → "Stryker was here!fooStryker was here!".
		const result = buildLocalMediaDescriptor({
			filename: "-foo-.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(result.asset.title).toBe("foo");
	});

	it("defaults the basename to 'upload' when sanitisation leaves nothing (kills L83 StringLiteral '' fallback)", () => {
		// "---.png" → "-" after run-collapse → "" after edge-trim → falls back via || "upload".
		// Mutant: fallback is "" → title becomes "" (or input.title trimmed).
		const result = buildLocalMediaDescriptor({
			filename: "---.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(result.asset.title).toBe("upload");
	});

	it("trims whitespace from title and altText (kills L99/L100 MethodExpression dropping .trim)", () => {
		const result = buildLocalMediaDescriptor({
			filename: "photo.png",
			bytes: validPng,
			title: "  spaced title  ",
			altText: "  alt with edges  ",
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		// Mutant L99: drops .trim() → title retains leading/trailing spaces.
		// Mutant L100: same for altText.
		expect(result.asset.title).toBe("spaced title");
		expect(result.asset.altText).toBe("alt with edges");
	});

	it("defaults altText to '' when not provided (kills L100 StringLiteral '' → 'Stryker was here!')", () => {
		const result = buildLocalMediaDescriptor({
			filename: "photo.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		// Mutated fallback ?? "Stryker was here!" would produce a non-empty altText.
		expect(result.asset.altText).toBe("");
	});

	it("generates a unique id on each call", () => {
		const r1 = buildLocalMediaDescriptor({
			filename: "a.png",
			bytes: validPng,
		});
		const r2 = buildLocalMediaDescriptor({
			filename: "b.png",
			bytes: validPng,
		});
		expect(r1.ok && r2.ok).toBe(true);
		if (!r1.ok || !r2.ok) return;
		expect(r1.asset.id).not.toBe(r2.asset.id);
	});
});

// ---------------------------------------------------------------------------
// createLocalMediaUpload
// ---------------------------------------------------------------------------

describe("createLocalMediaUpload", () => {
	it("writes the file to disk and returns descriptor", () => {
		const result = createLocalMediaUpload({
			filename: "test.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(existsSync(result.asset.diskPath)).toBe(true);
	});

	it("writes file with owner-only permissions (mode 0o600)", () => {
		const result = createLocalMediaUpload({
			filename: "perm.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		const stat = statSync(result.asset.diskPath);
		// Mode includes file type bits; mask to permission bits only
		expect(stat.mode & 0o777).toBe(0o600);
	});

	it("propagates validation errors without writing to disk (kills L104 ConditionalExpression:false & BlockStatement)", () => {
		// Mutant L104 ConditionalExpression:false / BlockStatement {}: the early
		// `return descriptor` is skipped, so writeFileSync runs even for a rejected
		// upload — leaving a stray file in the uploads dir.
		const before = readdirSync(testUploadsDir);
		const result = createLocalMediaUpload({
			filename: "bad.exe",
			bytes: validPng,
		});
		expect(result).toMatchObject({ ok: false });
		expect(readdirSync(testUploadsDir)).toEqual(before);
	});
});

// ---------------------------------------------------------------------------
// deleteLocalMediaUpload
// ---------------------------------------------------------------------------

describe("deleteLocalMediaUpload", () => {
	it("deletes a file written to the uploads dir", () => {
		const result = createLocalMediaUpload({
			filename: "del.png",
			bytes: validPng,
		});
		if (!result.ok) return;
		expect(existsSync(result.asset.diskPath)).toBe(true);
		deleteLocalMediaUpload(result.asset.publicPath);
		expect(existsSync(result.asset.diskPath)).toBe(false);
	});

	it("only deletes paths under /images/uploads/ (kills L126 ConditionalExpression:false, StringLiteral '' on the prefix check, and L126 BlockStatement {} on the body)", () => {
		// Write a file outside the uploads dir into the testUploadsDir tree but reference it
		// via a non-/images/uploads path. The guard must return without unlinking.
		const result = createLocalMediaUpload({
			filename: "stay.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		// Try to delete via a path that doesn't start with the prefix.
		deleteLocalMediaUpload("/other/area/stay.png");
		expect(existsSync(result.asset.diskPath)).toBe(true);
		// Now delete via the legitimate path — file should be removed.
		deleteLocalMediaUpload(result.asset.publicPath);
		expect(existsSync(result.asset.diskPath)).toBe(false);
	});

	it("is a no-op for paths outside the uploads dir", () => {
		// Should not throw
		expect(() => deleteLocalMediaUpload("/etc/passwd")).not.toThrow();
		expect(() => deleteLocalMediaUpload("relative/path/file.png")).not.toThrow();
	});

	it("is a no-op for non-existent files (no throw)", () => {
		expect(() => deleteLocalMediaUpload("/images/uploads/does-not-exist-12345.png")).not.toThrow();
	});

	it("does not unlink a file when the path's basename collides but the prefix is wrong (kills L115 ConditionalExpression:false, StringLiteral '', BlockStatement)", () => {
		// The guard rejects any path not under /images/uploads/. Mutants that disable
		// the early return (ConditionalExpression:false, BlockStatement {}) or that
		// make startsWith("") always-true would fall through to unlinkSync on the
		// real stored file, since basename here equals the actual stored filename.
		const result = createLocalMediaUpload({
			filename: "keep.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		deleteLocalMediaUpload(`/elsewhere/${result.asset.storedFilename}`);
		expect(existsSync(result.asset.diskPath)).toBe(true);
	});
});

tests/integration-secret-envelope.test.t.source:
import { describe, expect, it } from "vitest";
import {
	envelopeSerializedLength,
	IntegrationSecretError,
	openIntegrationSecret,
	type SealedSecret,
	sealIntegrationSecret,
} from "../src/integration-secret-envelope";

const ROOT = "root-secret-current-do-not-use-in-prod";
const PREV = "root-secret-previous-do-not-use-in-prod";

const CTX = { domain: "newsletter", provider: "listmonk" } as const;
const FIELDS = { apiKey: "lm-key-CANARY", baseUrl: "https://example.test" };

describe("integration-secret-envelope", () => {
	it("round-trips: seal → open returns identical fields", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		const opened = await openIntegrationSecret(sealed, CTX, { current: ROOT });
		expect(opened.fields).toEqual(FIELDS);
		expect(opened.usedKid).toBe("current");
	});

	it("tags fresh seals with kid=current", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		expect(sealed.kid).toBe("current");
		expect(sealed.v).toBe(1);
	});

	it("AAD binds to (domain, provider) — wrong provider fails decrypt", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		await expect(
			openIntegrationSecret(
				sealed,
				{ domain: "newsletter", provider: "mailchimp" },
				{ current: ROOT },
			),
		).rejects.toThrow(IntegrationSecretError);
	});

	it("AAD binds to (domain, provider) — wrong domain fails decrypt", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		await expect(
			openIntegrationSecret(
				sealed,
				{ domain: "analytics", provider: "listmonk" },
				{ current: ROOT },
			),
		).rejects.toThrow(IntegrationSecretError);
	});

	it("tampered ciphertext throws DECRYPT_FAILED", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		const tampered: SealedSecret = {
			...sealed,
			ciphertext: flipFirstByte(sealed.ciphertext),
		};
		await expect(openIntegrationSecret(tampered, CTX, { current: ROOT })).rejects.toMatchObject({
			code: "DECRYPT_FAILED",
		});
	});

	it("tampered dek_wrap throws DECRYPT_FAILED", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		const tampered: SealedSecret = {
			...sealed,
			dek_wrap: flipFirstByte(sealed.dek_wrap),
		};
		await expect(openIntegrationSecret(tampered, CTX, { current: ROOT })).rejects.toMatchObject({
			code: "DECRYPT_FAILED",
		});
	});

	it("tampered IVs throw DECRYPT_FAILED", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		const wrapTampered: SealedSecret = {
			...sealed,
			wrap_iv: flipFirstByte(sealed.wrap_iv),
		};
		await expect(openIntegrationSecret(wrapTampered, CTX, { current: ROOT })).rejects.toMatchObject(
			{ code: "DECRYPT_FAILED" },
		);
		const dataTampered: SealedSecret = {
			...sealed,
			data_iv: flipFirstByte(sealed.data_iv),
		};
		await expect(openIntegrationSecret(dataTampered, CTX, { current: ROOT })).rejects.toMatchObject(
			{ code: "DECRYPT_FAILED" },
		);
	});

	it("opens against previous key when current rejects", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, PREV);
		// Mark as previous-rooted so the opener knows which slot to try.
		const rotated: SealedSecret = { ...sealed, kid: "previous" };
		const opened = await openIntegrationSecret(rotated, CTX, {
			current: ROOT,
			previous: PREV,
		});
		expect(opened.fields).toEqual(FIELDS);
		expect(opened.usedKid).toBe("previous");
	});

	it("falls back across slots when sealed.kid points at a missing key", async () => {
		// Seal under the current key but mislabel the kid as "previous"
		// (simulating a corrupted record). Open should still succeed by
		// trying both slots.
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		const mislabeled: SealedSecret = { ...sealed, kid: "previous" };
		const opened = await openIntegrationSecret(mislabeled, CTX, {
			current: ROOT,
			previous: PREV,
		});
		expect(opened.fields).toEqual(FIELDS);
		expect(opened.usedKid).toBe("current");
	});

	it("rejects when neither key matches", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		await expect(
			openIntegrationSecret(sealed, CTX, {
				current: "not-the-key",
				previous: "also-not-the-key",
			}),
		).rejects.toMatchObject({ code: "DECRYPT_FAILED" });
	});

	it("rejects unknown envelope version", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		const future = { ...sealed, v: 999 } as unknown as SealedSecret;
		await expect(openIntegrationSecret(future, CTX, { current: ROOT })).rejects.toMatchObject({
			code: "INVALID_ENVELOPE",
		});
	});

	it("rejects an invalid kid value", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		const broken = { ...sealed, kid: "antique" } as unknown as SealedSecret;
		await expect(openIntegrationSecret(broken, CTX, { current: ROOT })).rejects.toMatchObject({
			code: "INVALID_ENVELOPE",
		});
	});

	it("rejects empty rootSecret on seal", async () => {
		await expect(sealIntegrationSecret(FIELDS, CTX, "")).rejects.toMatchObject({
			code: "INVALID_ENVELOPE",
		});
	});

	it("two seals of identical input differ in nonces and ciphertext", async () => {
		const a = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		const b = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		expect(a.wrap_iv).not.toBe(b.wrap_iv);
		expect(a.data_iv).not.toBe(b.data_iv);
		expect(a.wrap_salt).not.toBe(b.wrap_salt);
		expect(a.dek_wrap).not.toBe(b.dek_wrap);
		expect(a.ciphertext).not.toBe(b.ciphertext);
	});

	it("base64 fields contain only standard base64 alphabet", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		const safe = /^[A-Za-z0-9+/=]+$/;
		for (const field of [
			sealed.wrap_salt,
			sealed.wrap_iv,
			sealed.dek_wrap,
			sealed.data_iv,
			sealed.ciphertext,
		]) {
			expect(field).toMatch(safe);
		}
	});

	it("envelope JSON shape has exactly the documented keys", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		expect(Object.keys(sealed).sort()).toEqual(
			["ciphertext", "data_iv", "dek_wrap", "kid", "v", "wrap_iv", "wrap_salt"].sort(),
		);
	});

	it("serialized envelope stays well under D1's 1MiB row budget", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		expect(envelopeSerializedLength(sealed)).toBeLessThan(1024);
	});

	it("rejects payload sealed as a primitive (not an object)", async () => {
		const sealed = await sealIntegrationSecret(
			"not-an-object" as unknown as Record<string, string>,
			CTX,
			ROOT,
		);
		await expect(openIntegrationSecret(sealed, CTX, { current: ROOT })).rejects.toMatchObject({
			code: "INVALID_PLAINTEXT",
		});
	});

	it("rejects payload sealed as null (typeof object but falsy)", async () => {
		const sealed = await sealIntegrationSecret(
			null as unknown as Record<string, string>,
			CTX,
			ROOT,
		);
		await expect(openIntegrationSecret(sealed, CTX, { current: ROOT })).rejects.toMatchObject({
			code: "INVALID_PLAINTEXT",
		});
	});

	it("rejects payload sealed as an array", async () => {
		const sealed = await sealIntegrationSecret(
			["a", "b"] as unknown as Record<string, string>,
			CTX,
			ROOT,
		);
		await expect(openIntegrationSecret(sealed, CTX, { current: ROOT })).rejects.toMatchObject({
			code: "INVALID_PLAINTEXT",
		});
	});

	it("rejects payload with a non-string value", async () => {
		const sealed = await sealIntegrationSecret(
			{ apiKey: 123 } as unknown as Record<string, string>,
			CTX,
			ROOT,
		);
		await expect(openIntegrationSecret(sealed, CTX, { current: ROOT })).rejects.toMatchObject({
			code: "INVALID_PLAINTEXT",
		});
	});

	it("INVALID_ENVELOPE error messages name the offending field", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		const future = { ...sealed, v: 999 } as unknown as SealedSecret;
		const broken = { ...sealed, kid: "antique" } as unknown as SealedSecret;
		await expect(openIntegrationSecret(future, CTX, { current: ROOT })).rejects.toMatchObject({
			message: expect.stringContaining("envelope version"),
		});
		await expect(openIntegrationSecret(broken, CTX, { current: ROOT })).rejects.toMatchObject({
			message: expect.stringContaining("envelope kid"),
		});
	});

	it("DECRYPT_FAILED error message names domain/provider context", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		await expect(openIntegrationSecret(sealed, CTX, { current: "bad-key" })).rejects.toMatchObject({
			message: expect.stringMatching(/newsletter\/listmonk/),
		});
	});

	it("seal() error message names the function on empty rootSecret", async () => {
		await expect(sealIntegrationSecret(FIELDS, CTX, "")).rejects.toMatchObject({
			message: expect.stringContaining("sealIntegrationSecret"),
		});
	});

	it("base64 round-trip survives every padding length (0/1/2 chars)", async () => {
		const cases = [
			{ apiKey: "" },
			{ apiKey: "x" },
			{ apiKey: "xx" },
			{ apiKey: "xxx" },
			{ apiKey: "xxxxx" },
		];
		for (const fields of cases) {
			const sealed = await sealIntegrationSecret(fields, CTX, ROOT);
			const opened = await openIntegrationSecret(sealed, CTX, {
				current: ROOT,
			});
			expect(opened.fields).toEqual(fields);
		}
	});

	it("opens against current when sealed.kid='previous' but only current matches", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		const mislabeled: SealedSecret = { ...sealed, kid: "previous" };
		const opened = await openIntegrationSecret(mislabeled, CTX, {
			current: ROOT,
		});
		expect(opened.fields).toEqual(FIELDS);
		expect(opened.usedKid).toBe("current");
	});

	it("rejects when sealed.kid='previous' and only current is supplied and doesn't match", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, PREV);
		const labeled: SealedSecret = { ...sealed, kid: "previous" };
		await expect(openIntegrationSecret(labeled, CTX, { current: ROOT })).rejects.toMatchObject({
			code: "DECRYPT_FAILED",
		});
	});

	it("thrown errors carry name='IntegrationSecretError'", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		try {
			await openIntegrationSecret(sealed, CTX, { current: "wrong" });
			throw new Error("expected throw");
		} catch (err) {
			expect((err as Error).name).toBe("IntegrationSecretError");
		}
	});

	it("DECRYPT_FAILED on tampered ciphertext mentions 'authentication failed'", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		const tampered: SealedSecret = {
			...sealed,
			ciphertext: flipFirstByte(sealed.ciphertext),
		};
		await expect(openIntegrationSecret(tampered, CTX, { current: ROOT })).rejects.toMatchObject({
			message: expect.stringContaining("authentication failed"),
		});
	});

	it("DECRYPT_FAILED on no-key-match mentions 'unable to decrypt'", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		await expect(openIntegrationSecret(sealed, CTX, { current: "wrong" })).rejects.toMatchObject({
			message: expect.stringContaining("unable to decrypt"),
		});
	});

	it("INVALID_PLAINTEXT (non-object) mentions 'flat string-valued object'", async () => {
		const sealed = await sealIntegrationSecret(
			"not-an-object" as unknown as Record<string, string>,
			CTX,
			ROOT,
		);
		await expect(openIntegrationSecret(sealed, CTX, { current: ROOT })).rejects.toMatchObject({
			message: expect.stringContaining("flat string-valued object"),
		});
	});

	it("rejects payload with mixed-type values (one string, one number)", async () => {
		// Targets the `Object.values(...).some()` predicate: a `.every()` mutant
		// would let this mixed payload through; `.some()` correctly flags it.
		const sealed = await sealIntegrationSecret(
			{ apiKey: "ok", count: 7 } as unknown as Record<string, string>,
			CTX,
			ROOT,
		);
		await expect(openIntegrationSecret(sealed, CTX, { current: ROOT })).rejects.toMatchObject({
			code: "INVALID_PLAINTEXT",
		});
	});

	it("opens with only previous slot supplied (no current key)", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, PREV);
		const labeled: SealedSecret = { ...sealed, kid: "previous" };
		const opened = await openIntegrationSecret(labeled, CTX, {
			previous: PREV,
		} as { current: string; previous?: string });
		expect(opened.fields).toEqual(FIELDS);
		expect(opened.usedKid).toBe("previous");
	});

	it("envelope JSON encoding has the documented keys with correct types", async () => {
		const sealed = await sealIntegrationSecret(FIELDS, CTX, ROOT);
		const json = JSON.stringify(sealed);
		expect(json).toContain('"v":1');
		expect(json).toContain('"kid":"current"');
		expect(json).toMatch(/"wrap_salt":"[A-Za-z0-9+/=]+"/);
		expect(json).toMatch(/"wrap_iv":"[A-Za-z0-9+/=]+"/);
		expect(json).toMatch(/"dek_wrap":"[A-Za-z0-9+/=]+"/);
		expect(json).toMatch(/"data_iv":"[A-Za-z0-9+/=]+"/);
		expect(json).toMatch(/"ciphertext":"[A-Za-z0-9+/=]+"/);
	});
});

function flipFirstByte(b64url: string): string {
	const padded = b64url.replace(/-/g, "+").replace(/_/g, "/");
	const padLen = (4 - (padded.length % 4)) % 4;
	const binary = atob(padded + "=".repeat(padLen));
	const bytes = new Uint8Array(binary.length);
	for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
	bytes[0] ^= 0x01;
	let out = "";
	for (const byte of bytes) out += String.fromCharCode(byte);
	return btoa(out).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

tests/hosted-provider.contract.test.ts.source:
import { mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
	createAstropressAppwriteAdapter,
	createAstropressAppwriteHostedAdapter,
	createAstropressHostedAdapter,
	createAstropressHostedPlatformAdapter,
	createAstropressNeonHostedAdapter,
	createAstropressNhostHostedAdapter,
	createAstropressPocketbaseAdapter,
	createAstropressPocketbaseHostedAdapter,
	createAstropressSupabaseHostedAdapter,
	createAstropressTursoHostedAdapter,
	readAstropressAppwriteHostedConfig,
	readAstropressNeonHostedConfig,
	readAstropressNhostHostedConfig,
	readAstropressPocketbaseHostedConfig,
	readAstropressSupabaseHostedConfig,
	readAstropressTursoHostedConfig,
	resolveAstropressHostedProvider,
} from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";
import {
	createAstropressAppwriteHostedAdapter as createDirectAppwriteHostedAdapter,
	readAstropressAppwriteHostedConfig as readDirectAppwriteHostedConfig,
} from "../src/adapters/appwrite.js";
import { createAstropressLocalAdapter } from "../src/adapters/local.js";
import {
	createAstropressPocketbaseHostedAdapter as createDirectPocketbaseHostedAdapter,
	readAstropressPocketbaseHostedConfig as readDirectPocketbaseHostedConfig,
} from "../src/adapters/pocketbase.js";
import {
	createAstropressSupabaseHostedAdapter as createDirectSupabaseHostedAdapter,
	readAstropressSupabaseHostedConfig as readDirectSupabaseHostedConfig,
} from "../src/adapters/supabase.js";
import { createHostedStores } from "./helpers/provider-test-fixtures.js";

describe("hosted provider contracts", () => {
	it("lets Appwrite and PocketBase use explicit hosted store modules", async () => {
		const hosted = createAstropressHostedPlatformAdapter({
			providerName: "custom",
			...createHostedStores(),
		});
		const appwrite = createAstropressAppwriteAdapter({
			backingAdapter: hosted,
		});
		const pocketbase = createAstropressPocketbaseAdapter({
			backingAdapter: hosted,
		});

		await appwrite.content.save({
			id: "custom-remote-post",
			kind: "post",
			slug: "custom-remote-post",
			status: "published",
			title: "Custom remote post",
		});

		expect(await appwrite.content.get("custom-remote-post")).toMatchObject({
			slug: "custom-remote-post",
			title: "Custom remote post",
		});
		expect(await appwrite.auth.signIn("admin@example.com", "password")).toMatchObject({
			email: "admin@example.com",
			role: "admin",
		});
		expect(await pocketbase.content.get("custom-remote-post")).toMatchObject({
			slug: "custom-remote-post",
			title: "Custom remote post",
		});
	});

	it("creates Supabase hosted adapters with package-owned remote api defaults", async () => {
		const supabaseConfig = readDirectSupabaseHostedConfig({
			SUPABASE_URL: "https://demo.supabase.co",
			SUPABASE_SERVICE_ROLE_KEY: "service",
		});

		const supabase = createDirectSupabaseHostedAdapter({
			config: supabaseConfig,
			fetchImpl: async () => new Response(JSON.stringify([]), { status: 200 }),
		});

		expect(supabaseConfig.apiBaseUrl).toContain("demo.supabase.co/functions/v1/astropress");
		expect((await supabase.preview?.create({ recordId: "hello" }))?.url).toContain(
			"demo.supabase.co/preview/preview/hello",
		);
		expect(supabase.capabilities.hostedAdmin).toBe(true);
	});

	it("creates Appwrite and PocketBase hosted adapters with package-owned remote api defaults", async () => {
		const appwriteConfig = readDirectAppwriteHostedConfig({
			APPWRITE_ENDPOINT: "https://cloud.appwrite.io/v1",
			APPWRITE_PROJECT_ID: "project-123",
			APPWRITE_API_KEY: "secret",
		});
		const pocketbaseConfig = readDirectPocketbaseHostedConfig({
			POCKETBASE_URL: "https://pocketbase.example.com",
			POCKETBASE_EMAIL: "admin@example.com",
			POCKETBASE_PASSWORD: "secret",
		});

		const appwrite = createDirectAppwriteHostedAdapter({
			config: appwriteConfig,
			fetchImpl: async () => new Response(JSON.stringify([]), { status: 200 }),
		});
		const pocketbase = createDirectPocketbaseHostedAdapter({
			config: pocketbaseConfig,
			fetchImpl: async () => new Response(JSON.stringify([]), { status: 200 }),
		});

		expect(appwriteConfig.apiBaseUrl).toContain("cloud.appwrite.io/v1/functions/astropress");
		expect((await appwrite.preview?.create({ recordId: "hello" }))?.url).toContain(
			"cloud.appwrite.io/v1/console/project-project-123/preview/preview/hello",
		);
		expect(pocketbaseConfig.apiBaseUrl).toContain("pocketbase.example.com/api/astropress");
		expect((await pocketbase.preview?.create({ recordId: "hello" }))?.url).toContain(
			"pocketbase.example.com/preview",
		);
	});

	it("reads hosted provider config from env maps", () => {
		expect(
			readAstropressSupabaseHostedConfig({
				SUPABASE_URL: "https://example.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "service",
			}),
		).toEqual({
			url: "https://example.supabase.co",
			serviceRoleKey: "service",
			apiBaseUrl: "https://example.supabase.co/functions/v1/astropress",
		});
		expect(
			readAstropressAppwriteHostedConfig({
				APPWRITE_ENDPOINT: "https://cloud.appwrite.io/v1",
				APPWRITE_PROJECT_ID: "project-123",
				APPWRITE_API_KEY: "secret",
			}),
		).toEqual({
			endpoint: "https://cloud.appwrite.io/v1",
			projectId: "project-123",
			apiKey: "secret",
			apiBaseUrl: "https://cloud.appwrite.io/v1/functions/astropress",
			previewBaseUrl: "https://cloud.appwrite.io/v1/console/project-project-123",
		});
		expect(
			readAstropressPocketbaseHostedConfig({
				POCKETBASE_URL: "https://pocketbase.example.com",
				POCKETBASE_EMAIL: "admin@example.com",
				POCKETBASE_PASSWORD: "secret",
			}),
		).toEqual({
			url: "https://pocketbase.example.com",
			email: "admin@example.com",
			password: "secret",
			apiBaseUrl: "https://pocketbase.example.com/api/astropress",
			previewBaseUrl: "https://pocketbase.example.com",
		});
		expect(
			readAstropressNhostHostedConfig({
				NHOST_SUBDOMAIN: "abcdefgh",
				NHOST_REGION: "eu-central-1",
				NHOST_ADMIN_SECRET: "secret",
			}),
		).toEqual({
			subdomain: "abcdefgh",
			region: "eu-central-1",
			adminSecret: "secret",
			apiBaseUrl: "https://abcdefgh.eu-central-1.nhost.run/v1/functions/astropress",
			previewBaseUrl: "https://abcdefgh.eu-central-1.nhost.run/console",
		});
		expect(
			readAstropressNeonHostedConfig({
				NEON_DATABASE_URL: "postgres://user:pass@ep-example.us-east-1.aws.neon.tech/neondb",
				NEON_PROJECT_ID: "proj-quiet-moon-123456",
			}),
		).toEqual({
			databaseUrl: "postgres://user:pass@ep-example.us-east-1.aws.neon.tech/neondb",
			projectId: "proj-quiet-moon-123456",
			apiBaseUrl: "https://console.neon.tech/app/projects/proj-quiet-moon-123456",
		});
		expect(
			readAstropressTursoHostedConfig({
				TURSO_DATABASE_URL: "libsql://astropress-prod.turso.io",
				TURSO_AUTH_TOKEN: "secret",
			}),
		).toEqual({
			databaseUrl: "libsql://astropress-prod.turso.io",
			authToken: "secret",
			apiBaseUrl: "https://app.turso.tech/databases/astropress-prod",
		});
	});

	it("guards hosted provider config and builds hosted adapters with preview URLs", async () => {
		expect(() => readAstropressSupabaseHostedConfig({})).toThrow(/SUPABASE_URL/);
		expect(() => readAstropressAppwriteHostedConfig({})).toThrow(/APPWRITE_ENDPOINT/);
		expect(() => readAstropressPocketbaseHostedConfig({})).toThrow(/POCKETBASE_URL/);
		expect(() => readAstropressNhostHostedConfig({})).toThrow(/NHOST_SUBDOMAIN/);
		expect(() => readAstropressNeonHostedConfig({})).toThrow(/NEON_DATABASE_URL|DATABASE_URL/);
		expect(() => readAstropressTursoHostedConfig({})).toThrow(/TURSO_DATABASE_URL/);

		const hostedStores = createHostedStores();
		const supabase = createAstropressSupabaseHostedAdapter({
			env: {
				SUPABASE_URL: "https://example.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "service",
			},
			...hostedStores,
		});
		const appwrite = createAstropressAppwriteHostedAdapter({
			env: {
				APPWRITE_ENDPOINT: "https://cloud.appwrite.io/v1",
				APPWRITE_PROJECT_ID: "project-123",
				APPWRITE_API_KEY: "secret",
			},
			...hostedStores,
		});
		const pocketbase = createAstropressPocketbaseHostedAdapter({
			env: {
				POCKETBASE_URL: "https://pocketbase.example.com",
				POCKETBASE_EMAIL: "admin@example.com",
				POCKETBASE_PASSWORD: "secret",
			},
			...hostedStores,
		});
		const nhost = createAstropressNhostHostedAdapter({
			env: {
				NHOST_SUBDOMAIN: "abcdefgh",
				NHOST_REGION: "eu-central-1",
				NHOST_ADMIN_SECRET: "secret",
			},
			...hostedStores,
		});
		const neon = createAstropressNeonHostedAdapter({
			env: {
				NEON_DATABASE_URL: "postgres://user:pass@ep-example.us-east-1.aws.neon.tech/neondb",
			},
			...hostedStores,
		});
		const turso = createAstropressTursoHostedAdapter({
			env: {
				TURSO_DATABASE_URL: "libsql://astropress-prod.turso.io",
				TURSO_AUTH_TOKEN: "secret",
			},
			...hostedStores,
		});

		await supabase.content.save({
			id: "hosted-config-post",
			kind: "post",
			slug: "hosted-config-post",
			status: "published",
			title: "Hosted config post",
		});

		expect(await supabase.preview?.create({ recordId: "hosted-config-post" })).toEqual({
			url: "https://example.supabase.co/preview",
		});
		expect(await appwrite.preview?.create({ recordId: "hosted-config-post" })).toEqual({
			url: "https://cloud.appwrite.io/v1/console/project-project-123/preview",
		});
		expect(await pocketbase.preview?.create({ recordId: "hosted-config-post" })).toEqual({
			url: "https://pocketbase.example.com/preview",
		});
		expect(await nhost.preview?.create({ recordId: "hosted-config-post" })).toEqual({
			url: "https://abcdefgh.eu-central-1.nhost.run/console/preview",
		});
		expect(neon.capabilities.hostedAdmin).toBe(false);
		expect(await turso.preview?.create({ recordId: "hosted-config-post" })).toBeUndefined();
	});

	it("selects hosted providers from explicit options or env", async () => {
		expect(resolveAstropressHostedProvider(undefined)).toBe("supabase");
		expect(resolveAstropressHostedProvider("appwrite")).toBe("appwrite");
		expect(resolveAstropressHostedProvider("pocketbase")).toBe("pocketbase");
		expect(resolveAstropressHostedProvider("nhost")).toBe("nhost");
		expect(resolveAstropressHostedProvider("neon")).toBe("neon");
		expect(resolveAstropressHostedProvider("turso")).toBe("turso");
		expect(resolveAstropressHostedProvider("unexpected")).toBe("supabase");

		const hostedStores = createHostedStores();
		const supabase = createAstropressHostedAdapter({
			env: {
				SUPABASE_URL: "https://selector.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "service",
			},
			...hostedStores,
		});

		const appwrite = createAstropressHostedAdapter({
			provider: "appwrite",
			env: {
				APPWRITE_ENDPOINT: "https://cloud.appwrite.io/v1",
				APPWRITE_PROJECT_ID: "selector-appwrite",
				APPWRITE_API_KEY: "secret",
			},
			content: hostedStores.content,
			media: hostedStores.media,
			revisions: hostedStores.revisions,
			auth: hostedStores.auth,
		});
		const pocketbase = createAstropressHostedAdapter({
			provider: "pocketbase",
			env: {
				POCKETBASE_URL: "https://pocketbase.example.com",
				POCKETBASE_EMAIL: "admin@example.com",
				POCKETBASE_PASSWORD: "secret",
			},
			content: hostedStores.content,
			media: hostedStores.media,
			revisions: hostedStores.revisions,
			auth: hostedStores.auth,
		});
		const nhost = createAstropressHostedAdapter({
			provider: "nhost",
			env: {
				NHOST_SUBDOMAIN: "abcdefgh",
				NHOST_REGION: "eu-central-1",
				NHOST_ADMIN_SECRET: "secret",
			},
			content: hostedStores.content,
			media: hostedStores.media,
			revisions: hostedStores.revisions,
			auth: hostedStores.auth,
		});
		const neon = createAstropressHostedAdapter({
			provider: "neon",
			env: {
				NEON_DATABASE_URL: "postgres://user:pass@ep-example.us-east-1.aws.neon.tech/neondb",
			},
			content: hostedStores.content,
			media: hostedStores.media,
			revisions: hostedStores.revisions,
			auth: hostedStores.auth,
		});
		const turso = createAstropressHostedAdapter({
			provider: "turso",
			env: {
				TURSO_DATABASE_URL: "libsql://astropress-prod.turso.io",
				TURSO_AUTH_TOKEN: "secret",
			},
			content: hostedStores.content,
			media: hostedStores.media,
			revisions: hostedStores.revisions,
			auth: hostedStores.auth,
		});

		expect(supabase.capabilities.name).toBe("supabase");
		expect(appwrite.capabilities.objectStorage).toBe(true);
		expect(pocketbase.capabilities.database).toBe(true);
		expect(nhost.capabilities.name).toBe("nhost");
		expect(neon.capabilities.database).toBe(true);
		expect(turso.capabilities.name).toBe("turso");
		expect(await supabase.preview?.create({ recordId: "x" })).toEqual({
			url: "https://selector.supabase.co/preview",
		});
		expect(await appwrite.preview?.create({ recordId: "x" })).toEqual({
			url: "https://cloud.appwrite.io/v1/console/project-selector-appwrite/preview",
		});
		expect(await pocketbase.preview?.create({ recordId: "x" })).toEqual({
			url: "https://pocketbase.example.com/preview",
		});
		expect(await nhost.preview?.create({ recordId: "x" })).toEqual({
			url: "https://abcdefgh.eu-central-1.nhost.run/console/preview",
		});
	});

	it("selects local and hosted providers from explicit env maps", async () => {
		const localSupabase = createAstropressLocalAdapter({
			env: {
				ASTROPRESS_LOCAL_PROVIDER: "supabase",
			},
			workspaceRoot: await mkdtemp(join(tmpdir(), "astropress-local-env-")),
			dbPath: join(tmpdir(), `astropress-local-env-${Date.now()}.sqlite`),
		});

		expect(localSupabase.capabilities.name).toBe("supabase");
	});
});

tests/d1-store-taxonomies.test.ts.source:
// Direct mutation-coverage tests for d1-store-taxonomies.ts.
// The store factories are exercised end-to-end through the
// SqliteBackedD1Database fixture so insert/select/error paths and the
// exact error-string returns are all observable.
import { beforeEach, describe, expect, it } from "vitest";

import {
	createD1AuthorsMutationPart,
	createD1AuthorsReadPart,
	createD1TaxonomiesMutationPart,
	createD1TaxonomiesReadPart,
} from "../src/d1-store-taxonomies";
import { makeDb } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

let d1: SqliteBackedD1Database;
let db: ReturnType<typeof makeDb>;

beforeEach(() => {
	db = makeDb();
	d1 = new SqliteBackedD1Database(db);
});

describe("createD1AuthorsReadPart.listAuthors", () => {
	it("maps every column and orders by name COLLATE NOCASE", async () => {
		db.prepare("INSERT INTO authors (slug, name, bio) VALUES (?, ?, ?)").run("b", "bob", "B-bio");
		db.prepare("INSERT INTO authors (slug, name, bio) VALUES (?, ?, ?)").run(
			"a",
			"Alice",
			null as unknown as string,
		);
		const result = await createD1AuthorsReadPart(d1).listAuthors();
		expect(result.map((r) => r.name)).toEqual(["Alice", "bob"]);
		const alice = result[0];
		expect(alice).toMatchObject({ slug: "a", name: "Alice" });
		expect(alice.bio).toBeUndefined();
		expect(typeof alice.createdAt).toBe("string");
		expect(typeof alice.updatedAt).toBe("string");
		expect(typeof alice.id).toBe("number");
		const bob = result[1];
		expect(bob.bio).toBe("B-bio");
	});

	it("filters out soft-deleted authors", async () => {
		db.prepare(
			"INSERT INTO authors (slug, name, bio, deleted_at) VALUES (?, ?, ?, CURRENT_TIMESTAMP)",
		).run("d", "Deleted", null as unknown as string);
		db.prepare("INSERT INTO authors (slug, name, bio) VALUES (?, ?, ?)").run("k", "Keep", null);
		const result = await createD1AuthorsReadPart(d1).listAuthors();
		expect(result.map((r) => r.name)).toEqual(["Keep"]);
	});
});

