/**
 * Contract tests for HTML sanitization.
 *
 * Covers: features/contracts/html-sanitization.feature
 *
 * sanitizeHtml() is part of the public rendering contract and must remain
 * available alongside optimizeImageLoading().
 */

import { sanitizeHtml } from "@astropress-diy/astropress";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

describe("html-sanitization.feature: sanitizeHtml() allowlist contract", () => {
	it("strips <script> tags", async () => {
		const input = "<p>Hello</p><script>alert(1)</script>";
		const output = await sanitizeHtml(input);
		expect(output).not.toContain("<script");
		expect(output).not.toContain("alert(1)");
		expect(output).toContain("<p>Hello</p>");
	});

	it("strips event handler attributes (onclick, onmouseover, etc.)", async () => {
		const input = '<a href="/donate" onclick="steal()">Donate</a>';
		const output = await sanitizeHtml(input);
		expect(output).not.toContain("onclick");
		expect(output).not.toContain("steal()");
		expect(output).toContain("Donate");
	});

	it("strips <iframe> tags", async () => {
		const input = '<p>Content</p><iframe src="https://evil.example"></iframe>';
		const output = await sanitizeHtml(input);
		expect(output).not.toContain("<iframe");
		expect(output).toContain("Content");
	});

	it("preserves allowed structural tags: p, h2, ul, li, blockquote", async () => {
		const input = "<h2>Title</h2><p>Text</p><ul><li>Item</li></ul><blockquote>Quote</blockquote>";
		const output = await sanitizeHtml(input);
		expect(output).toContain("<h2>");
		expect(output).toContain("<p>");
		expect(output).toContain("<ul>");
		expect(output).toContain("<li>");
		expect(output).toContain("<blockquote>");
	});

	it("preserves allowed inline tags with safe attributes: strong, em, a[href]", async () => {
		const input = '<strong>Bold</strong><em>Italic</em><a href="/about">Link</a>';
		const output = await sanitizeHtml(input);
		expect(output).toContain("<strong>");
		expect(output).toContain("<em>");
		expect(output).toContain('href="/about"');
	});

	it("strips style= attributes from all elements", async () => {
		const input = '<p style="color:red">Text</p><h2 style="font-size:99px">Title</h2>';
		const output = await sanitizeHtml(input);
		expect(output).not.toContain("style=");
		expect(output).toContain("<p>");
		expect(output).toContain("<h2>");
	});

	it("strips nested disallowed tags inside allowed tags", async () => {
		const input = "<p>Safe text <script>evil()</script> still safe</p>";
		const output = await sanitizeHtml(input);
		expect(output).toContain("<p>");
		expect(output).not.toContain("<script");
		expect(output).not.toContain("evil()");
	});

	it("strips javascript: href values from links", async () => {
		const input = '<a href="javascript:alert(1)">Bad link</a><a href="/safe">Safe link</a>';
		const output = await sanitizeHtml(input);
		expect(output).not.toContain("javascript:");
		expect(output).toContain(">Bad link</a>");
		expect(output).toContain('href="/safe"');
	});

	it("strips data: URL from img src (data URI injection)", async () => {
		const input = '<img src="data:text/html,<script>alert(1)</script>" alt="probe">';
		const output = await sanitizeHtml(input);
		expect(output).not.toContain("data:");
		expect(output).not.toContain("alert(1)");
		// img tag may be present but src must be absent
		if (output.includes("<img")) {
			expect(output).not.toContain('src="');
		}
	});

	it("strips protocol-relative URLs from href (// scheme open redirect)", async () => {
		const input = '<a href="//evil.example/steal">click me</a>';
		const output = await sanitizeHtml(input);
		expect(output).not.toContain("//evil.example");
		expect(output).toContain("click me");
	});

	it("strips SVG tags entirely (SVG XSS vector)", async () => {
		const input = "<svg><script>alert(1)</script><circle r='10'/></svg>";
		const output = await sanitizeHtml(input);
		expect(output).not.toContain("<svg");
		expect(output).not.toContain("<script");
		expect(output).not.toContain("alert(1)");
	});

	it("strips srcset candidates with javascript: scheme while preserving safe candidates", async () => {
		const input = '<img srcset="javascript:alert(1) 1x, /safe.jpg 2x" alt="probe">';
		const output = await sanitizeHtml(input);
		expect(output).not.toContain("javascript:");
		expect(output).toContain("/safe.jpg");
	});

	it("strips deeply nested script inside multiple allowed structural wrappers", async () => {
		const input = "<blockquote><ul><li><p><script>evil()</script></p></li></ul></blockquote>";
		const output = await sanitizeHtml(input);
		expect(output).not.toContain("<script");
		expect(output).not.toContain("evil()");
		expect(output).toContain("<blockquote>");
		expect(output).toContain("<ul>");
		expect(output).toContain("<li>");
		expect(output).toContain("<p>");
	});

	it("strips non-class attributes that have an empty string value", async () => {
		const input = '<img src="/image.jpg" alt="" />';
		const output = await sanitizeHtml(input);
		// The empty alt attribute is removed; src is a safe URL so it stays
		expect(output).toContain("/image.jpg");
		// alt="" (empty non-class attribute) is stripped
		expect(output).not.toMatch(/alt=""/);
	});

	it("removes srcset attribute entirely when all candidates are blocked", async () => {
		const input = '<img srcset="javascript:alert(1) 1x" alt="probe" />';
		const output = await sanitizeHtml(input);
		expect(output).not.toContain("srcset=");
		expect(output).toContain("probe");
	});

	it("preserves empty class attribute (class is the only non-boolean attribute with empty values kept)", async () => {
		const input = '<div class="">content</div>';
		const output = await sanitizeHtml(input);
		expect(output).toMatch(/class=""/);
	});

	it("joins multiple surviving srcset candidates with the literal ', ' separator", async () => {
		const input = '<img srcset="/a.jpg 1x, /b.jpg 2x" alt="x" />';
		const output = await sanitizeHtml(input);
		// Both candidates survive and are joined by ", "
		expect(output).toMatch(/srcset="\/a\.jpg 1x, \/b\.jpg 2x"/);
	});

	it("adds rel=noopener noreferrer to every <a> via the HTMLRewriter path", async () => {
		const output = await sanitizeHtml('<a href="/page">link</a>');
		expect(output).toContain("/page");
		expect(output).toContain('rel="noopener noreferrer"');
	});

	it("rewrites an existing rel value to 'noopener noreferrer' on <a> (overwrite not append)", async () => {
		const output = await sanitizeHtml('<a href="/p" rel="custom">x</a>');
		expect(output).toContain('rel="noopener noreferrer"');
		expect(output).not.toMatch(/rel="custom"/);
	});

	it("does NOT add rel=noopener noreferrer to non-anchor tags", async () => {
		const output = await sanitizeHtml('<span class="link">x</span>');
		expect(output).not.toMatch(/rel="noopener noreferrer"/);
	});

	it("returns true from isAllowedUrl for relative URLs without a scheme (no colon-prefixed scheme match)", async () => {
		// A relative '/foo' URL has no scheme; sanitizer should keep the href.
		const output = await sanitizeHtml('<a href="/relative/path">x</a>');
		expect(output).toContain('href="/relative/path"');
	});

	it("preserves a mailto: link (uses allowedSchemes lowercase match)", async () => {
		const output = await sanitizeHtml('<a href="MAILTO:User@Example.com">contact</a>');
		// scheme lowercased via .toLowerCase(); 'mailto' is in allowedSchemes
		expect(output).toMatch(/href="MAILTO:User@Example\.com"/i);
	});

	it("strips href with a disallowed scheme that has alphanumeric + '+.-' characters", async () => {
		// 'data:' is alphanumeric-only — exercises the [a-zA-Z][a-zA-Z0-9+.-]* scheme regex
		const output = await sanitizeHtml('<a href="data:text/html,<svg/onload=alert(1)>">x</a>');
		expect(output).not.toContain("data:");
	});

	it("trims surrounding whitespace from URL attribute values (href / src)", async () => {
		const output = await sanitizeHtml('<a href="  /trimmed  ">x</a>');
		// The trimmed value is what's checked against isAllowedUrl; trimmed form is written back.
		expect(output).toMatch(/href="\/trimmed"/);
	});

	it("trims srcset candidate whitespace and recomposes with ', ' separator", async () => {
		const output = await sanitizeHtml('<img srcset="  /a.jpg 1x  ,  /b.jpg 2x  " alt="x" />');
		expect(output).toMatch(/srcset="\/a\.jpg 1x, \/b\.jpg 2x"/);
	});

	it("treats a scheme-bearing javascript: prefix with surrounding whitespace as blocked (trim matters)", async () => {
		const output = await sanitizeHtml('<a href="   javascript:alert(1)   ">x</a>');
		expect(output).not.toContain("javascript:");
	});
});

describe("html-sanitization.feature: sanitizeHtml() sanitize-html library fallback (no HTMLRewriter)", () => {
	let saved: typeof globalThis.HTMLRewriter;

	beforeEach(() => {
		saved = globalThis.HTMLRewriter;
		// @ts-expect-error — intentionally removing the polyfill to test the library fallback path
		globalThis.HTMLRewriter = undefined;
	});

	afterEach(() => {
		globalThis.HTMLRewriter = saved;
	});

	it("strips <script> tags via library fallback", async () => {
		const output = await sanitizeHtml("<p>Hello</p><script>alert(1)</script>");
		expect(output).not.toContain("<script");
		expect(output).toContain("<p>Hello</p>");
	});

	it("strips event handler attributes via library fallback", async () => {
		const output = await sanitizeHtml('<a href="/donate" onclick="steal()">Donate</a>');
		expect(output).not.toContain("onclick");
		expect(output).toContain("Donate");
	});

	it("adds rel=noopener noreferrer to links via library fallback", async () => {
		const output = await sanitizeHtml('<a href="/page">Link</a>');
		expect(output).toContain('rel="noopener noreferrer"');
	});

	it("library fallback uses the same allowed-tags list (preserves <p>, drops <iframe>)", async () => {
		const output = await sanitizeHtml("<p>kept</p><iframe>evil</iframe>");
		expect(output).toContain("<p>kept</p>");
		expect(output).not.toContain("<iframe");
	});

	it("library fallback uses the allowedSchemes list (strips javascript: href)", async () => {
		const output = await sanitizeHtml('<a href="javascript:alert(1)">x</a>');
		expect(output).not.toContain("javascript:");
	});

	it("library fallback rejects protocol-relative URLs (allowProtocolRelative: false)", async () => {
		const output = await sanitizeHtml('<a href="//evil.example.com/x">x</a>');
		expect(output).not.toContain("//evil.example.com");
	});
});

describe("html-sanitization.feature: mutation-coverage pins", () => {
	// The scheme regex `/^([a-zA-Z][a-zA-Z0-9+.-]*):/` must match only at the
	// start. Without the `^` anchor a URL like "/some-path:foo" would still
	// match "foo:" and treat it as a scheme — flipping a relative path into
	// a scheme check.
	it("isAllowedUrl treats a path with an internal colon as relative (anchored scheme match)", async () => {
		// "/safe-path:internal" has no scheme at the start. Original
		// schemeMatch is null → returns true (allowed). Mutant (no `^`)
		// matches "internal:" somewhere → asks allowedSchemes for
		// "internal" → false → href stripped.
		const output = await sanitizeHtml('<a href="/safe-path:internal">link</a>');
		expect(output).toContain('href="/safe-path:internal"');
	});

	// sanitizeSrcset's `.filter(Boolean)` drops empty entries left behind by
	// consecutive commas. Without the filter, `[" ", ""]` flows into the
	// subsequent `.filter(c => Boolean(url) && isAllowedUrl(url))` which
	// still rejects them, but the candidate array would carry the
	// blanks if isAllowedUrl returned true on "" — kill the mutant by
	// asserting the joined output has no double-space artefacts.
	it("sanitizeSrcset drops empty candidates from consecutive commas (no leftover blanks)", async () => {
		const output = await sanitizeHtml('<img srcset="/a.jpg 1x,,/b.jpg 2x" alt="x" />');
		// Original: candidates = ["/a.jpg 1x", "/b.jpg 2x"] → joined cleanly.
		expect(output).toMatch(/srcset="\/a\.jpg 1x, \/b\.jpg 2x"/);
		expect(output).not.toMatch(/srcset="[^"]*, ?, ?/);
	});

	// sanitizeSrcset's whitespace split uses `/\s+/` so multi-space gaps
	// between URL and descriptor are handled as a single delimiter. The
	// `+` quantifier matters: `/\s/` (without `+`) would split each
	// individual space, producing empty entries between them, and the
	// first token captured by `.split(/\s/, 1)` would still be the URL
	// — but for srcset values where the URL is followed by tabs/newlines,
	// only the `\s+` form correctly collapses them.
	it("sanitizeSrcset splits URL from descriptor on runs of whitespace, not single chars", async () => {
		// A trailing tab between url and descriptor; `\s+` collapses it.
		// Mutated `\s` would still split at the first \t but the rest of
		// the candidate would re-parse incorrectly.
		const output = await sanitizeHtml('<img srcset="/x.jpg\t\t1x" alt="x" />');
		expect(output).toContain("/x.jpg");
	});
});

tests/sqlite-admin-runtime-auth.test.ts.source:
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { createKmacDigest } from "../src/crypto-primitives.js";
import { hashPassword, isLegacyHash, verifyPassword } from "../src/crypto-utils.js";
import { DEV_ROOT_SECRET_FALLBACK } from "../src/runtime-env.js";
import { createAstropressSqliteAdminRuntime } from "../src/sqlite-admin-runtime.js";
import { makeDb } from "./helpers/make-db.js";
import {
	createRuntimeFixture,
	makePasswordHash,
	type RuntimeFixture,
} from "./helpers/sqlite-admin-runtime-fixture.js";

let fixture: RuntimeFixture;

beforeAll(() => {
	fixture = createRuntimeFixture();
});

afterAll(() => {
	fixture.db.close();
});

// ─── Factory option defaults ──────────────────────────────────────────────────

describe("factory option defaults", () => {
	it("creates runtime with default sessionTtlMs, now, and randomId", () => {
		const rt = createAstropressSqliteAdminRuntime({
			getDatabase: () => fixture.db,
		});
		expect(rt.sqliteAdminStore).toBeDefined();
		expect(rt.sqliteCmsRegistryModule).toBeDefined();
		expect(rt.authenticatePersistedAdminUser).toBeInstanceOf(Function);
	});
});

// ─── Auth ─────────────────────────────────────────────────────────────────────

describe("auth", () => {
	it("returns null for empty email", async () => {
		expect(await fixture.runtime.authenticatePersistedAdminUser("", "correct-password")).toBeNull();
	});

	it("returns null for malformed password hash (verifyPasswordSync malformed-hash branch)", async () => {
		expect(
			await fixture.runtime.authenticatePersistedAdminUser("malformed@test.local", "any-password"),
		).toBeNull();
	});

	it("returns null for wrong password", async () => {
		expect(
			await fixture.runtime.authenticatePersistedAdminUser("admin@test.local", "wrong-password"),
		).toBeNull();
	});

	it("returns user for correct password", async () => {
		const user = await fixture.runtime.authenticatePersistedAdminUser(
			"admin@test.local",
			"correct-password",
		);
		expect(user?.email).toBe("admin@test.local");
		expect(user?.role).toBe("admin");
	});

	it("getSessionUser returns null for null/empty token", () => {
		expect(fixture.store.auth.getSessionUser(null as unknown as string)).toBeNull();
		expect(fixture.store.auth.getSessionUser("")).toBeNull();
	});

	it("getCsrfToken returns null for empty token", () => {
		expect(fixture.store.auth.getCsrfToken("")).toBeNull();
	});

	it("session lifecycle: create → get → getCsrfToken → revoke", async () => {
		const user = await fixture.runtime.authenticatePersistedAdminUser(
			"admin@test.local",
			"correct-password",
		);
		const sessionToken = fixture.store.auth.createSession(user as NonNullable<typeof user>, {
			ipAddress: "127.0.0.1",
		});
		expect(typeof sessionToken).toBe("string");

		const sessionUser = fixture.store.auth.getSessionUser(sessionToken);
		expect(sessionUser?.email).toBe("admin@test.local");

		const csrf = fixture.store.auth.getCsrfToken(sessionToken);
		expect(typeof csrf).toBe("string");

		fixture.store.auth.revokeSession(sessionToken);
		expect(fixture.store.auth.getSessionUser(sessionToken)).toBeNull();
	});

	it("revokeSession with null token is a no-op", () => {
		expect(() => fixture.store.auth.revokeSession(null as unknown as string)).not.toThrow();
	});

	it("getSessionUser returns null for expired session (sessionTtlMs branch)", async () => {
		const expiredDb = makeDb();
		expiredDb
			.prepare(
				"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?2, ?4, 1, CASE WHEN ?3 = 'admin' THEN 1 ELSE 0 END)",
			)
			.run("expired@test.local", makePasswordHash("password"), "admin", "Expired");
		let clockOffset = 0;
		const expiredRuntime = createAstropressSqliteAdminRuntime({
			getDatabase: () => expiredDb,
			sessionTtlMs: 1,
			now: () => Date.now() + clockOffset,
		});
		const user = await expiredRuntime.authenticatePersistedAdminUser(
			"expired@test.local",
			"password",
		);
		const token = expiredRuntime.sqliteAdminStore.auth.createSession(
			user as NonNullable<typeof user>,
			{},
		);
		// Session created under real clock; now advance past the 1ms TTL
		clockOffset = 100_000;
		expect(expiredRuntime.sqliteAdminStore.auth.getSessionUser(token)).toBeNull();
		expiredDb.close();
	});

	it("createPasswordResetToken: unknown user without actor returns ok:true with null resetUrl", () => {
		const result = fixture.store.auth.createPasswordResetToken("nobody@test.local", null);
		expect(result).toMatchObject({ ok: true, resetUrl: null });
	});

	it("createPasswordResetToken: known user returns ok:true with resetUrl", () => {
		const result = fixture.store.auth.createPasswordResetToken("admin@test.local", fixture.actor);
		expect(result.ok).toBe(true);
		if (!result.ok) throw new Error("unreachable");
		expect(result.resetUrl).toContain("token=");
	});

	it("createPasswordResetToken: unknown user with actor returns ok:false", () => {
		const result = fixture.store.auth.createPasswordResetToken("nobody@test.local", fixture.actor);
		expect(result).toMatchObject({ ok: false });
	});

	it("createPasswordResetToken: empty email returns ok:false", () => {
		expect(fixture.store.auth.createPasswordResetToken("", fixture.actor)).toMatchObject({
			ok: false,
		});
	});

	it("getPasswordResetRequest: empty token returns null", () => {
		expect(fixture.store.auth.getPasswordResetRequest("")).toBeNull();
	});

	it("getPasswordResetRequest: invalid token returns null", () => {
		expect(fixture.store.auth.getPasswordResetRequest("invalid-token")).toBeNull();
	});

	it("getInviteRequest: empty token returns null", () => {
		expect(fixture.store.auth.getInviteRequest("")).toBeNull();
	});

	it("getInviteRequest: invalid token returns null", () => {
		expect(fixture.store.auth.getInviteRequest("not-a-real-token")).toBeNull();
	});

	it("consumeInviteToken: short password returns error", () => {
		expect(fixture.store.auth.consumeInviteToken("any-token", "short")).toMatchObject({
			ok: false,
		});
	});

	it("consumeInviteToken: invalid token returns error", () => {
		expect(
			fixture.store.auth.consumeInviteToken("not-a-real-token", "long-enough-password"),
		).toMatchObject({ ok: false });
	});

	it("consumePasswordResetToken: short password returns error", () => {
		expect(fixture.store.auth.consumePasswordResetToken("any-token", "short")).toMatchObject({
			ok: false,
		});
	});

	it("consumePasswordResetToken: invalid token returns error", () => {
		expect(
			fixture.store.auth.consumePasswordResetToken("not-a-real-token", "long-enough-password"),
		).toMatchObject({ ok: false });
	});

	it("full password reset flow: issue, get request, consume", () => {
		const issued = fixture.store.auth.createPasswordResetToken("admin@test.local", fixture.actor);
		expect(issued.ok).toBe(true);
		if (!issued.ok) throw new Error("unreachable");

		const rawToken = decodeURIComponent(issued.resetUrl?.split("token=")[1]);
		const request = fixture.store.auth.getPasswordResetRequest(rawToken);
		expect(request?.email).toBe("admin@test.local");

		const consumed = fixture.store.auth.consumePasswordResetToken(
			rawToken,
			"new-long-password-123",
		);
		expect(consumed.ok).toBe(true);

		expect(fixture.store.auth.getPasswordResetRequest(rawToken)).toBeNull();
	});

	it("full invite flow: create invite, get request, consume", async () => {
		fixture.store.users.inviteAdminUser(
			{ email: "invite-flow@test.local", role: "editor", name: "Invite Flow" },
			fixture.actor,
		);

		const inviteRawToken = "test-invite-raw-token-xyz";
		const tokenHash = createKmacDigest(
			inviteRawToken,
			DEV_ROOT_SECRET_FALLBACK,
			"sqlite-opaque-token",
		);
		const invitedUserId = (
			fixture.db
				.prepare("SELECT id FROM admin_users WHERE email = 'invite-flow@test.local'")
				.get() as { id: number }
		).id;
		fixture.db
			.prepare(
				"INSERT INTO user_invites (id, user_id, token_hash, expires_at, invited_by) VALUES (?, ?, ?, datetime('now', '+7 days'), ?)",
			)
			.run("invite-flow-1", invitedUserId, tokenHash, "admin@test.local");

		const inviteRequest = fixture.store.auth.getInviteRequest(inviteRawToken);
		expect(inviteRequest?.email).toBe("invite-flow@test.local");

		const consumed = fixture.store.auth.consumeInviteToken(
			inviteRawToken,
			"my-new-secure-password",
		);
		expect(consumed.ok).toBe(true);

		expect(fixture.store.auth.getInviteRequest(inviteRawToken)).toBeNull();
	});

	it("recordSuccessfulLogin records an auth audit event", () => {
		expect(() => fixture.store.auth.recordSuccessfulLogin(fixture.actor)).not.toThrow();
	});

	it("recordLogout records an auth audit event", () => {
		expect(() => fixture.store.auth.recordLogout(fixture.actor)).not.toThrow();
	});

	it("getCsrfToken returns null for expired session", { timeout: 60_000 }, async () => {
		const expiredDb = makeDb();
		expiredDb
			.prepare(
				"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?2, ?4, 1, CASE WHEN ?3 = 'admin' THEN 1 ELSE 0 END)",
			)
			.run("expired2@test.local", makePasswordHash("password"), "admin", "Expired2");
		let clockOffset = 0;
		const expiredRuntime = createAstropressSqliteAdminRuntime({
			getDatabase: () => expiredDb,
			sessionTtlMs: 1,
			now: () => Date.now() + clockOffset,
		});
		const user = await expiredRuntime.authenticatePersistedAdminUser(
			"expired2@test.local",
			"password",
		);
		const token = expiredRuntime.sqliteAdminStore.auth.createSession(
			user as NonNullable<typeof user>,
			{},
		);
		// Session created under real clock; now advance past the 1ms TTL
		clockOffset = 100_000;
		expect(expiredRuntime.sqliteAdminStore.auth.getCsrfToken(token)).toBeNull();
		expiredDb.close();
	});
});

// ─── Auth additional branches ─────────────────────────────────────────────────

describe("auth additional branches", () => {
	it("getCsrfToken returns null for revoked session (getSessionUser !row branch)", () => {
		const token = fixture.store.auth.createSession(
			{ email: "admin@test.local", role: "admin" as const, name: "Test Admin" },
			{},
		);
		fixture.store.auth.revokeSession(token);
		expect(fixture.store.auth.getCsrfToken(token)).toBeNull();
	});

	it("createSession throws for unknown user email", () => {
		expect(() =>
			fixture.store.auth.createSession(
				{
					email: "nobody-at-all@test.local",
					role: "admin" as const,
					name: "Nobody",
				},
				{},
			),
		).toThrow();
	});
});

// ─── Password hashing — Argon2id with explicit legacy cutoff ─────────────────

// Use reduced iterations in tests to keep run time under 5 s while still exercising
// the same code paths. The stored format embeds the iteration count, so verifyPassword
// reads it back and uses the same value — the round-trip is still fully verified.
const TEST_ITERATIONS = 1;

describe("password hashing", () => {
	it("hashPassword produces an Argon2id-prefixed hash", async () => {
		const hash = await hashPassword("my-secret-password", 32, TEST_ITERATIONS);
		expect(hash.startsWith("v3:argon2id$")).toBe(true);
	});

	it("hashPassword encodes the work factor in the stored string", async () => {
		const hash = await hashPassword("password", 32, TEST_ITERATIONS);
		const [, iters] = hash.split("$");
		expect(Number(iters)).toBe(TEST_ITERATIONS);
	});

	it("isLegacyHash returns false for an Argon2id hash", async () => {
		const hash = await hashPassword("password", 32, TEST_ITERATIONS);
		expect(isLegacyHash(hash)).toBe(false);
	});

	it("isLegacyHash returns true for a pre-Argon2 password format", () => {
		const legacyHash = "600000$c2FsdA==$aGFzaA==";
		expect(isLegacyHash(legacyHash)).toBe(true);
	});

	it("verifyPassword returns true for a correct Argon2id password", async () => {
		const hash = await hashPassword("correct-password", 32, TEST_ITERATIONS);
		expect(await verifyPassword("correct-password", hash)).toBe(true);
	});

	it("verifyPassword returns false for a wrong Argon2id password", async () => {
		const hash = await hashPassword("correct-password", 32, TEST_ITERATIONS);
		expect(await verifyPassword("wrong-password", hash)).toBe(false);
	});

	it("verifyPassword returns false for a legacy pre-Argon2 password", async () => {
		const legacyHash = "600000$c2FsdA==$aGFzaA==";
		expect(await verifyPassword("wrong-password", legacyHash)).toBe(false);
	});

	it("verifyPassword returns false for a malformed hash string", async () => {
		expect(await verifyPassword("any-password", "not-a-valid-hash")).toBe(false);
	});
});

