import type { DatabaseSync } from "node:sqlite";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { z } from "zod";

import { _resetRegistryForTests, registerProvider } from "../../src/integrations/registry";
import {
	createRequestProviderCache,
	getConnectedProvider,
	listRegisteredProvidersForDomain,
} from "../../src/integrations/runtime";
import {
	createIntegrationsRepository,
	type IntegrationsRepository,
} from "../../src/sqlite-runtime/integrations";
import { makeDb } from "../helpers/make-db.js";

const ROOT = "test-root-current";
const NOW = "2026-05-02T12:00:00.000Z";

let db: DatabaseSync;
let repo: IntegrationsRepository;

const fields = z.object({ apiKey: z.string().min(1) });

beforeEach(() => {
	db = makeDb();
	db.exec("PRAGMA foreign_keys = ON");
	repo = createIntegrationsRepository({
		getDb: () => db as never,
		now: () => NOW,
	});
	_resetRegistryForTests();
	registerProvider("newsletter", {
		id: "listmonk",
		label: "Listmonk",
		fields,
	});
});

afterEach(() => {
	_resetRegistryForTests();
});

describe("getConnectedProvider", () => {
	it("returns the decoded fields for a connected row", async () => {
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: "live-key" },
				now: NOW,
			},
			ROOT,
		);
		const result = await getConnectedProvider({
			domain: "newsletter",
			repo,
			rootSecrets: { current: ROOT },
		});
		expect(result?.providerId).toBe("listmonk");
		expect(result?.fields.apiKey).toBe("live-key");
	});

	it("returns undefined when no row exists for the domain", async () => {
		const result = await getConnectedProvider({
			domain: "analytics",
			repo,
			rootSecrets: { current: ROOT },
		});
		expect(result).toBeUndefined();
	});

	it("returns undefined when only a different domain has a connected row", async () => {
		// Forces the .filter(s.domain === args.domain) predicate to do
		// real work — without it, a connected newsletter row would mask
		// our analytics domain's lack of connection.
		registerProvider("analytics", {
			id: "plausible",
			label: "Plausible",
			fields,
		});
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: "k" },
				now: NOW,
			},
			ROOT,
		);
		const result = await getConnectedProvider({
			domain: "analytics",
			repo,
			rootSecrets: { current: ROOT },
		});
		expect(result).toBeUndefined();
	});

	it("picks the connected row from the requested domain when multiple domains are connected", async () => {
		registerProvider("analytics", {
			id: "plausible",
			label: "Plausible",
			fields,
		});
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: "newsletter-key" },
				now: NOW,
			},
			ROOT,
		);
		await repo.connect(
			{
				domain: "analytics",
				provider: "plausible",
				configJson: "{}",
				secretFields: { apiKey: "analytics-key" },
				now: NOW,
			},
			ROOT,
		);
		const result = await getConnectedProvider({
			domain: "analytics",
			repo,
			rootSecrets: { current: ROOT },
		});
		expect(result?.providerId).toBe("plausible");
		expect(result?.fields.apiKey).toBe("analytics-key");
	});

	it("ignores connected rows from other domains when querying an alphabetically-later domain", async () => {
		// listStatuses returns rows ORDER BY domain ASC, so without the
		// .filter(s.domain === args.domain) call the .find(connected)
		// would latch onto the analytics row first and try to look up
		// "plausible" under "newsletter" — which is not registered there
		// and would return undefined. The filter must do real work for
		// this assertion to pass.
		registerProvider("analytics", {
			id: "plausible",
			label: "Plausible",
			fields,
		});
		await repo.connect(
			{
				domain: "analytics",
				provider: "plausible",
				configJson: "{}",
				secretFields: { apiKey: "analytics-key" },
				now: NOW,
			},
			ROOT,
		);
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: "newsletter-key" },
				now: NOW,
			},
			ROOT,
		);
		const result = await getConnectedProvider({
			domain: "newsletter",
			repo,
			rootSecrets: { current: ROOT },
		});
		expect(result?.providerId).toBe("listmonk");
		expect(result?.fields.apiKey).toBe("newsletter-key");
	});

	it("returns undefined when status is 'error'", async () => {
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: "k" },
				now: NOW,
			},
			ROOT,
		);
		repo.updateStatus({
			domain: "newsletter",
			provider: "listmonk",
			status: "error",
			lastCheckAt: NOW,
			lastError: "INTEGRATION_VERIFY_FAILED",
		});
		const result = await getConnectedProvider({
			domain: "newsletter",
			repo,
			rootSecrets: { current: ROOT },
		});
		expect(result).toBeUndefined();
	});

	it("returns undefined when status is 'paused'", async () => {
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: "k" },
				now: NOW,
			},
			ROOT,
		);
		repo.updateStatus({
			domain: "newsletter",
			provider: "listmonk",
			status: "paused",
			lastCheckAt: NOW,
		});
		const result = await getConnectedProvider({
			domain: "newsletter",
			repo,
			rootSecrets: { current: ROOT },
		});
		expect(result).toBeUndefined();
	});

	it("returns undefined when findSecret returns undefined (status row exists but secret was deleted)", async () => {
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: "k" },
				now: NOW,
			},
			ROOT,
		);
		// Wipe the secret row directly while leaving the status row in
		// place; getConnectedProvider must not return a half-connected
		// view to the runtime.
		db.prepare("DELETE FROM integration_secrets WHERE domain=? AND provider=?").run(
			"newsletter",
			"listmonk",
		);
		const result = await getConnectedProvider({
			domain: "newsletter",
			repo,
			rootSecrets: { current: ROOT },
		});
		expect(result).toBeUndefined();
	});

	it("returns undefined when provider is not registered", async () => {
		_resetRegistryForTests();
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: "k" },
				now: NOW,
			},
			ROOT,
		);
		const result = await getConnectedProvider({
			domain: "newsletter",
			repo,
			rootSecrets: { current: ROOT },
		});
		expect(result).toBeUndefined();
	});

	it("uses runtimeShape for validation when provided", async () => {
		_resetRegistryForTests();
		registerProvider("newsletter", {
			id: "strict",
			label: "Strict",
			fields,
			runtimeShape: z.object({ apiKey: z.string().min(20) }),
		});
		await repo.connect(
			{
				domain: "newsletter",
				provider: "strict",
				configJson: "{}",
				secretFields: { apiKey: "short" },
				now: NOW,
			},
			ROOT,
		);
		const result = await getConnectedProvider({
			domain: "newsletter",
			repo,
			rootSecrets: { current: ROOT },
		});
		// Runtime shape rejects short keys → undefined.
		expect(result).toBeUndefined();
	});

	it("rotation: opens against previous key when current is wrong", async () => {
		const PREV = "test-root-previous";
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: "rotated-key" },
				now: NOW,
			},
			PREV,
		);
		db.prepare("UPDATE integration_secrets SET kid='previous' WHERE domain=? AND provider=?").run(
			"newsletter",
			"listmonk",
		);
		const result = await getConnectedProvider({
			domain: "newsletter",
			repo,
			rootSecrets: { current: ROOT, previous: PREV },
		});
		expect(result?.fields.apiKey).toBe("rotated-key");
	});
});

describe("explicit active-provider selection (#127/#129)", () => {
	async function connectBoth() {
		registerProvider("newsletter", { id: "mailchimp", label: "Mailchimp", fields });
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: "listmonk-key" },
				now: NOW,
			},
			ROOT,
		);
		await repo.connect(
			{
				domain: "newsletter",
				provider: "mailchimp",
				configJson: "{}",
				secretFields: { apiKey: "mailchimp-key" },
				now: NOW,
			},
			ROOT,
		);
	}

	it("first provider connected in a domain becomes active automatically", async () => {
		await connectBoth();
		const statuses = repo.listStatuses().filter((s) => s.domain === "newsletter");
		const active = statuses.filter((s) => s.isActive);
		expect(active).toHaveLength(1);
		expect(active[0].provider).toBe("listmonk");
	});

	it("connecting a second provider does NOT steal the active selection", async () => {
		await connectBoth();
		// listmonk (connected first) stays active; mailchimp is connected but not active.
		const result = await getConnectedProvider({
			domain: "newsletter",
			repo,
			rootSecrets: { current: ROOT },
		});
		expect(result?.providerId).toBe("listmonk");
		expect(result?.fields.apiKey).toBe("listmonk-key");
	});

	it("setActiveProvider switches which connected provider the runtime resolves", async () => {
		await connectBoth();
		expect(repo.setActiveProvider("newsletter", "mailchimp")).toBe(true);
		const result = await getConnectedProvider({
			domain: "newsletter",
			repo,
			rootSecrets: { current: ROOT },
		});
		expect(result?.providerId).toBe("mailchimp");
		expect(result?.fields.apiKey).toBe("mailchimp-key");
		// Exactly one active row remains in the domain.
		const active = repo.listStatuses().filter((s) => s.domain === "newsletter" && s.isActive);
		expect(active.map((s) => s.provider)).toEqual(["mailchimp"]);
	});

	it("resolves a SOLE connected provider even when no is_active flag is set (legacy fallback)", async () => {
		// One connected provider with is_active = 0 (a pre-#127 row). The
		// `connected.length === 1 ? connected[0] : undefined` fallback must still
		// resolve it — only an ambiguous multi-provider domain returns undefined.
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: "sole-key" },
				now: NOW,
			},
			ROOT,
		);
		db.prepare("UPDATE connected_integrations SET is_active = 0 WHERE domain = ?").run(
			"newsletter",
		);
		const result = await getConnectedProvider({
			domain: "newsletter",
			repo,
			rootSecrets: { current: ROOT },
		});
		expect(result?.providerId).toBe("listmonk");
		expect(result?.fields.apiKey).toBe("sole-key");
	});

	it("refuses to resolve when two providers are connected but none is active (ambiguous)", async () => {
		await connectBoth();
		// Clear the auto-active flag to model a legacy/ambiguous domain.
		db.prepare("UPDATE connected_integrations SET is_active = 0 WHERE domain = ?").run(
			"newsletter",
		);
		const result = await getConnectedProvider({
			domain: "newsletter",
			repo,
			rootSecrets: { current: ROOT },
		});
		expect(result).toBeUndefined();
	});

	it("setActiveProvider refuses a provider that is not connected", async () => {
		registerProvider("newsletter", { id: "mailchimp", label: "Mailchimp", fields });
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: "k" },
				now: NOW,
			},
			ROOT,
		);
		expect(repo.setActiveProvider("newsletter", "mailchimp")).toBe(false);
	});
});

describe("createRequestProviderCache", () => {
	it("decrypts only once across multiple calls", async () => {
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: "cache-key" },
				now: NOW,
			},
			ROOT,
		);
		let calls = 0;
		const wrappedRepo: IntegrationsRepository = {
			...repo,
			findSecret: async (...args) => {
				calls += 1;
				return repo.findSecret(...args);
			},
		};
		const cache = createRequestProviderCache({
			domain: "newsletter",
			repo: wrappedRepo,
			rootSecrets: { current: ROOT },
		});
		const first = await cache();
		const second = await cache();
		expect(first?.fields.apiKey).toBe("cache-key");
		expect(second).toBe(first);
		expect(calls).toBe(1);
	});
});

describe("listRegisteredProvidersForDomain", () => {
	it("returns id+label pairs for the domain", () => {
		registerProvider("newsletter", {
			id: "mailchimp",
			label: "Mailchimp",
			fields,
		});
		const out = listRegisteredProvidersForDomain("newsletter")
			.map((p) => p.id)
			.sort();
		expect(out).toEqual(["listmonk", "mailchimp"]);
	});

	it("returns empty array for a domain with no registrations", () => {
		expect(listRegisteredProvidersForDomain("monitoring")).toEqual([]);
	});
});

tests/cloudflare-adapter-security.test.t.source:
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { createAstropressCloudflareAdapter } from "../src/adapters/cloudflare.js";
import {
	cleanupExpiredCloudflareSessions,
	resolveCloudflareSessionSecret,
	resolveCloudflareSessionSecretCandidates,
} from "../src/adapters/cloudflare-auth.js";
import { createSessionTokenDigest, hashPassword } from "../src/crypto-utils.js";
import { makeDb } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

describe("cloudflare adapter security defaults", () => {
	it("does not allow insecure fallback sign-in unless explicitly enabled", async () => {
		const adapter = createAstropressCloudflareAdapter({
			users: [
				{
					id: "admin-1",
					email: "admin@example.com",
					isAdmin: true,
					password: "password",
				},
			],
		});

		await expect(adapter.auth.signIn("admin@example.com", "password")).resolves.toBeNull();
	});

	it("supports explicit insecure fallback auth only for test-style callers", async () => {
		const adapter = createAstropressCloudflareAdapter({
			allowInsecureFallbackAuth: true,
			users: [
				{
					id: "admin-1",
					email: "admin@example.com",
					isAdmin: true,
					password: "password",
				},
			],
		});

		await expect(adapter.auth.signIn("admin@example.com", "password")).resolves.toMatchObject({
			email: "admin@example.com",
			isAdmin: true,
		});
	});
});

describe("cloudflare session secret", () => {
	beforeEach(() => {
		vi.spyOn(console, "warn").mockImplementation(() => {});
		delete process.env.CLOUDFLARE_SESSION_SECRET;
	});

	afterEach(() => {
		vi.restoreAllMocks();
		delete process.env.CLOUDFLARE_SESSION_SECRET;
	});

	it("emits console.warn when using the default hardcoded secret", async () => {
		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?3, 'Admin', 1, CASE WHEN ?2='admin' THEN 1 ELSE 0 END)",
		).run("admin@example.com", "admin", await hashPassword("correctpass"));
		const d1 = new SqliteBackedD1Database(db);
		const adapter = createAstropressCloudflareAdapter({ db: d1 });
		await adapter.auth.signIn("admin@example.com", "correctpass");
		expect(console.warn).toHaveBeenCalledWith(
			expect.any(String),
			expect.stringContaining("CLOUDFLARE_SESSION_SECRET is using the insecure default"),
		);
		db.close();
	});

	it("suppresses console.warn when CLOUDFLARE_SESSION_SECRET is set to a custom value", async () => {
		process.env.CLOUDFLARE_SESSION_SECRET = "my-long-random-secret-value";
		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?3, 'Admin', 1, CASE WHEN ?2='admin' THEN 1 ELSE 0 END)",
		).run("admin@example.com", "admin", await hashPassword("correctpass"));
		const d1 = new SqliteBackedD1Database(db);
		const adapter = createAstropressCloudflareAdapter({ db: d1 });
		await adapter.auth.signIn("admin@example.com", "correctpass");
		expect(console.warn).not.toHaveBeenCalled();
		db.close();
	});

	it("session sign-in/lookup round-trips correctly with a custom secret", async () => {
		process.env.CLOUDFLARE_SESSION_SECRET = "custom-test-secret-xyz";

		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?3, 'Admin', 1, CASE WHEN ?2='admin' THEN 1 ELSE 0 END)",
		).run("admin@example.com", "admin", await hashPassword("correctpass"));

		const d1 = new SqliteBackedD1Database(db);
		const adapter = createAstropressCloudflareAdapter({ db: d1 });

		const session = await adapter.auth.signIn("admin@example.com", "correctpass");
		expect(session).not.toBeNull();
		expect(session?.email).toBe("admin@example.com");

		const looked = await adapter.auth.getSession(session?.id);
		expect(looked).toMatchObject({ email: "admin@example.com" });

		await adapter.auth.signOut(session?.id);
		expect(await adapter.auth.getSession(session?.id)).toBeNull();

		db.close();
	});

	it("keeps sessions valid when CLOUDFLARE_SESSION_SECRET_PREV is present during rotation", async () => {
		process.env.CLOUDFLARE_SESSION_SECRET = "old-cloudflare-secret";

		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?3, 'Admin', 1, CASE WHEN ?2='admin' THEN 1 ELSE 0 END)",
		).run("admin@example.com", "admin", await hashPassword("correctpass"));

		const d1 = new SqliteBackedD1Database(db);
		const adapter = createAstropressCloudflareAdapter({ db: d1 });

		const session = await adapter.auth.signIn("admin@example.com", "correctpass");
		expect(session).not.toBeNull();

		process.env.CLOUDFLARE_SESSION_SECRET = "new-cloudflare-secret";
		process.env.CLOUDFLARE_SESSION_SECRET_PREV = "old-cloudflare-secret";

		await expect(adapter.auth.getSession(session?.id)).resolves.toMatchObject({
			email: "admin@example.com",
			isAdmin: true,
		});

		await adapter.auth.signOut(session?.id);
		expect(await adapter.auth.getSession(session?.id)).toBeNull();

		db.close();
	});

	it("throws in production runtime when CLOUDFLARE_SESSION_SECRET is the insecure default (pins L39 ConditionalExpression)", () => {
		const origProd = process.env.PROD;
		process.env.PROD = "true";
		delete process.env.CLOUDFLARE_SESSION_SECRET;
		try {
			expect(() => resolveCloudflareSessionSecret()).toThrow(
				/CLOUDFLARE_SESSION_SECRET must be set/,
			);
			// Pin L42 StringLiteral — also assert the "random string of 32+" tail.
			expect(() => resolveCloudflareSessionSecret()).toThrow(/random string of 32\+ characters/);
		} finally {
			if (origProd === undefined) delete process.env.PROD;
			else process.env.PROD = origProd;
		}
	});

	it("warns with the 'long random string' guidance line (pins L47 StringLiteral)", () => {
		delete process.env.CLOUDFLARE_SESSION_SECRET;
		resolveCloudflareSessionSecret();
		expect(console.warn).toHaveBeenCalledWith(
			expect.any(String),
			expect.stringContaining("long random string"),
		);
	});

	it("getConfiguredSecrets trims and deduplicates env values (pins L23 .trim() + L24 dedup/empty guards)", () => {
		// Use the exported wrapper resolveCloudflareSessionSecretCandidates to
		// exercise getConfiguredSecrets indirectly.
		process.env.CLOUDFLARE_SESSION_SECRET = "  same-secret  ";
		process.env.CLOUDFLARE_SESSION_SECRET_PREV = "same-secret";
		const candidates = resolveCloudflareSessionSecretCandidates();
		// L23 mutates `.trim()` away → "  same-secret  " stays padded and the
		// dedup check `seen.has(...)` returns false → 2 entries.
		// L24 mutates the `||` / continue → empty/duplicate entries push through.
		expect(candidates).toEqual(["same-secret"]);
		delete process.env.CLOUDFLARE_SESSION_SECRET;
		delete process.env.CLOUDFLARE_SESSION_SECRET_PREV;
	});

	it("cleanupExpiredCloudflareSessions revokes sessions older than 12h (pins L60 BlockStatement)", async () => {
		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?, ?, 'Admin', 1, 1)",
		).run("admin@example.com", await hashPassword("p"));
		const userId = (
			db.prepare("SELECT id FROM admin_users WHERE email = 'admin@example.com'").get() as {
				id: number;
			}
		).id;
		// Insert a session with last_active_at >12h ago.
		db.prepare(
			"INSERT INTO admin_sessions (id, user_id, csrf_token, last_active_at) VALUES (?, ?, ?, datetime('now', '-13 hours'))",
		).run("stale-session", userId, "csrf");
		const d1 = new SqliteBackedD1Database(db);
		await cleanupExpiredCloudflareSessions(d1);
		const row = db
			.prepare("SELECT revoked_at FROM admin_sessions WHERE id = 'stale-session'")
			.get() as { revoked_at: string | null };
		// Mutant emptying the function body skips the UPDATE → revoked_at stays null.
		expect(row.revoked_at).not.toBeNull();
		db.close();
	});

	it("D1 getSession returns isAdmin reflecting the column, not always-true (pins L230 ConditionalExpression)", async () => {
		process.env.CLOUDFLARE_SESSION_SECRET = "test-secret-for-getsession-isadmin";
		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?, ?, 'Editor', 1, 0)",
		).run("editor@example.com", await hashPassword("ed-pw"));
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		const session = await adapter.auth.signIn("editor@example.com", "ed-pw");
		expect(session).not.toBeNull();
		const looked = await adapter.auth.getSession(session?.id ?? "");
		expect(looked?.isAdmin).toBe(false);
		db.close();
	});

	it("D1 signIn returns isAdmin reflecting the column, not always-true (pins L210 ConditionalExpression)", async () => {
		process.env.CLOUDFLARE_SESSION_SECRET = "test-secret-for-isadmin";
		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?, ?, 'Editor', 1, 0)",
		).run("editor@example.com", await hashPassword("editor-pw"));
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		const session = await adapter.auth.signIn("editor@example.com", "editor-pw");
		expect(session?.isAdmin).toBe(false);
		db.close();
	});

	it("D1 signIn trims email before lookup (pins L177 MethodExpression .trim())", async () => {
		process.env.CLOUDFLARE_SESSION_SECRET = "test-secret-for-trim";
		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?, ?, 'Admin', 1, 1)",
		).run("admin@example.com", await hashPassword("pwd"));
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		// Leading/trailing whitespace must be stripped before the SELECT.
		const session = await adapter.auth.signIn("  admin@example.com  ", "pwd");
		expect(session).not.toBeNull();
		expect(session?.email).toBe("admin@example.com");
		db.close();
	});

	it("D1 signIn records user_agent = 'astropress-cloudflare-adapter' (pins L204 StringLiteral)", async () => {
		process.env.CLOUDFLARE_SESSION_SECRET = "test-secret-for-ua";
		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?, ?, 'Admin', 1, 1)",
		).run("admin@example.com", await hashPassword("pwd"));
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});
		await adapter.auth.signIn("admin@example.com", "pwd");
		const row = db.prepare("SELECT user_agent FROM admin_sessions LIMIT 1").get() as {
			user_agent: string;
		};
		expect(row.user_agent).toBe("astropress-cloudflare-adapter");
		db.close();
	});

	it("fallback signIn trims email and returns a non-empty sessionId (pins L138 .trim() + L140 sessionId template)", async () => {
		const adapter = createAstropressCloudflareAdapter({
			allowInsecureFallbackAuth: true,
			users: [
				{
					id: "u-1",
					email: "admin@example.com",
					isAdmin: true,
					password: "pw",
				},
			],
		});
		const session = await adapter.auth.signIn("  admin@example.com  ", "pw");
		expect(session).not.toBeNull();
		// L138 .trim() — wrong-case-only would also map, but trim makes the
		// "  admin@example.com  " variant resolve to the seed user.
		expect(session?.email).toBe("admin@example.com");
		// L140 mutates the template literal to ''; original must produce a
		// non-empty session id that the same store can roundtrip.
		expect(session?.id).toBeTruthy();
		expect(String(session?.id).length).toBeGreaterThan(0);
		const lookedUp = await adapter.auth.getSession(session?.id ?? "");
		expect(lookedUp).not.toBeNull();
	});

	it("signs rotated Cloudflare sessions with the current secret, not the previous one", async () => {
		process.env.CLOUDFLARE_SESSION_SECRET = "new-cloudflare-secret";
		process.env.CLOUDFLARE_SESSION_SECRET_PREV = "old-cloudflare-secret";

		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?3, 'Admin', 1, CASE WHEN ?2='admin' THEN 1 ELSE 0 END)",
		).run("admin@example.com", "admin", await hashPassword("correctpass"));

		const d1 = new SqliteBackedD1Database(db);
		const adapter = createAstropressCloudflareAdapter({ db: d1 });

		const session = await adapter.auth.signIn("admin@example.com", "correctpass");
		expect(session).not.toBeNull();

		const stored = db.prepare("SELECT id FROM admin_sessions LIMIT 1").get() as { id: string };
		expect(stored.id).toBe(await createSessionTokenDigest(session?.id, "new-cloudflare-secret"));
		expect(stored.id).not.toBe(
			await createSessionTokenDigest(session?.id, "old-cloudflare-secret"),
		);

		db.close();
	});
});

tests/runtime-actions-misc-static.test.t.source:
// Static-import counterpart to runtime-actions-misc.test.ts. The sibling file
// uses dynamic imports + vi.resetModules for its no-db fallback assertions,
// which prevents stryker's per-test coverage tracker from recording most of
// its assertions against this source. This file imports statically and pins
// the audit-event content, exact error strings, status-code mapping, and the
// existing-row branches that the dynamic-import file cannot.
import type { DatabaseSync } from "node:sqlite";
import { afterAll, afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { registerCms } from "../src/config";
import {
	createRuntimeRedirectRule,
	deleteRuntimeRedirectRule,
	moderateRuntimeComment,
	saveRuntimeSettings,
	updateRuntimeTranslationState,
} from "../src/runtime-actions-misc.js";
import { makeDb, STANDARD_ACTOR, STANDARD_CMS_CONFIG } from "./helpers/make-db.js";
import { makeLocals } from "./helpers/make-locals.js";

const { fakeLocalStore, mockLoadLocalAdminStore } = vi.hoisted(() => ({
	fakeLocalStore: {
		updateTranslationState: vi.fn(),
		createRedirectRule: vi.fn(),
		deleteRedirectRule: vi.fn(),
		moderateComment: vi.fn(),
		saveSettings: vi.fn(),
	},
	mockLoadLocalAdminStore: vi.fn(),
}));

vi.mock("../src/local-runtime-modules", () => ({
	loadLocalAdminStore: mockLoadLocalAdminStore,
}));
vi.mock("../src/local-runtime-modules.js", () => ({
	loadLocalAdminStore: mockLoadLocalAdminStore,
}));

const actor = STANDARD_ACTOR;
let db: DatabaseSync;
let locals: App.Locals;

beforeEach(() => {
	db = makeDb();
	locals = makeLocals(db);
	registerCms(STANDARD_CMS_CONFIG);
	db.prepare(
		"INSERT INTO redirect_rules (source_path, target_path, status_code, created_by) VALUES (?, ?, ?, ?)",
	).run("/existing", "/dest", 301, "admin@test.local");
	db.prepare(
		"INSERT INTO redirect_rules (source_path, target_path, status_code, created_by, deleted_at) VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)",
	).run("/soft-deleted", "/dest", 301, "admin@test.local");
	db.prepare("INSERT INTO comments (id, route, author, body, status) VALUES (?, ?, ?, ?, ?)").run(
		"c-1",
		"/page",
		"Bob",
		"Hello",
		"pending",
	);
	for (const m of Object.values(fakeLocalStore)) m.mockReset();
	mockLoadLocalAdminStore.mockReset();
	mockLoadLocalAdminStore.mockResolvedValue(fakeLocalStore);
});

afterEach(() => {
	vi.clearAllMocks();
});

afterAll(() => {
	vi.resetModules();
});

describe("updateRuntimeTranslationState — audit and error text", () => {
	it("rejects with a message listing every valid state", async () => {
		const result = (await updateRuntimeTranslationState("/about", "bogus", actor, locals)) as {
			ok: false;
			error: string;
		};
		expect(result.ok).toBe(false);
		expect(result.error).toBe(
			"Invalid translation state. Must be one of: not_started, partial, fallback_en, translated, reviewed, published",
		);
	});

	it("records a translation.update audit event with the route and new state in the summary", async () => {
		await updateRuntimeTranslationState("/about", "translated", actor, locals);
		const row = db
			.prepare(
				"SELECT user_email, action, resource_type, resource_id, summary FROM audit_events ORDER BY id DESC LIMIT 1",
			)
			.get() as Record<string, string>;
		expect(row).toEqual({
			user_email: actor.email,
			action: "translation.update",
			resource_type: "content",
			resource_id: "/about",
			summary: "Updated translation state for /about to translated.",
		});
	});

	it("forwards to localStore.updateTranslationState when no D1 binding is present", async () => {
		fakeLocalStore.updateTranslationState.mockResolvedValue({ ok: true });
		const result = await updateRuntimeTranslationState("/about", "translated", actor, undefined);
		expect(fakeLocalStore.updateTranslationState).toHaveBeenCalledWith(
			"/about",
			"translated",
			actor,
		);
		expect(result).toEqual({ ok: true });
	});
});

describe("createRuntimeRedirectRule — error strings, audit, branches", () => {
	it("returns the exact 'both required' error when sourcePath is empty after normalisation", async () => {
		const result = await createRuntimeRedirectRule(
			{ sourcePath: "   ", targetPath: "/to", statusCode: 301 },
			actor,
			locals,
		);
		expect(result).toEqual({ ok: false, error: "Both legacy and target paths are required." });
	});

	it("returns the exact 'must be different' error when source and target match", async () => {
		const result = await createRuntimeRedirectRule(
			{ sourcePath: "/same", targetPath: "/same", statusCode: 301 },
			actor,
			locals,
		);
		expect(result).toEqual({ ok: false, error: "Legacy and target paths must be different." });
	});

	it("returns the exact 'already has a reviewed rule' error for an active duplicate", async () => {
		const result = await createRuntimeRedirectRule(
			{ sourcePath: "/existing", targetPath: "/other", statusCode: 301 },
			actor,
			locals,
		);
		expect(result).toEqual({
			ok: false,
			error: "That legacy path already has a reviewed redirect rule.",
		});
	});

	it("re-activates a previously soft-deleted rule rather than rejecting as duplicate", async () => {
		// deleted_at is non-null → existing && existing.deleted_at === null is false → continue
		// (the mutant `if (true)` would reject as duplicate)
		const result = await createRuntimeRedirectRule(
			{ sourcePath: "/soft-deleted", targetPath: "/new-dest", statusCode: 302 },
			actor,
			locals,
		);
		expect(result).toMatchObject({
			ok: true,
			rule: { sourcePath: "/soft-deleted", targetPath: "/new-dest", statusCode: 302 },
		});
		const row = db
			.prepare(
				"SELECT target_path, status_code, deleted_at FROM redirect_rules WHERE source_path = '/soft-deleted'",
			)
			.get() as { target_path: string; status_code: number; deleted_at: string | null };
		expect(row.deleted_at).toBeNull();
		expect(row.target_path).toBe("/new-dest");
		expect(row.status_code).toBe(302);
	});

	it("creates a fresh redirect when no existing row matches the source path", async () => {
		const result = await createRuntimeRedirectRule(
			{ sourcePath: "/fresh", targetPath: "/dest", statusCode: 301 },
			actor,
			locals,
		);
		expect(result).toMatchObject({ ok: true });
	});

	it("records a redirect.create audit event with the source, target and status code", async () => {
		await createRuntimeRedirectRule(
			{ sourcePath: "/from", targetPath: "/to", statusCode: 302 },
			actor,
			locals,
		);
		const row = db
			.prepare(
				"SELECT user_email, action, resource_type, resource_id, summary FROM audit_events ORDER BY id DESC LIMIT 1",
			)
			.get() as Record<string, string>;
		expect(row).toEqual({
			user_email: actor.email,
			action: "redirect.create",
			resource_type: "redirect",
			resource_id: "/from",
			summary: "Created redirect /from -> /to (302).",
		});
	});

	it("forwards to localStore.createRedirectRule when no D1 binding is present", async () => {
		fakeLocalStore.createRedirectRule.mockResolvedValue({ ok: true });
		const input = { sourcePath: "/a", targetPath: "/b", statusCode: 301 };
		const result = await createRuntimeRedirectRule(input, actor, undefined);
		expect(fakeLocalStore.createRedirectRule).toHaveBeenCalledWith(input, actor);
		expect(result).toEqual({ ok: true });
	});
});

describe("deleteRuntimeRedirectRule — audit and fallback", () => {
	it("records a redirect.delete audit event with the source path in the summary", async () => {
		await deleteRuntimeRedirectRule("/existing", actor, locals);
		const row = db
			.prepare(
				"SELECT user_email, action, resource_type, resource_id, summary FROM audit_events ORDER BY id DESC LIMIT 1",
			)
