import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { registerCms } from "../../src/config";
import {
	mapArchiveRow,
	mapStructuredPageRow,
	SQL_FIND_ARCHIVE_FOR_UPDATE,
	SQL_FIND_STRUCTURED_FOR_UPDATE,
	SQL_FIND_SYSTEM_FOR_UPDATE,
	SQL_GET_ARCHIVE,
	SQL_INSERT_ARCHIVE_REVISION,
	SQL_INSERT_REVISION,
	SQL_INSERT_ROUTE_GROUP,
	SQL_INSERT_ROUTE_VARIANT,
	SQL_IS_PATH_TAKEN,
	SQL_LIST_ARCHIVES,
	SQL_LIST_STRUCTURED,
	SQL_LIST_SYSTEM,
	SQL_PERSIST_ARCHIVE,
	SQL_PERSIST_STRUCTURED,
	SQL_PERSIST_SYSTEM,
} from "../../src/sqlite-runtime/routes-helpers";

describe("mapArchiveRow", () => {
	it("maps a fully-populated row to a normalized record", () => {
		const row = {
			path: "/blog",
			title: "Blog",
			summary: "All posts",
			seo_title: "Posts",
			meta_description: "All blog posts",
			canonical_url_override: "https://example.org/blog",
			robots_directive: "index, follow",
			updated_at: "2026-05-03T00:00:00Z",
		} as never;
		expect(mapArchiveRow(row)).toEqual({
			path: "/blog",
			title: "Blog",
			summary: "All posts",
			seoTitle: "Posts",
			metaDescription: "All blog posts",
			canonicalUrlOverride: "https://example.org/blog",
			robotsDirective: "index, follow",
			updatedAt: "2026-05-03T00:00:00Z",
		});
	});

	it("converts every nullable column to undefined when null", () => {
		const row = {
			path: "/blog",
			title: "Blog",
			summary: null,
			seo_title: null,
			meta_description: null,
			canonical_url_override: null,
			robots_directive: null,
			updated_at: null,
		} as never;
		expect(mapArchiveRow(row)).toEqual({
			path: "/blog",
			title: "Blog",
			summary: undefined,
			seoTitle: undefined,
			metaDescription: undefined,
			canonicalUrlOverride: undefined,
			robotsDirective: undefined,
			updatedAt: undefined,
		});
	});

	it("propagates path and title verbatim (StringLiteral pin)", () => {
		const row = {
			path: "/p1",
			title: "T1",
			summary: null,
			seo_title: null,
			meta_description: null,
			canonical_url_override: null,
			robots_directive: null,
			updated_at: null,
		} as never;
		const out = mapArchiveRow(row);
		expect(out.path).toBe("/p1");
		expect(out.title).toBe("T1");
	});
});

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");
beforeEach(() => {
	registerCms({
		siteUrl: "https://example.org",
		templateKeys: ["content"],
		seedPages: [],
		archives: [],
	} as never);
});
afterEach(() => {
	(globalThis as typeof globalThis & { [CMS_CONFIG_KEY]?: unknown })[CMS_CONFIG_KEY] = null;
});

describe("mapStructuredPageRow", () => {
	const baseSettingsJson = JSON.stringify({
		templateKey: "content",
		alternateLinks: [{ hreflang: "es", href: "/es/x" }],
	});

	it("maps a structured row using settings JSON for templateKey + alternates", () => {
		const row = {
			path: "/x",
			title: "X",
			summary: "Sum",
			seo_title: "SEO",
			meta_description: "Desc",
			canonical_url_override: "https://example.org/x",
			robots_directive: "index, follow",
			og_image: "https://example.org/x.png",
			sections_json: JSON.stringify({ hero: { title: "H" } }),
			settings_json: baseSettingsJson,
			updated_at: "2026-05-03T00:00:00Z",
		} as never;
		const result = mapStructuredPageRow(row);
		expect(result).toEqual({
			path: "/x",
			title: "X",
			summary: "Sum",
			seoTitle: "SEO",
			metaDescription: "Desc",
			canonicalUrlOverride: "https://example.org/x",
			robotsDirective: "index, follow",
			ogImage: "https://example.org/x.png",
			templateKey: "content",
			alternateLinks: [{ hreflang: "es", href: "/es/x" }],
			sections: { hero: { title: "H" } },
			updatedAt: "2026-05-03T00:00:00Z",
		});
	});

	it("returns null when settings.templateKey is missing or invalid", () => {
		const row = {
			path: "/x",
			title: "X",
			summary: null,
			seo_title: null,
			meta_description: null,
			canonical_url_override: null,
			robots_directive: null,
			og_image: null,
			sections_json: null,
			settings_json: JSON.stringify({}),
			updated_at: null,
		} as never;
		expect(mapStructuredPageRow(row)).toBeNull();
	});

	it("defaults alternateLinks to [] when settings has no alternateLinks array", () => {
		const row = {
			path: "/x",
			title: "X",
			summary: null,
			seo_title: null,
			meta_description: null,
			canonical_url_override: null,
			robots_directive: null,
			og_image: null,
			sections_json: null,
			settings_json: JSON.stringify({ templateKey: "content" }),
			updated_at: null,
		} as never;
		expect(mapStructuredPageRow(row)?.alternateLinks).toEqual([]);
	});

	it("defaults alternateLinks to [] when settings.alternateLinks is not an array", () => {
		const row = {
			path: "/x",
			title: "X",
			summary: null,
			seo_title: null,
			meta_description: null,
			canonical_url_override: null,
			robots_directive: null,
			og_image: null,
			sections_json: null,
			settings_json: JSON.stringify({
				templateKey: "content",
				alternateLinks: "not-an-array",
			}),
			updated_at: null,
		} as never;
		expect(mapStructuredPageRow(row)?.alternateLinks).toEqual([]);
	});

	it("returns sections as null when sections_json is null", () => {
		const row = {
			path: "/x",
			title: "X",
			summary: null,
			seo_title: null,
			meta_description: null,
			canonical_url_override: null,
			robots_directive: null,
			og_image: null,
			sections_json: null,
			settings_json: baseSettingsJson,
			updated_at: null,
		} as never;
		expect(mapStructuredPageRow(row)?.sections).toBeNull();
	});

	it("converts every nullable column to undefined when null", () => {
		const row = {
			path: "/x",
			title: "X",
			summary: null,
			seo_title: null,
			meta_description: null,
			canonical_url_override: null,
			robots_directive: null,
			og_image: null,
			sections_json: null,
			settings_json: baseSettingsJson,
			updated_at: null,
		} as never;
		const out = mapStructuredPageRow(row);
		if (!out) throw new Error("expected row to map (templateKey is valid)");
		expect(out.summary).toBeUndefined();
		expect(out.seoTitle).toBeUndefined();
		expect(out.metaDescription).toBeUndefined();
		expect(out.canonicalUrlOverride).toBeUndefined();
		expect(out.robotsDirective).toBeUndefined();
		expect(out.ogImage).toBeUndefined();
		expect(out.updatedAt).toBeUndefined();
	});
});

describe("SQL constants", () => {
	// These string literals are sent verbatim to D1/SQLite — pin every one to
	// make StringLiteral mutations to "" or arbitrary text observable.
	const cases: [string, string, string[]][] = [
		[
			"SQL_LIST_SYSTEM",
			SQL_LIST_SYSTEM,
			["SELECT", "cms_route_variants", "kind = 'system'", "ORDER BY"],
		],
		[
			"SQL_LIST_STRUCTURED",
			SQL_LIST_STRUCTURED,
			["SELECT", "cms_route_variants", "render_strategy = 'structured_sections'", "ORDER BY"],
		],
		["SQL_GET_ARCHIVE", SQL_GET_ARCHIVE, ["SELECT", "kind = 'archive'", "v.path = ?", "LIMIT 1"]],
		["SQL_LIST_ARCHIVES", SQL_LIST_ARCHIVES, ["SELECT", "kind = 'archive'", "ORDER BY"]],
		[
			"SQL_FIND_SYSTEM_FOR_UPDATE",
			SQL_FIND_SYSTEM_FOR_UPDATE,
			["SELECT", "render_strategy", "kind = 'system'", "v.path = ?"],
		],
		["SQL_PERSIST_SYSTEM", SQL_PERSIST_SYSTEM, ["UPDATE", "WHERE id = ?"]],
		["SQL_INSERT_REVISION", SQL_INSERT_REVISION, ["INSERT INTO cms_route_revisions", "VALUES"]],
		["SQL_IS_PATH_TAKEN", SQL_IS_PATH_TAKEN, ["SELECT", "v.path = ?", "LIMIT 1"]],
		[
			"SQL_FIND_STRUCTURED_FOR_UPDATE",
			SQL_FIND_STRUCTURED_FOR_UPDATE,
			["SELECT", "render_strategy = 'structured_sections'", "v.path = ?"],
		],
		["SQL_INSERT_ROUTE_GROUP", SQL_INSERT_ROUTE_GROUP, ["INSERT INTO cms_route_groups", "VALUES"]],
		[
			"SQL_INSERT_ROUTE_VARIANT",
			SQL_INSERT_ROUTE_VARIANT,
			["INSERT INTO cms_route_variants", "VALUES"],
		],
		["SQL_PERSIST_STRUCTURED", SQL_PERSIST_STRUCTURED, ["UPDATE", "WHERE id = ?"]],
		[
			"SQL_FIND_ARCHIVE_FOR_UPDATE",
			SQL_FIND_ARCHIVE_FOR_UPDATE,
			["SELECT", "kind = 'archive'", "v.path = ?"],
		],
		["SQL_PERSIST_ARCHIVE", SQL_PERSIST_ARCHIVE, ["UPDATE", "WHERE id = ?"]],
		[
			"SQL_INSERT_ARCHIVE_REVISION",
			SQL_INSERT_ARCHIVE_REVISION,
			["INSERT INTO cms_route_revisions", "VALUES", "'en'"],
		],
	];
	it.each(cases)("%s contains expected keywords", (_name, sql, parts) => {
		for (const part of parts) {
			expect(sql).toContain(part);
		}
		expect(sql.length).toBeGreaterThan(20);
	});
});

tests/import-api.contract.test.ts.source:
import type { DatabaseSync } from "node:sqlite";
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

import { registerCms } from "../src/config";
import type { AstropressWordPressImportReport } from "../src/platform-contracts.js";
import { createApiTokenStore } from "../src/sqlite-runtime/api-tokens.js";
import { makeDb } from "./helpers/make-db.js";

// ─── Hoisted mock functions ────────────────────────────────────────────────────

const mocks = vi.hoisted(() => ({
	loadLocalAdminStore: vi.fn(),
	importWordPress: vi.fn(),
}));

vi.mock("@astropress-diy/astropress/local-runtime-modules", () => ({
	loadLocalAdminStore: mocks.loadLocalAdminStore,
}));

vi.mock("@astropress-diy/astropress/import/wordpress", () => ({
	createAstropressWordPressImportSource: () => ({
		importWordPress: mocks.importWordPress,
	}),
}));

// ─── Page handler import (after mocks) ───────────────────────────────────────

import { POST } from "../pages/ap-api/v1/import/wordpress.js";

// ─── Test fixtures ────────────────────────────────────────────────────────────

const BASE = "http://localhost";

let db: DatabaseSync;
let importWriteToken: string;
let contentReadToken: string;

const MOCK_REPORT: AstropressWordPressImportReport = {
	status: "completed",
	importedRecords: 3,
	importedMedia: 1,
	importedComments: 0,
	importedUsers: 1,
	importedRedirects: 2,
	downloadedMedia: 0,
	failedMedia: [],
	reviewRequired: false,
	manualTasks: [],
	warnings: [],
	plan: {
		exportFile: "wp-export.xml",
		includeComments: true,
		includeUsers: true,
		includeMedia: true,
		downloadMedia: false,
		applyLocal: true,
		permalinkStrategy: "preserve-wordpress-links",
		resumeSupported: true,
		entityCounts: {
			posts: 2,
			pages: 1,
			attachments: 1,
			redirects: 2,
			comments: 0,
			users: 1,
			categories: 0,
			tags: 0,
		},
		reviewRequired: false,
		manualTasks: [],
	},
	inventory: {
		exportFile: "wp-export.xml",
		detectedRecords: 4,
		detectedMedia: 1,
		detectedComments: 0,
		detectedUsers: 1,
		detectedShortcodes: 0,
		detectedBuilderMarkers: 0,
		entityCounts: {
			posts: 2,
			pages: 1,
			attachments: 1,
			redirects: 2,
			comments: 0,
			users: 1,
			categories: 0,
			tags: 0,
		},
		unsupportedPatterns: [],
		remediationCandidates: [],
		warnings: [],
	},
};

beforeAll(async () => {
	db = makeDb();
	registerCms({
		templateKeys: ["content"],
		siteUrl: "https://example.com",
		seedPages: [],
		archives: [],
		translationStatus: [],
		api: { enabled: true },
	});

	const store = createApiTokenStore(db);
	importWriteToken = (await store.create({ label: "import", scopes: ["import:write"] })).rawToken;
	contentReadToken = (await store.create({ label: "read", scopes: ["content:read"] })).rawToken;
});

afterAll(() => {
	db.close();
});

beforeEach(() => {
	const apiTokens = createApiTokenStore(db);
	mocks.loadLocalAdminStore.mockResolvedValue({
		apiTokens,
		checkRateLimit: () => true,
	});
	mocks.importWordPress.mockResolvedValue(MOCK_REPORT);
});

// ─── Context builder ──────────────────────────────────────────────────────────

type AnyAPIContext = Parameters<typeof POST>[0];

function ctx(request: Request): AnyAPIContext {
	return { request, params: {}, locals: {} } as unknown as AnyAPIContext;
}

function req(opts: { token?: string; body?: unknown } = {}): Request {
	const headers: Record<string, string> = {
		"Content-Type": "application/json",
	};
	if (opts.token) headers.Authorization = `Bearer ${opts.token}`;
	return new Request(`${BASE}/ap-api/v1/import/wordpress`, {
		method: "POST",
		headers,
		body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined,
	});
}

// ─── POST /ap-api/v1/import/wordpress ────────────────────────────────────────

describe("POST /ap-api/v1/import/wordpress — auth and scope", () => {
	it("returns 401 without Authorization header", async () => {
		const res = await POST(ctx(req({ body: { exportFile: "wp-export.xml" } })));
		expect(res.status).toBe(401);
	});

	it("returns 403 when token lacks import:write scope", async () => {
		const res = await POST(
			ctx(
				req({
					token: contentReadToken,
					body: { exportFile: "wp-export.xml" },
				}),
			),
		);
		expect(res.status).toBe(403);
	});

	it("returns 404 when API is disabled", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
			api: { enabled: false },
		});
		const res = await POST(
			ctx(
				req({
					token: importWriteToken,
					body: { exportFile: "wp-export.xml" },
				}),
			),
		);
		expect(res.status).toBe(404);
		// Restore
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
			api: { enabled: true },
		});
	});
});

describe("POST /ap-api/v1/import/wordpress — request validation", () => {
	it("returns 422 when exportFile is missing from body", async () => {
		const res = await POST(ctx(req({ token: importWriteToken, body: {} })));
		expect(res.status).toBe(422);
		const body = (await res.json()) as Record<string, unknown>;
		expect(body.code).toBe("validation_error");
	});

	it("returns 422 when exportFile is empty string", async () => {
		const res = await POST(ctx(req({ token: importWriteToken, body: { exportFile: "  " } })));
		expect(res.status).toBe(422);
	});

	// #118: untrusted exportFile must be confined to the workspace root.
	it("returns 422 and never invokes the importer for an absolute exportFile", async () => {
		const res = await POST(
			ctx(req({ token: importWriteToken, body: { exportFile: "/etc/passwd" } })),
		);
		expect(res.status).toBe(422);
		expect(mocks.importWordPress).not.toHaveBeenCalled();
	});

	it("returns 422 and never invokes the importer for a traversing exportFile", async () => {
		const res = await POST(
			ctx(req({ token: importWriteToken, body: { exportFile: "../../etc/passwd" } })),
		);
		expect(res.status).toBe(422);
		expect(mocks.importWordPress).not.toHaveBeenCalled();
	});
});

describe("POST /ap-api/v1/import/wordpress — success path", () => {
	it("returns 200 with AstropressWordPressImportReport shape", async () => {
		const res = await POST(
			ctx(
				req({
					token: importWriteToken,
					body: { exportFile: "wp-export.xml" },
				}),
			),
		);
		expect(res.status).toBe(200);
		const body = (await res.json()) as Record<string, unknown>;
		expect(body.status).toBe("completed");
		expect(typeof body.importedRecords).toBe("number");
		expect(typeof body.importedMedia).toBe("number");
		expect(Array.isArray(body.failedMedia)).toBe(true);
		expect(typeof body.reviewRequired).toBe("boolean");
	});

	it("calls importWordPress with the provided exportFile and applyLocal: true", async () => {
		await POST(
			ctx(
				req({
					token: importWriteToken,
					body: { exportFile: "wp-export.xml" },
				}),
			),
		);
		expect(mocks.importWordPress).toHaveBeenCalledWith(
			expect.objectContaining({
				exportFile: "wp-export.xml",
				applyLocal: true,
			}),
		);
	});

	it("returns completed_with_warnings status when import has warnings", async () => {
		mocks.importWordPress.mockResolvedValueOnce({
			...MOCK_REPORT,
			status: "completed_with_warnings",
			reviewRequired: true,
			warnings: ["Review remediation-candidates.json"],
		});
		const res = await POST(
			ctx(
				req({
					token: importWriteToken,
					body: { exportFile: "wp-export.xml" },
				}),
			),
		);
		expect(res.status).toBe(200);
		const body = (await res.json()) as { status: string; warnings: string[] };
		expect(body.status).toBe("completed_with_warnings");
		expect(body.warnings.length).toBeGreaterThan(0);
	});
});

