import { describe, expect, it, vi } from "vitest";
import {
	createAstropressNhostAdapter,
	createAstropressNhostHostedAdapter,
	readAstropressNhostHostedConfig,
} from "../src/adapters/nhost.js";
import { createAstropressInMemoryPlatformAdapter } from "../src/in-memory-platform-adapter.js";

describe("readAstropressNhostHostedConfig", () => {
	const validEnv = {
		NHOST_SUBDOMAIN: "abcdefgh",
		NHOST_REGION: "eu-central-1",
		NHOST_ADMIN_SECRET: "super-secret-key",
	};

	it("reads all required env vars", () => {
		const config = readAstropressNhostHostedConfig(validEnv);
		expect(config.subdomain).toBe("abcdefgh");
		expect(config.region).toBe("eu-central-1");
		expect(config.adminSecret).toBe("super-secret-key");
	});

	it("builds the correct API base URL", () => {
		const config = readAstropressNhostHostedConfig(validEnv);
		expect(config.apiBaseUrl).toBe(
			"https://abcdefgh.eu-central-1.nhost.run/v1/functions/astropress",
		);
	});

	it("builds the correct preview (console) URL", () => {
		const config = readAstropressNhostHostedConfig(validEnv);
		expect(config.previewBaseUrl).toBe("https://abcdefgh.eu-central-1.nhost.run/console");
	});

	it("throws when NHOST_SUBDOMAIN is missing", () => {
		expect(() =>
			readAstropressNhostHostedConfig({
				...validEnv,
				NHOST_SUBDOMAIN: undefined,
			}),
		).toThrow(/NHOST_SUBDOMAIN/);
	});

	it("throws when NHOST_REGION is missing", () => {
		expect(() => readAstropressNhostHostedConfig({ ...validEnv, NHOST_REGION: undefined })).toThrow(
			/NHOST_REGION/,
		);
	});

	it("throws when NHOST_ADMIN_SECRET is missing", () => {
		expect(() =>
			readAstropressNhostHostedConfig({
				...validEnv,
				NHOST_ADMIN_SECRET: undefined,
			}),
		).toThrow(/NHOST_ADMIN_SECRET/);
	});

	it("strips whitespace from env values", () => {
		const config = readAstropressNhostHostedConfig({
			NHOST_SUBDOMAIN: "  abcdefgh  ",
			NHOST_REGION: "  eu-central-1  ",
			NHOST_ADMIN_SECRET: "  secret  ",
		});
		expect(config.subdomain).toBe("abcdefgh");
		expect(config.region).toBe("eu-central-1");
		expect(config.adminSecret).toBe("secret");
	});
});

describe("createAstropressNhostAdapter", () => {
	it("creates an adapter with full capabilities", () => {
		const adapter = createAstropressNhostAdapter();
		expect(adapter.capabilities.name).toBe("nhost");
		expect(adapter.capabilities.database).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(true);
		expect(adapter.capabilities.serverRuntime).toBe(true);
		expect(adapter.capabilities.hostedAdmin).toBe(true);
	});
});

describe("createAstropressNhostHostedAdapter", () => {
	const validEnv = {
		NHOST_SUBDOMAIN: "abcdefgh",
		NHOST_REGION: "eu-central-1",
		NHOST_ADMIN_SECRET: "super-secret-key",
	};

	it("creates a hosted API adapter with full capabilities", () => {
		const adapter = createAstropressNhostHostedAdapter({ env: validEnv });
		expect(adapter.capabilities.name).toBe("nhost");
		expect(adapter.capabilities.database).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(true);
		expect(adapter.capabilities.serverRuntime).toBe(true);
		expect(adapter.capabilities.hostedAdmin).toBe(true);
	});

	it("sets the Nhost Console hostPanel link", () => {
		const adapter = createAstropressNhostHostedAdapter({ env: validEnv });
		const panel = adapter.capabilities.hostPanel as {
			url: string;
			label: string;
			mode: string;
		};
		expect(panel).toBeTruthy();
		expect(panel.url).toBe("https://abcdefgh.eu-central-1.nhost.run/console");
		expect(panel.label).toBe("Nhost Console");
		// Pins L94 StringLiteral `mode: "link"`.
		expect(panel.mode).toBe("link");
	});

	it("routes through the hosted-API adapter when no stores are provided and invokes fetchImpl (pins L78 condition chain)", async () => {
		const fetchImpl = vi.fn(async () => new Response(JSON.stringify([]), { status: 200 }) as never);
		const adapter = createAstropressNhostHostedAdapter({
			env: validEnv,
			fetchImpl: fetchImpl as never,
		});
		await adapter.content.list("post");
		expect(fetchImpl).toHaveBeenCalled();
		expect(String(fetchImpl.mock.calls[0]?.[0])).toContain("functions/astropress");
	});

	it.each([
		["backingAdapter"],
		["content"],
		["media"],
		["revisions"],
		["auth"],
	] as const)("does NOT call fetchImpl when only `%s` is supplied (pins each L78 `!options.x &&` clause)", async (key) => {
		const fetchImpl = vi.fn(async () => new Response("nope", { status: 500 }) as never);
		const backing = createAstropressInMemoryPlatformAdapter({
			capabilities: { name: "sqlite" },
		});
		const isolated: Record<string, unknown> = {};
		if (key === "backingAdapter") {
			isolated.backingAdapter = backing;
		} else {
			isolated[key] = backing[key as "content" | "media" | "revisions" | "auth"];
		}
		const adapter = createAstropressNhostHostedAdapter({
			env: validEnv,
			...(isolated as Parameters<typeof createAstropressNhostHostedAdapter>[0]),
			fetchImpl: fetchImpl as never,
		});
		await adapter.content.list("post");
		expect(fetchImpl).not.toHaveBeenCalled();
	});

	it("accepts explicit config bypassing env read", () => {
		const adapter = createAstropressNhostHostedAdapter({
			config: {
				subdomain: "xyz",
				region: "us-east-1",
				adminSecret: "s3cr3t",
				apiBaseUrl: "https://xyz.us-east-1.nhost.run/v1/functions/astropress",
				previewBaseUrl: "https://xyz.us-east-1.nhost.run/console",
			},
		});
		expect(adapter.capabilities.name).toBe("nhost");
	});

	it("falls back to hosted platform adapter when backing stores are provided", () => {
		const mockContent = {
			async list() {
				return [];
			},
			async get() {
				return null;
			},
			async save(r: unknown) {
				return r as never;
			},
			async delete() {},
		};
		const adapter = createAstropressNhostHostedAdapter({
			env: validEnv,
			content: mockContent,
		});
		expect(adapter.capabilities.name).toBe("nhost");
	});

	it("throws when required env vars are missing and no explicit config", () => {
		expect(() => createAstropressNhostHostedAdapter({ env: {} })).toThrow(/NHOST_SUBDOMAIN/);
	});

	it("trims whitespace from NHOST_SUBDOMAIN (pins L53 .trim())", () => {
		const config = readAstropressNhostHostedConfig({
			NHOST_SUBDOMAIN: "  xyz  ",
			NHOST_REGION: "us-east-1",
			NHOST_ADMIN_SECRET: "secret",
		});
		expect(config.subdomain).toBe("xyz");
	});

	it("treats whitespace-only NHOST_SUBDOMAIN as missing", () => {
		expect(() =>
			readAstropressNhostHostedConfig({
				NHOST_SUBDOMAIN: "   ",
				NHOST_REGION: "us-east-1",
				NHOST_ADMIN_SECRET: "secret",
			}),
		).toThrow();
	});

	it("trims whitespace from NHOST_REGION (pins L54 .trim())", () => {
		const config = readAstropressNhostHostedConfig({
			NHOST_SUBDOMAIN: "xyz",
			NHOST_REGION: "  us-east-1  ",
			NHOST_ADMIN_SECRET: "secret",
		});
		expect(config.region).toBe("us-east-1");
	});

	it("trims whitespace from NHOST_ADMIN_SECRET (pins L55 .trim())", () => {
		const config = readAstropressNhostHostedConfig({
			NHOST_SUBDOMAIN: "xyz",
			NHOST_REGION: "us-east-1",
			NHOST_ADMIN_SECRET: "  secret  ",
		});
		expect(config.adminSecret).toBe("secret");
	});
});

tests/webhooks-d1.test.ts.source:
// Mutation-coverage + behavioral tests for the D1 webhook store
// (src/sqlite-runtime/webhooks-d1.ts), exercised through the SqliteBackedD1Database
// fixture. The D1 sibling #137 added must match the sqlite store's create /
// list / delete / dispatch semantics — including the ML-DSA signing headers and
// the last_fired_at bookkeeping — on every host that provides a D1 binding.
import { describe, expect, it, vi } from "vitest";

import { verifyMlDsaMessage } from "../src/crypto-primitives.js";
import { createD1WebhookStore } from "../src/sqlite-runtime/webhooks-d1.js";
import { makeDb } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

const { loggerErrorSpy } = vi.hoisted(() => ({ loggerErrorSpy: vi.fn() }));

vi.mock("../src/runtime-logger", () => ({
	createLogger: () => ({
		info: vi.fn(),
		warn: vi.fn(),
		error: loggerErrorSpy,
	}),
}));

function makeStore(fetchImpl: typeof fetch = fetch) {
	const db = makeDb();
	const d1 = new SqliteBackedD1Database(db);
	return { db, store: createD1WebhookStore(d1, fetchImpl) };
}

describe("createD1WebhookStore", () => {
	it("create: returns a one-time ML-DSA verification bundle and stores only the secret", async () => {
		const { db, store } = makeStore();
		const { record, verification } = await store.create({
			url: "https://example.com/hook",
			events: ["content.published"],
		});

		expect(verification.algorithm).toBe("ML-DSA-65");
		expect(verification.keyId).toBe(record.id);
		expect(verification.publicKey.length).toBeGreaterThan(100);
		expect(record.id.startsWith("wh_")).toBe(true);
		expect(record.active).toBe(true);
		expect(record.events).toEqual(["content.published"]);

		const row = db.prepare("SELECT secret_hash FROM webhooks WHERE id = ?").get(record.id) as {
			secret_hash: string;
		};
		expect(row.secret_hash).not.toBe(verification.publicKey);
	});

	it("list: returns only active, non-deleted webhooks newest-first", async () => {
		const { store } = makeStore();
		const { record: r1 } = await store.create({
			url: "https://a.com/hook",
			events: ["content.published"],
		});
		const { record: r2 } = await store.create({
			url: "https://b.com/hook",
			events: ["media.uploaded"],
		});
		await store.delete(r1.id);

		const active = await store.list();
		expect(active.some((w) => w.id === r2.id)).toBe(true);
		expect(active.some((w) => w.id === r1.id)).toBe(false);
	});

	it("list: maps the active column to a boolean", async () => {
		const { db, store } = makeStore();
		db.prepare(
			"INSERT INTO webhooks (id, url, events, secret_hash, active) VALUES (?, ?, ?, ?, ?)",
		).run("wh_on", "https://on.example.com", JSON.stringify(["content.published"]), "secret", 1);
		db.prepare(
			"INSERT INTO webhooks (id, url, events, secret_hash, active) VALUES (?, ?, ?, ?, ?)",
		).run("wh_off", "https://off.example.com", JSON.stringify(["content.published"]), "secret", 0);

		const list = await store.list();
		expect(list.find((w) => w.id === "wh_on")?.active).toBe(true);
		expect(list.find((w) => w.id === "wh_off")?.active).toBe(false);
	});

	it("delete: soft-deletes (sets deleted_at) so the webhook drops out of list", async () => {
		const { db, store } = makeStore();
		const { record } = await store.create({
			url: "https://c.com/hook",
			events: ["content.deleted"],
		});

		await store.delete(record.id);
		const row = db.prepare("SELECT deleted_at FROM webhooks WHERE id = ?").get(record.id) as {
			deleted_at: string | null;
		};
		expect(row.deleted_at).not.toBeNull();
		expect((await store.list()).some((w) => w.id === record.id)).toBe(false);
	});

	it("dispatch: POSTs an ML-DSA-65 signed body with the documented headers", async () => {
		let captured: Request | undefined;
		const mockFetch = async (req: Request) => {
			captured = req;
			return new Response("ok", { status: 200 });
		};
		const { store } = makeStore(mockFetch as typeof fetch);
		const { record, verification } = await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});

		await store.dispatch("content.published", { id: "post-1", status: "published" });

		expect(captured?.method).toBe("POST");
		expect(captured?.headers.get("content-type")).toBe("application/json");
		expect(captured?.headers.get("x-astropress-signature-alg")).toBe("ML-DSA-65");
		expect(captured?.headers.get("x-astropress-key-id")).toBe(record.id);

		const sig = captured?.headers.get("x-astropress-signature");
		const body = await captured?.clone().text();
		expect(verifyMlDsaMessage(body, sig as string, verification.publicKey)).toBe(true);

		const parsed = JSON.parse(body ?? "{}") as {
			event?: string;
			payload?: { id?: string; status?: string };
			timestamp?: string;
		};
		expect(parsed.event).toBe("content.published");
		expect(parsed.payload).toEqual({ id: "post-1", status: "published" });
		expect(typeof parsed.timestamp).toBe("string");
	});

	it("dispatch: skips webhooks not subscribed to the event", async () => {
		let callCount = 0;
		const mockFetch = async () => {
			callCount++;
			return new Response("ok", { status: 200 });
		};
		const { store } = makeStore(mockFetch as typeof fetch);
		await store.create({ url: "https://media.example.com/hook", events: ["media.uploaded"] });

		await store.dispatch("content.published", { id: "x" });
		expect(callCount).toBe(0);
	});

	it("dispatch: records last_fired_at on success", async () => {
		const mockFetch = async () => new Response("ok", { status: 200 });
		const { db, store } = makeStore(mockFetch as typeof fetch);
		const { record } = await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});

		await store.dispatch("content.published", { id: "x" });
		const row = db.prepare("SELECT last_fired_at FROM webhooks WHERE id = ?").get(record.id) as {
			last_fired_at: string | null;
		};
		expect(row.last_fired_at).not.toBeNull();

		const listed = (await store.list()).find((w) => w.id === record.id);
		expect(typeof listed?.lastFiredAt).toBe("string");
	});

	it("dispatch: a failed delivery leaves last_fired_at NULL, logs the error, and does not throw", async () => {
		loggerErrorSpy.mockClear();
		const mockFetch = async () => {
			throw new Error("Network error");
		};
		const { db, store } = makeStore(mockFetch as typeof fetch);
		const { record } = await store.create({
			url: "https://fail.example.com/hook",
			events: ["content.updated"],
		});

		await expect(store.dispatch("content.updated", { id: "x" })).resolves.not.toThrow();

		const row = db.prepare("SELECT last_fired_at FROM webhooks WHERE id = ?").get(record.id) as {
			last_fired_at: string | null;
		};
		expect(row.last_fired_at).toBeNull();

		expect(loggerErrorSpy).toHaveBeenCalledTimes(1);
		const [message, meta] = loggerErrorSpy.mock.calls[0] as [string, { error?: unknown }];
		expect(message).toContain("content.updated");
		expect(message).toContain("https://fail.example.com/hook");
		expect(meta.error).toBeInstanceOf(Error);
	});
});

tests/deployment-matrix.test.ts.source:
import { describe, expect, it } from "vitest";
import {
	getAstropressDeploymentMatrixEntry,
	listAstropressDeploymentMatrixEntries,
	resolveAstropressDeploymentSupportLevel,
} from "../src/deployment-matrix.js";

describe("listAstropressDeploymentMatrixEntries", () => {
	// Pins the .slice() defensive copy so callers can mutate the returned
	// array without poisoning the next call. Without .slice(), the
	// MethodExpression mutant would let mutations bleed across calls.
	it("returns a fresh array each call (defensive copy)", () => {
		const a = listAstropressDeploymentMatrixEntries();
		const b = listAstropressDeploymentMatrixEntries();
		expect(a).not.toBe(b);
