import {
	type AstropressPlatformAdapter,
	type AuthUser,
	assertProviderContract,
	type ContentStoreRecord,
	isAuthUserAdmin,
	type MediaAssetRecord,
	normalizeProviderCapabilities,
	type RevisionRecord,
} from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";

function createInMemoryAdapter(): AstropressPlatformAdapter {
	const records = new Map<string, ContentStoreRecord>();
	const media = new Map<string, MediaAssetRecord>();
	const revisions = new Map<string, RevisionRecord[]>();
	const sessions = new Map<string, AuthUser>();

	return {
		capabilities: normalizeProviderCapabilities({
			name: "custom",
			hostedAdmin: true,
			database: true,
			gitSync: true,
		}),
		content: {
			async list(kind) {
				return [...records.values()].filter((record) => !kind || record.kind === kind);
			},
			async get(id) {
				return records.get(id) ?? null;
			},
			async save(record) {
				records.set(record.id, record);
				return record;
			},
			async delete(id) {
				records.delete(id);
			},
		},
		media: {
			async put(asset) {
				media.set(asset.id, asset);
				return asset;
			},
			async get(id) {
				return media.get(id) ?? null;
			},
			async delete(id) {
				media.delete(id);
			},
		},
		revisions: {
			async list(recordId) {
				return revisions.get(recordId) ?? [];
			},
			async append(revision) {
				const existing = revisions.get(revision.recordId) ?? [];
				existing.push(revision);
				revisions.set(revision.recordId, existing);
				return revision;
			},
		},
		auth: {
			async signIn(email) {
				const user = { id: "u1", email, role: "admin" as const };
				sessions.set("session-1", user);
				return user;
			},
			async signOut(sessionId) {
				sessions.delete(sessionId);
			},
			async getSession(sessionId) {
				return sessions.get(sessionId) ?? null;
			},
		},
		gitSync: {
			async exportSnapshot(targetDir) {
				return { targetDir, fileCount: 4 };
			},
			async importSnapshot(sourceDir) {
				return { sourceDir, fileCount: 4 };
			},
		},
	};
}

describe("platform contracts", () => {
	it("fills omitted capability flags with false and preserves explicitly set flags", () => {
		const result = normalizeProviderCapabilities({
			name: "supabase",
			database: true,
		});
		expect(result.name).toBe("supabase");
		expect(result.database).toBe(true);
		const defaultFalseFlags = [
			"staticPublishing",
			"hostedAdmin",
			"previewEnvironments",
			"serverRuntime",
			"objectStorage",
			"gitSync",
		] as const;
		for (const flag of defaultFalseFlags) {
			expect(result[flag]).toBe(false);
		}
	});

	it("defaults database flag to false when omitted", () => {
		const result = normalizeProviderCapabilities({ name: "static-only" });
		expect(result.database).toBe(false);
	});

	it("preserves unknown provider names as-is", () => {
		const result = normalizeProviderCapabilities({
			name: "my-custom-provider",
		});
		expect(result.name).toBe("my-custom-provider");
	});

	it("accepts an adapter that satisfies the required contracts", async () => {
		const adapter = assertProviderContract(createInMemoryAdapter());
		const saved = await adapter.content.save({
			id: "page-1",
			kind: "page",
			slug: "home",
			status: "draft",
			title: "Home",
		});

		expect(saved.slug).toBe("home");
		expect((await adapter.content.list("page")).length).toBe(1);
	});

	it("rejects adapters that omit required stores", () => {
		expect(() =>
			assertProviderContract({
				capabilities: normalizeProviderCapabilities({ name: "custom" }),
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("rejects adapters with no capabilities name", () => {
		expect(() =>
			assertProviderContract({
				...createInMemoryAdapter(),
				capabilities: { ...normalizeProviderCapabilities({ name: "" }) },
			}),
		).toThrow(/must declare a name/i);
	});

	it("rejects an adapter missing only the content store", () => {
		const base = createInMemoryAdapter();
		expect(() =>
			assertProviderContract({
				...base,
				content: undefined,
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("rejects an adapter missing only the media store", () => {
		const base = createInMemoryAdapter();
		expect(() =>
			assertProviderContract({
				...base,
				media: undefined,
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("rejects an adapter missing only the revisions store", () => {
		const base = createInMemoryAdapter();
		expect(() =>
			assertProviderContract({
				...base,
				revisions: undefined,
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("rejects an adapter missing only the auth store", () => {
		const base = createInMemoryAdapter();
		expect(() =>
			assertProviderContract({
				...base,
				auth: undefined,
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("normalizeProviderCapabilities preserves an explicitly-provided hostPanel and deployHook", () => {
		const result = normalizeProviderCapabilities({
			name: "custom",
			hostPanel: { url: "https://panel.example" },
			deployHook: { url: "https://deploy.example" },
		});
		expect(result.hostPanel).toEqual({ url: "https://panel.example" });
		expect(result.deployHook).toEqual({ url: "https://deploy.example" });
	});

	describe("isAuthUserAdmin", () => {
		const base: AuthUser = { id: "u", email: "x@y", role: "admin" };
		it("returns true when isAdmin === true", () => {
			expect(isAuthUserAdmin({ ...base, isAdmin: true })).toBe(true);
		});
		it("returns false when isAdmin is false", () => {
			expect(isAuthUserAdmin({ ...base, isAdmin: false })).toBe(false);
		});
		it("returns false when isAdmin is undefined", () => {
			expect(isAuthUserAdmin(base)).toBe(false);
		});
		// Pin the strict equality check: isAdmin === true must reject truthy non-true.
		it("returns false when isAdmin is a truthy non-boolean (1)", () => {
			expect(isAuthUserAdmin({ ...base, isAdmin: 1 as unknown as boolean })).toBe(false);
		});
	});

	it("supports full content CRUD lifecycle", async () => {
		const adapter = assertProviderContract(createInMemoryAdapter());

		const record = await adapter.content.save({
			id: "post-1",
			kind: "post",
			slug: "hello",
			status: "draft",
			title: "Hello",
		});
		expect(record.id).toBe("post-1");

		const fetched = await adapter.content.get("post-1");
		expect(fetched?.slug).toBe("hello");

		const all = await adapter.content.list("post");
		expect(all).toHaveLength(1);

		await adapter.content.delete("post-1");
		expect(await adapter.content.get("post-1")).toBeNull();
		expect(await adapter.content.list("post")).toHaveLength(0);
	});
});

tests/integrations/registry.test.ts.source:
import { afterEach, describe, expect, it } from "vitest";
import { z } from "zod";

import {
	registerAbTesting,
	registerAnalytics,
	registerCdnPurge,
	registerDeployHooks,
	registerForms,
	registerMonitoring,
	registerNewsletter,
	registerSearch,
} from "../../src/integrations/domains";
import {
	_resetRegistryForTests,
	getProvider,
	IntegrationRegistryError,
	listProviders,
	registerProvider,
} from "../../src/integrations/registry";

const noopVerify = async () => {
	/* no-op */
};

const baseDef = {
	id: "test-provider",
	label: "Test Provider",
	fields: z.object({ apiKey: z.string() }),
	verify: noopVerify,
};

afterEach(() => {
	_resetRegistryForTests();
});

describe("integration registry", () => {
	it("registers and looks up a provider by (domain, id)", () => {
		registerProvider("newsletter", baseDef);
		const found = getProvider("newsletter", "test-provider");
		expect(found?.id).toBe("test-provider");
		expect(found?.domain).toBe("newsletter");
	});

	it("isolates providers per domain (same id, different domain)", () => {
		registerProvider("newsletter", baseDef);
		registerProvider("analytics", baseDef);
		expect(getProvider("newsletter", "test-provider")?.domain).toBe("newsletter");
		expect(getProvider("analytics", "test-provider")?.domain).toBe("analytics");
	});

	it("rejects duplicate registration in the same domain", () => {
		registerProvider("newsletter", baseDef);
		expect(() => registerProvider("newsletter", baseDef)).toThrowError(IntegrationRegistryError);
	});

	it("rejects an unknown domain", () => {
		expect(() =>
			// @ts-expect-error — runtime guard for hosts cast through `any`
			registerProvider("not-a-domain", baseDef),
		).toThrowError(IntegrationRegistryError);
	});

	it("listProviders returns only matches for the domain", () => {
		registerProvider("newsletter", { ...baseDef, id: "a" });
		registerProvider("newsletter", { ...baseDef, id: "b" });
		registerProvider("analytics", { ...baseDef, id: "a" });
		const newsletterIds = listProviders("newsletter")
			.map((p) => p.id)
			.sort();
		expect(newsletterIds).toEqual(["a", "b"]);
	});

	it("every typed wrapper pins the right domain", () => {
		registerNewsletter({ ...baseDef, id: "ml1" });
		registerAnalytics({ ...baseDef, id: "an1" });
		registerAbTesting({ ...baseDef, id: "ab1" });
		registerSearch({ ...baseDef, id: "se1" });
		registerCdnPurge({ ...baseDef, id: "cd1" });
		registerMonitoring({ ...baseDef, id: "mn1" });
		registerForms({ ...baseDef, id: "fm1" });
		registerDeployHooks({ ...baseDef, id: "dh1" });
		expect(getProvider("newsletter", "ml1")?.domain).toBe("newsletter");
		expect(getProvider("analytics", "an1")?.domain).toBe("analytics");
		expect(getProvider("ab-testing", "ab1")?.domain).toBe("ab-testing");
		expect(getProvider("search", "se1")?.domain).toBe("search");
		expect(getProvider("cdn-purge", "cd1")?.domain).toBe("cdn-purge");
		expect(getProvider("monitoring", "mn1")?.domain).toBe("monitoring");
		expect(getProvider("forms", "fm1")?.domain).toBe("forms");
		expect(getProvider("deploy-hooks", "dh1")?.domain).toBe("deploy-hooks");
	});

	it("getProvider returns undefined for unknown id", () => {
		registerProvider("newsletter", baseDef);
		expect(getProvider("newsletter", "missing")).toBeUndefined();
	});

	it("preserves verify callback and runtimeShape on lookup", () => {
		const fields = z.object({ apiKey: z.string() });
		const runtimeShape = z.object({ apiKey: z.string().min(8) });
		registerProvider("newsletter", {
			id: "shape",
			label: "Shape",
			fields,
			runtimeShape,
			verify: noopVerify,
		});
		const found = getProvider("newsletter", "shape");
		expect(found?.runtimeShape).toBe(runtimeShape);
		expect(found?.verify).toBe(noopVerify);
	});

	it("IntegrationRegistryError carries the typed code", () => {
		registerProvider("newsletter", baseDef);
		try {
			registerProvider("newsletter", baseDef);
			throw new Error("expected throw");
		} catch (err) {
			expect(err).toBeInstanceOf(IntegrationRegistryError);
			expect((err as IntegrationRegistryError).code).toBe("DUPLICATE_PROVIDER");
			expect((err as Error).name).toBe("IntegrationRegistryError");
		}
	});

	it("UNKNOWN_DOMAIN error code is set", () => {
		try {
			// @ts-expect-error
			registerProvider("bogus", baseDef);
			throw new Error("expected throw");
		} catch (err) {
			expect((err as IntegrationRegistryError).code).toBe("UNKNOWN_DOMAIN");
		}
	});

	it("listProviders returns empty array for empty domain", () => {
		expect(listProviders("monitoring")).toEqual([]);
	});

	it("registerProvider returns the registered entry with domain pinned", () => {
		const out = registerProvider("forms", { ...baseDef, id: "tally" });
		expect(out.domain).toBe("forms");
		expect(out.id).toBe("tally");
		expect(out.label).toBe("Test Provider");
	});

	it("INTEGRATION_DOMAINS contains every typed domain literal", () => {
		// Forces each string literal to remain in the typed array; a
		// stryker StringLiteral mutant on any of them would break a
		// registration with that domain.
		registerProvider("newsletter", { ...baseDef, id: "p" });
		registerProvider("analytics", { ...baseDef, id: "p" });
		registerProvider("ab-testing", { ...baseDef, id: "p" });
		registerProvider("search", { ...baseDef, id: "p" });
		registerProvider("cdn-purge", { ...baseDef, id: "p" });
		registerProvider("monitoring", { ...baseDef, id: "p" });
		registerProvider("forms", { ...baseDef, id: "p" });
		registerProvider("deploy-hooks", { ...baseDef, id: "p" });
		expect(getProvider("newsletter", "p")?.domain).toBe("newsletter");
		expect(getProvider("analytics", "p")?.domain).toBe("analytics");
		expect(getProvider("ab-testing", "p")?.domain).toBe("ab-testing");
		expect(getProvider("search", "p")?.domain).toBe("search");
		expect(getProvider("cdn-purge", "p")?.domain).toBe("cdn-purge");
		expect(getProvider("monitoring", "p")?.domain).toBe("monitoring");
		expect(getProvider("forms", "p")?.domain).toBe("forms");
		expect(getProvider("deploy-hooks", "p")?.domain).toBe("deploy-hooks");
	});

	it("DUPLICATE_PROVIDER error message names the domain and id", () => {
		registerProvider("newsletter", baseDef);
		try {
			registerProvider("newsletter", baseDef);
			throw new Error("expected throw");
		} catch (err) {
			expect((err as Error).message).toContain("test-provider");
			expect((err as Error).message).toContain("newsletter");
		}
	});

	it("UNKNOWN_DOMAIN error message names the offending domain", () => {
		try {
			// @ts-expect-error
			registerProvider("not-real", baseDef);
			throw new Error("expected throw");
		} catch (err) {
			expect((err as Error).message).toContain("not-real");
		}
	});
});

