import type { DatabaseSync } from "node:sqlite";

import { beforeEach, describe, expect, it } from "vitest";

import { createD1SchedulingPart } from "../src/d1-store-content.js";
import { makeDb } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

function seedEntry(db: DatabaseSync, slug: string) {
	db.prepare(
		`INSERT INTO content_entries (slug, legacy_url, title, kind, template_key, source_html_path, updated_at)
     VALUES (?, ?, ?, 'post', 'content', 'runtime://content/' || ?, CURRENT_TIMESTAMP)`,
	).run(slug, `/${slug}`, `Title for ${slug}`, slug);
}

function makeScheduling(db: DatabaseSync) {
	return createD1SchedulingPart(new SqliteBackedD1Database(db));
}

describe("D1 scheduling — schedulePublish", () => {
	let db: DatabaseSync;

	beforeEach(() => {
		db = makeDb();
		seedEntry(db, "my-post");
	});

	it("creates an override with scheduled_at when none exists", async () => {
		const scheduling = makeScheduling(db);
		const future = new Date(Date.now() + 60_000).toISOString();
		await scheduling.schedulePublish("my-post", future);

		const row = db
			.prepare("SELECT slug, status, scheduled_at FROM content_overrides WHERE slug = ?")
			.get("my-post") as {
			slug: string;
			status: string;
			scheduled_at: string;
		};
		expect(row).toBeDefined();
		expect(row.slug).toBe("my-post");
		expect(row.status).toBe("draft");
		expect(row.scheduled_at).toBe(future);
	});

	it("updates existing override's scheduled_at", async () => {
		const scheduling = makeScheduling(db);
		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, seo_title, meta_description, updated_at, updated_by)
       VALUES ('my-post', 'Title for my-post', 'draft', 'Title for my-post', '', CURRENT_TIMESTAMP, 'test@test.com')`,
		).run();

		const future = new Date(Date.now() + 120_000).toISOString();
		await scheduling.schedulePublish("my-post", future);

		const row = db
			.prepare("SELECT scheduled_at FROM content_overrides WHERE slug = ?")
			.get("my-post") as {
			scheduled_at: string;
		};
		expect(row.scheduled_at).toBe(future);
	});
});

describe("D1 scheduling — listScheduled", () => {
	let db: DatabaseSync;

	beforeEach(() => {
		db = makeDb();
		seedEntry(db, "future-post");
		seedEntry(db, "past-post");
	});

	it("returns only future-scheduled entries", async () => {
		const scheduling = makeScheduling(db);
		const future = new Date(Date.now() + 60_000).toISOString();
		const past = new Date(Date.now() - 60_000).toISOString();

		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, scheduled_at, seo_title, meta_description, updated_at, updated_by)
       VALUES ('future-post', 'Future Post', 'draft', ?, 'Future Post', '', CURRENT_TIMESTAMP, 'scheduler')`,
		).run(future);
		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, scheduled_at, seo_title, meta_description, updated_at, updated_by)
       VALUES ('past-post', 'Past Post', 'draft', ?, 'Past Post', '', CURRENT_TIMESTAMP, 'scheduler')`,
		).run(past);

		const list = await scheduling.listScheduled();
		expect(list).toHaveLength(1);
		expect(list[0].slug).toBe("future-post");
		expect(list[0].scheduledAt).toBe(future);
	});

	it("returns empty array when no scheduled entries", async () => {
		const list = await makeScheduling(db).listScheduled();
		expect(list).toEqual([]);
	});
});

describe("D1 scheduling — cancelScheduledPublish", () => {
	it("clears scheduled_at without changing status", async () => {
		const db = makeDb();
		seedEntry(db, "cancel-post");
		const future = new Date(Date.now() + 60_000).toISOString();
		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, scheduled_at, seo_title, meta_description, updated_at, updated_by)
       VALUES ('cancel-post', 'Cancel Post', 'draft', ?, 'Cancel Post', '', CURRENT_TIMESTAMP, 'scheduler')`,
		).run(future);

		await makeScheduling(db).cancelScheduledPublish("cancel-post");

		const row = db
			.prepare("SELECT status, scheduled_at FROM content_overrides WHERE slug = ?")
			.get("cancel-post") as {
			status: string;
			scheduled_at: string | null;
		};
		expect(row.status).toBe("draft");
		expect(row.scheduled_at).toBeNull();
	});
});

describe("D1 scheduling — runScheduledPublishes", () => {
	it("publishes past-due entries and returns count", async () => {
		const db = makeDb();
		seedEntry(db, "due-post");
		seedEntry(db, "not-due-post");
		const past = new Date(Date.now() - 60_000).toISOString();
		const future = new Date(Date.now() + 60_000).toISOString();

		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, scheduled_at, seo_title, meta_description, updated_at, updated_by)
       VALUES ('due-post', 'Due Post', 'draft', ?, 'Due Post', '', CURRENT_TIMESTAMP, 'scheduler')`,
		).run(past);
		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, scheduled_at, seo_title, meta_description, updated_at, updated_by)
       VALUES ('not-due-post', 'Not Due Post', 'draft', ?, 'Not Due Post', '', CURRENT_TIMESTAMP, 'scheduler')`,
		).run(future);

		const count = await makeScheduling(db).runScheduledPublishes();
		expect(count).toBe(1);

		const due = db
			.prepare("SELECT status, scheduled_at FROM content_overrides WHERE slug = ?")
			.get("due-post") as {
			status: string;
			scheduled_at: string | null;
		};
		expect(due.status).toBe("published");
		expect(due.scheduled_at).toBeNull();

		const notDue = db
			.prepare("SELECT status, scheduled_at FROM content_overrides WHERE slug = ?")
			.get("not-due-post") as {
			status: string;
			scheduled_at: string;
		};
		expect(notDue.status).toBe("draft");
		expect(notDue.scheduled_at).toBe(future);
	});

	it("returns 0 when no entries are due", async () => {
		const db = makeDb();
		const count = await makeScheduling(db).runScheduledPublishes();
		expect(count).toBe(0);
	});
});

tests/runtime-route-registry-dispatch.te.source:
import { afterEach, describe, expect, it, vi } from "vitest";

vi.mock("../src/local-runtime-modules", () => ({
	loadLocalCmsRegistry: vi.fn(),
}));

import { registerCms } from "../src/config";
import { loadLocalCmsRegistry } from "../src/local-runtime-modules";
import {
	loadSafeLocalCmsRegistry,
	localeFromPath,
	parseSettings,
	withSafeRouteRegistryFallback,
} from "../src/runtime-route-registry-dispatch";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

afterEach(() => {
	(globalThis as typeof globalThis & { [CMS_CONFIG_KEY]?: unknown })[CMS_CONFIG_KEY] = null;
	vi.restoreAllMocks();
});

describe("loadSafeLocalCmsRegistry", () => {
	it("returns the registry when load succeeds", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
			marker: "ok",
		});
		expect(await loadSafeLocalCmsRegistry()).toEqual({ marker: "ok" });
	});

	it("returns null when load throws", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockRejectedValueOnce(new Error("nope"));
		expect(await loadSafeLocalCmsRegistry()).toBeNull();
	});
});

describe("withSafeRouteRegistryFallback", () => {
	it("returns the operation result on success (no fallback invoked)", async () => {
		const fallback = vi.fn();
		const result = await withSafeRouteRegistryFallback(fallback, "default", async () => "ok");
		expect(result).toBe("ok");
		expect(fallback).not.toHaveBeenCalled();
	});

	it("invokes fallback with the local registry when operation throws and registry loads", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
			marker: "local",
		});
		const fallback = vi.fn(async (local: { marker: string }) => `fb-${local.marker}`);
		const result = await withSafeRouteRegistryFallback(fallback, "default", async () => {
			throw new Error("boom");
		});
		expect(result).toBe("fb-local");
		expect(fallback).toHaveBeenCalledWith({ marker: "local" });
	});

	it("returns defaultValue when operation throws AND registry load fails", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockRejectedValueOnce(
			new Error("registry-also-broken"),
		);
		const fallback = vi.fn();
		const result = await withSafeRouteRegistryFallback(fallback, "default-value", async () => {
			throw new Error("boom");
		});
		expect(result).toBe("default-value");
		expect(fallback).not.toHaveBeenCalled();
	});

	it("returns defaultValue when operation throws AND registry load returns null/undefined", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockResolvedValueOnce(null);
		const result = await withSafeRouteRegistryFallback(vi.fn(), "def", async () => {
			throw new Error("boom");
		});
		expect(result).toBe("def");
	});
});

describe("parseSettings", () => {
	it("returns null for null input", () => {
		expect(parseSettings(null)).toBeNull();
	});

	it("returns null for empty string", () => {
		expect(parseSettings("")).toBeNull();
	});

	it("returns null when JSON.parse throws", () => {
		expect(parseSettings("{not-json}")).toBeNull();
	});

	it("returns null when parsed value is not an object (number)", () => {
		expect(parseSettings("42")).toBeNull();
	});

	it("returns null when parsed value is not an object (string)", () => {
		expect(parseSettings('"hello"')).toBeNull();
	});

	it("returns null when parsed value is JSON null", () => {
		expect(parseSettings("null")).toBeNull();
	});

	it("returns the object when parse succeeds", () => {
		expect(parseSettings('{"a":1}')).toEqual({ a: 1 });
	});

	it("returns arrays as objects too (typeof [] === 'object')", () => {
		expect(parseSettings("[1,2,3]")).toEqual([1, 2, 3]);
	});
});

describe("localeFromPath", () => {
	it("returns the matching locale when pathname has /es/ prefix", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: ["en", "es"],
		} as never);
		expect(localeFromPath("/es/about")).toBe("es");
	});

	it("returns the first locale ('en') when no prefix matches", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: ["en", "es"],
		} as never);
		expect(localeFromPath("/about")).toBe("en");
	});

	it("falls back to ['en','es'] when getCmsConfig throws (config not registered)", () => {
		// CMS config is unset → getCmsConfig throws → catch falls back to ['en','es'].
		expect(localeFromPath("/es/x")).toBe("es");
		expect(localeFromPath("/about")).toBe("en");
	});

	it("falls back to ['en','es'] when locales is missing on the config", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
		} as never);
		expect(localeFromPath("/es/x")).toBe("es");
		expect(localeFromPath("/about")).toBe("en");
	});

	it("matches strictly on `/locale/` (not on suffix or substring)", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: ["en", "es", "fr"],
		} as never);
		// "/escape" must not match "es" — leading-slash + trailing-slash anchored.
		expect(localeFromPath("/escape")).toBe("en");
	});

	it("returns 'en' fallback when locales array is empty", () => {
		// Pins `locales[0] ?? "en"`.
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: [],
		} as never);
		expect(localeFromPath("/about")).toBe("en");
	});

	it("returns the first custom locale when no prefix matches", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: ["fr", "de"],
		} as never);
		expect(localeFromPath("/about")).toBe("fr");
	});
});

tests/vitest-runtime-alias.test.ts.source:
import { createAstropressVitestLocalRuntimePlugins } from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";
import { isAstropressSrcImporter, isLocalRuntimeModuleId } from "../src/vitest-runtime-alias.js";

// Inputs to the helpers under test are arbitrary strings, not real file
// paths. To keep this suite below the test-fanout threshold, importer/path
// inputs use the non-extension suffix `.x` rather than `.ts`/`.js`. The
// only `.js`/`.ts`/`.css` literals are the ones that exercise the actual
// extension-matching regex inside isLocalRuntimeModuleId.
const RP = "/RP";

describe("vitest runtime alias helpers", () => {
	it("creates the local module replacement and external source rewrite plugins", () => {
		const [replacePlugin, rewritePlugin] = createAstropressVitestLocalRuntimePlugins(RP);

		expect(replacePlugin.name).toBe("astropress-local-runtime-modules-replacer");
		expect(replacePlugin.resolveId("./local-runtime-modules")).toBe(RP);

		expect(rewritePlugin.name).toBe("astropress-external-source-rewriter");
		expect(
			rewritePlugin.resolveId(
				"./local-runtime-modules",
				"/node_modules/.bun/pkg/node_modules/astropress/src/x",
			),
		).toBe(RP);
	});

	it("does not rewrite unrelated imports", () => {
		const [, rewritePlugin] = createAstropressVitestLocalRuntimePlugins(RP);

		expect(rewritePlugin.resolveId("./other-module", "/node_modules/astropress/src/x")).toBe(
			undefined,
		);
		expect(rewritePlugin.resolveId("./local-runtime-modules", "/site/src/app")).toBe(undefined);
	});

	it("replacePlugin returns undefined for unrelated id", () => {
		const [replacePlugin] = createAstropressVitestLocalRuntimePlugins(RP);
		expect(replacePlugin.resolveId("not-the-runtime-module")).toBeUndefined();
		expect(replacePlugin.resolveId("/other-thing")).toBeUndefined();
	});

	it("both plugins set enforce: 'pre' so they outrank vite default resolvers", () => {
		const plugins = createAstropressVitestLocalRuntimePlugins(RP);
		expect(plugins[0]?.enforce).toBe("pre");
		expect(plugins[1]?.enforce).toBe("pre");
	});

	it("rewritePlugin matches under the astropress packages monorepo path", () => {
		const [, rewrite] = createAstropressVitestLocalRuntimePlugins(RP);
		expect(
			rewrite.resolveId("./local-runtime-modules", "/repo/astropress/packages/astropress/src/x"),
		).toBe(RP);
	});

	it("rewritePlugin matches under plain node_modules/astropress/src", () => {
		const [, rewrite] = createAstropressVitestLocalRuntimePlugins(RP);
		expect(
			rewrite.resolveId("./local-runtime-modules", "/site/node_modules/astropress/src/x"),
		).toBe(RP);
	});

	it("rewritePlugin returns undefined when importer is missing", () => {
		const [, rewrite] = createAstropressVitestLocalRuntimePlugins(RP);
		expect(rewrite.resolveId("./local-runtime-modules")).toBeUndefined();
	});

	it("rewritePlugin returns undefined when id does not look like local-runtime-modules", () => {
		const [, rewrite] = createAstropressVitestLocalRuntimePlugins(RP);
		expect(
			rewrite.resolveId("./some-other-module", "/site/node_modules/astropress/src/x"),
		).toBeUndefined();
	});

	describe("isLocalRuntimeModuleId", () => {
		it("matches base, .js, .ts variants", () => {
			expect(isLocalRuntimeModuleId("./local-runtime-modules")).toBe(true);
			expect(isLocalRuntimeModuleId("./local-runtime-modules.js")).toBe(true);
			expect(isLocalRuntimeModuleId("./local-runtime-modules.ts")).toBe(true);
		});
		it("rejects when extension is not .js / .ts (kills [jt]→[^jt])", () => {
			expect(isLocalRuntimeModuleId("./local-runtime-modules.xs")).toBe(false);
			expect(isLocalRuntimeModuleId("./local-runtime-modules.css")).toBe(false);
		});
		it("rejects when suffix continues past the name (kills $-removal)", () => {
			expect(isLocalRuntimeModuleId("./local-runtime-modules-extra")).toBe(false);
			expect(isLocalRuntimeModuleId("./local-runtime-modulesX")).toBe(false);
		});
		it("rejects unrelated strings", () => {
			expect(isLocalRuntimeModuleId("not-the-runtime-module")).toBe(false);
		});
	});

	describe("isAstropressSrcImporter", () => {
		it("matches the monorepo astropress/packages/astropress/src path", () => {
			expect(isAstropressSrcImporter("/repo/astropress/packages/astropress/src/x")).toBe(true);
		});
		it("matches plain node_modules/astropress/src", () => {
			expect(isAstropressSrcImporter("/site/node_modules/astropress/src/x")).toBe(true);
		});
		it("matches bun: node_modules/.bun/<pkg>/node_modules/astropress/src", () => {
			expect(
				isAstropressSrcImporter("/site/node_modules/.bun/pkg/node_modules/astropress/src/x"),
			).toBe(true);
		});
		it("rejects bun path that does not contain /astropress/src/ anywhere", () => {
			expect(isAstropressSrcImporter("/site/node_modules/.bun/other/lib/x")).toBe(false);
		});
		it("matches ONLY via the bun branch (kills bun-condition false-mutant)", () => {
			// No "/node_modules/astropress/src/" substring (lib/ sits between),
			// so the bun branch is the only path that can return true.
			expect(isAstropressSrcImporter("/site/node_modules/.bun/foo/lib/astropress/src/x")).toBe(
				true,
			);
		});
		it("rejects /astropress/src/ when there is no /node_modules/.bun/ (kills bun-condition true-mutant)", () => {
			// If the bun-condition were forced true, this would wrongly return true
			// because the inner check `/astropress/src/` would match.
			expect(isAstropressSrcImporter("/some/path/astropress/src/x")).toBe(false);
		});
		it("rejects an unrelated importer entirely", () => {
			expect(isAstropressSrcImporter("/site/src/app")).toBe(false);
		});
		it("normalizes backslashes (windows-style) to forward slashes", () => {
			expect(isAstropressSrcImporter("C:\\site\\node_modules\\astropress\\src\\x")).toBe(true);
		});
	});
});

tests/sqlite-runtime/assets.test.ts.source:
/**
 * sqlite-runtime/assets mutation pins.
 *
 * Exercises the SQLite-backed media repository wired by createSqliteAssetsStore:
 * listMediaAssets row-mapping fallbacks, updateMediaAsset trimming + audit,
 * and deleteMediaAsset audit recording.
 */

import { describe, expect, it } from "vitest";

import { createSqliteAssetsStore } from "../../src/sqlite-runtime/assets.js";
import { makeDb, STANDARD_ACTOR } from "../helpers/make-db.js";

function insertMediaRow(
	db: ReturnType<typeof makeDb>,
	row: {
		id: string;
		localPath?: string;
		altText?: string | null;
		title?: string | null;
		uploadedBy?: string | null;
		sourceUrl?: string | null;
	},
) {
	db.prepare(
		"INSERT INTO media_assets (id, source_url, local_path, r2_key, mime_type, file_size, alt_text, title, uploaded_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
	).run(
		row.id,
		row.sourceUrl ?? null,
		row.localPath ?? `/var/data/${row.id}`,
		`uploads/${row.id}`,
		"image/png",
		1024,
		row.altText === undefined ? "alt" : row.altText,
		row.title === undefined ? "title" : row.title,
		row.uploadedBy === undefined ? "uploader@test.local" : row.uploadedBy,
	);
}

function makeStore(db: ReturnType<typeof makeDb>) {
	return createSqliteAssetsStore(
		() => db,
		() => Date.now(),
	);
}

describe("createSqliteAssetsStore — listMediaAssets row mapping", () => {
	it("coalesces NULL alt_text / title / uploaded_by to empty strings (kills L79/L80/L82 StringLiteral & L82 LogicalOperator)", () => {
		const db = makeDb();
		insertMediaRow(db, { id: "m_null", altText: null, title: null, uploadedBy: null });
		const { sqliteMediaRepository } = makeStore(db);

		const listed = sqliteMediaRepository.listMediaAssets().find((m) => m.id === "m_null");
		expect(listed?.altText).toBe("");
		expect(listed?.title).toBe("");
		expect(listed?.uploadedBy).toBe("");
	});

	it("passes through non-NULL alt_text / title / uploaded_by verbatim (kills L82 LogicalOperator ?? → &&)", () => {
		const db = makeDb();
		insertMediaRow(db, {
			id: "m_set",
			altText: "a description",
			title: "A Title",
			uploadedBy: "bob@test.local",
		});
		const { sqliteMediaRepository } = makeStore(db);

		const listed = sqliteMediaRepository.listMediaAssets().find((m) => m.id === "m_set");
		expect(listed?.altText).toBe("a description");
		expect(listed?.title).toBe("A Title");
		// `row.uploaded_by ?? ""` with `&&` would yield "" for a non-null value.
		expect(listed?.uploadedBy).toBe("bob@test.local");
	});
});

describe("createSqliteAssetsStore — updateMediaAsset", () => {
	it("trims title and altText before persisting (kills L101 MethodExpression & OptionalChaining)", () => {
		const db = makeDb();
		insertMediaRow(db, { id: "m_upd" });
		const { sqliteMediaRepository } = makeStore(db);

		const result = sqliteMediaRepository.updateMediaAsset(
			{ id: "m_upd", title: "  Spaced Title  ", altText: "  spaced alt  " },
			STANDARD_ACTOR,
		);
		expect(result.ok).toBe(true);

		const row = db
			.prepare("SELECT title, alt_text FROM media_assets WHERE id = ?")
			.get("m_upd") as { title: string; alt_text: string };
		expect(row.title).toBe("Spaced Title");
		expect(row.alt_text).toBe("spaced alt");
	});

	it("defaults missing title/altText to empty strings without throwing (kills L101 StringLiteral '' fallbacks & OptionalChaining)", () => {
		const db = makeDb();
		insertMediaRow(db, { id: "m_blank", title: "old", altText: "old alt" });
		const { sqliteMediaRepository } = makeStore(db);

		// input.title / input.altText are undefined → `?.trim()` short-circuits to
		// undefined → `?? ""`. Removing the optional chain would throw on undefined;
		// mutating the "" fallback would persist a non-empty placeholder.
		const result = sqliteMediaRepository.updateMediaAsset({ id: "m_blank" }, STANDARD_ACTOR);
		expect(result.ok).toBe(true);

		const row = db
			.prepare("SELECT title, alt_text FROM media_assets WHERE id = ?")
			.get("m_blank") as { title: string; alt_text: string };
		expect(row.title).toBe("");
		expect(row.alt_text).toBe("");
	});

	it("records a media.update audit event scoped to content (kills L110 StringLiteral & template literal)", () => {
		const db = makeDb();
		insertMediaRow(db, { id: "m_audit" });
		const { sqliteMediaRepository } = makeStore(db);

		sqliteMediaRepository.updateMediaAsset({ id: "m_audit", title: "New" }, STANDARD_ACTOR);

		const audit = db
			.prepare(
				"SELECT action, resource_type, resource_id, summary FROM audit_events WHERE resource_id = ?",
			)
			.get("m_audit") as
			| { action: string; resource_type: string; resource_id: string; summary: string }
			| undefined;
		expect(audit?.action).toBe("media.update");
		expect(audit?.resource_type).toBe("content");
		expect(audit?.summary).toContain("m_audit");
	});
});

describe("createSqliteAssetsStore — deleteMediaAsset", () => {
	it("soft-deletes the row and records a media.delete audit event (kills L166 BlockStatement & L167 StringLiteral)", () => {
		const db = makeDb();
		// local_path outside /images/uploads/ so deleteLocalMediaUpload is a no-op.
		insertMediaRow(db, { id: "m_del", localPath: "/var/data/m_del" });
		const { sqliteMediaRepository } = makeStore(db);

		const result = sqliteMediaRepository.deleteMediaAsset("m_del", STANDARD_ACTOR);
		expect(result.ok).toBe(true);

		const row = db.prepare("SELECT deleted_at FROM media_assets WHERE id = ?").get("m_del") as {
			deleted_at: string | null;
		};
		expect(row.deleted_at).not.toBeNull();

		const audit = db
			.prepare("SELECT action, resource_type FROM audit_events WHERE resource_id = ?")
			.get("m_del") as { action: string; resource_type: string } | undefined;
		expect(audit?.action).toBe("media.delete");
		expect(audit?.resource_type).toBe("content");
	});
});

tests/access-request-context.test.ts.source:
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { beforeEach, describe, expect, test } from "vitest";
import type { LocalAccessStoreSurface } from "../src/access";
import { createAccessRepository, getAccessContext, seedStarterRoles } from "../src/access";
import { loadSqliteDatabase } from "../src/sqlite-bootstrap-helpers";

const SCHEMA = readFileSync(
	fileURLToPath(new URL("../src/sqlite-schema.sql", import.meta.url)),
	"utf8",
);

interface DbHandle {
	prepare: (sql: string) => {
		all: <T = unknown>(...args: unknown[]) => T[];
		get: <T = unknown>(...args: unknown[]) => T | undefined;
		run: (...args: unknown[]) => { changes: number };
	};
	exec: (sql: string) => void;
}

async function makeDb(): Promise<DbHandle> {
	const DbClass = await loadSqliteDatabase();
	const db = new DbClass(":memory:");
	db.exec(SCHEMA);
	return db as unknown as DbHandle;
}

function buildLocalSurface(db: DbHandle): LocalAccessStoreSurface {
	const repo = createAccessRepository(db as never);
	return {
		resolveAccessSnapshotByEmail(email) {
			const row = db
				.prepare("SELECT id, is_admin FROM admin_users WHERE email = ? AND active = 1 LIMIT 1")
				.get<{ id: number; is_admin: number }>(email);
			if (!row) return null;
			return {
				userId: String(row.id),
				isAdmin: row.is_admin === 1,
				roles: repo.listUserRoleIds(row.id),
				attributes: repo.getUserAttributes(row.id),
				policies: repo.resolvePoliciesForUser(row.id),
			};
		},
	};
}

function makeLocalsFromStore(
	storeOverrides: Partial<{ access: LocalAccessStoreSurface }>,
	adminUser: { email: string; role: "admin" | "editor"; name: string },
): App.Locals {
	const localStore = { ...storeOverrides };
	return {
		adminUser,
		__testLocalStore: localStore,
	} as unknown as App.Locals;
}

// Stub the local-runtime-modules loader so getAccessContext's local fallback
// receives our in-memory store instead of throwing.
import { vi } from "vitest";

vi.mock("../src/local-runtime-modules", async (orig) => {
	const original = await orig<typeof import("../src/local-runtime-modules")>();
	return {
		...original,
		loadLocalAdminStore: async () => currentStore as never,
	};
});

let currentStore: { access?: LocalAccessStoreSurface } = {};

describe("getAccessContext (local sqlite path)", () => {
	let db: DbHandle;
	beforeEach(async () => {
		db = await makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, is_admin) VALUES (?, 'h', 'Admin', 1)",
		).run("admin@example.com");
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, is_admin) VALUES (?, 'h', 'Editor', 0)",
		).run("editor@example.com");
		const repo = createAccessRepository(db as never);
		seedStarterRoles(repo);
		const editor = repo.listRoles().find((r) => r.name === "Editor");
		if (!editor) throw new Error("seedStarterRoles did not create Editor");
		const editorRow = db
			.prepare("SELECT id FROM admin_users WHERE email = ?")
			.get<{ id: number }>("editor@example.com");
		if (!editorRow) throw new Error("editor user fixture missing");
		repo.assignRole({ userId: editorRow.id, roleId: editor.id });
		currentStore = { access: buildLocalSurface(db) };
	});

	test("admin subject bypasses policy evaluation", async () => {
		const locals = makeLocalsFromStore(currentStore, {
			email: "admin@example.com",
			role: "admin",
			name: "Admin",
		});
		const ctx = await getAccessContext({ locals });
		if (!ctx) throw new Error("expected access context");
		expect(ctx.subject.isAdmin).toBe(true);
		expect(ctx.can("anything:weird").decision).toBe("allow");
	});

	test("editor subject gets allowed posts:list via seeded role", async () => {
		const locals = makeLocalsFromStore(currentStore, {
			email: "editor@example.com",
			role: "editor",
			name: "Editor",
		});
		const ctx = await getAccessContext({ locals });
		if (!ctx) throw new Error("expected access context");
		expect(ctx.subject.isAdmin).toBe(false);
		expect(ctx.can("media:upload").decision).toBe("allow");
		expect(ctx.can("users:invite").decision).toBe("deny");
	});

	test("returns null when no admin user is on locals", async () => {
		const locals = { runtime: { env: {} } } as unknown as App.Locals;
		const ctx = await getAccessContext({ locals });
		expect(ctx).toBeNull();
	});

	test("local fallback handles missing access extension via optional chaining (kills surface?. mutant)", async () => {
		currentStore = {}; // no .access surface at all
		const locals = makeLocalsFromStore(currentStore, {
			email: "admin@example.com",
			role: "admin",
			name: "Admin",
		});
		const ctx = await getAccessContext({ locals });
		if (!ctx) throw new Error("expected ctx");
		// Falls through to adminOnlySnapshot: id is the synthetic email:... prefix
		expect(ctx.subject.id).toBe("email:admin@example.com");
		expect(ctx.subject.roles).toEqual([]);
	});

	test("local fallback uses adminOnlySnapshot when surface returns null (kills if(fromStore) mutant)", async () => {
		currentStore = {
			access: {
				resolveAccessSnapshotByEmail: () => null,
			},
		};
		const locals = makeLocalsFromStore(currentStore, {
			email: "ghost@example.com",
			role: "admin",
			name: "Ghost",
		});
		const ctx = await getAccessContext({ locals });
		if (!ctx) throw new Error("expected ctx");
		expect(ctx.subject.id).toBe("email:ghost@example.com");
		expect(ctx.subject.roles).toEqual([]);
	});

	test("caches the resolved context across calls", async () => {
		const locals = makeLocalsFromStore(currentStore, {
			email: "editor@example.com",
			role: "editor",
			name: "Editor",
		});
		const a = await getAccessContext({ locals });
		const b = await getAccessContext({ locals });
		expect(a).toBe(b);
	});
});

tests/admin-normalizers.test.ts.source:
import { describe, expect, it } from "vitest";

import {
	normalizeEmail,
	normalizePath,
	normalizeRedirectPath,
	parseIdList,
	serializeIdList,
	slugify,
} from "../src/admin-normalizers";

describe("normalizePath", () => {
	it("returns empty string for empty input", () => {
		expect(normalizePath("")).toBe("");
	});

	it("returns empty string for whitespace-only input", () => {
		expect(normalizePath("   ")).toBe("");
	});

	it("prepends slash when path lacks one", () => {
		expect(normalizePath("about")).toBe("/about");
	});

	it("preserves existing leading slash", () => {
		expect(normalizePath("/about")).toBe("/about");
	});

	it("trims surrounding whitespace before normalizing", () => {
		expect(normalizePath("  /about  ")).toBe("/about");
	});
});

describe("normalizeRedirectPath", () => {
	it("returns empty string for empty input", () => {
		expect(normalizeRedirectPath("")).toBe("");
	});

	it("returns empty string for whitespace-only input", () => {
		expect(normalizeRedirectPath("   ")).toBe("");
	});

	it("rejects protocol-relative URLs (open redirect vector)", () => {
		expect(normalizeRedirectPath("//evil.example.com")).toBe("");
	});

	it("rejects protocol-relative URLs with trailing whitespace trimmed first", () => {
		expect(normalizeRedirectPath("  //evil.example.com/path  ")).toBe("");
	});

	it("prepends slash to relative paths", () => {
		expect(normalizeRedirectPath("dashboard")).toBe("/dashboard");
	});

	it("preserves existing leading slash", () => {
		expect(normalizeRedirectPath("/dashboard")).toBe("/dashboard");
	});
});

describe("normalizeEmail", () => {
	it("lowercases and trims the value", () => {
		expect(normalizeEmail("  Admin@Example.COM  ")).toBe("admin@example.com");
	});
});

describe("slugify", () => {
	it("lowercases, replaces non-alphanumeric runs with hyphens, strips leading/trailing hyphens", () => {
		expect(slugify("Hello World!")).toBe("hello-world");
	});
});

describe("parseIdList", () => {
	it.each([null, undefined, ""])("returns empty array for falsy input: %s", (value) => {
		expect(parseIdList(value)).toEqual([]);
	});

	it("returns empty array for invalid JSON string", () => {
		expect(parseIdList("not-json")).toEqual([]);
	});

	it("returns empty array when JSON is a non-array value", () => {
		expect(parseIdList('{"id":1}')).toEqual([]);
	});

	it("filters out non-integer and non-positive entries", () => {
		expect(parseIdList('["a", -1, 0, 1.5, 2]')).toEqual([2]);
	});

	it("parses a valid array of positive integers", () => {
		expect(parseIdList("[1, 2, 3]")).toEqual([1, 2, 3]);
	});
});

describe("serializeIdList", () => {
	it("serializes a sorted array of positive integers", () => {
		expect(serializeIdList([3, 1, 2])).toBe("[1,2,3]");
	});

	it("filters out non-positive entries before serializing", () => {
		expect(serializeIdList([0, -1, 3, 1])).toBe("[1,3]");
	});

	it("filters out non-integer entries", () => {
		expect(serializeIdList([1.5, 2, 3])).toBe("[2,3]");
	});

	it("returns empty array for all-negative input", () => {
		expect(serializeIdList([-1, -2, -3])).toBe("[]");
	});

	it("returns empty array for empty input", () => {
		expect(serializeIdList([])).toBe("[]");
	});
});

describe("slugify — edge cases", () => {
	it("collapses consecutive non-alphanumeric characters into a single hyphen", () => {
		expect(slugify("hello  world")).toBe("hello-world");
	});

	it("strips leading hyphens from special-char prefix", () => {
		expect(slugify("!hello")).toBe("hello");
	});

	it("strips trailing hyphens from special-char suffix", () => {
		expect(slugify("hello!")).toBe("hello");
	});

	it("strips multiple consecutive trailing hyphens", () => {
		// Kills Regex mutation: -+$ → -$ (only strips one trailing hyphen)
		expect(slugify("hello!!")).toBe("hello");
	});

	it("strips multiple consecutive leading hyphens", () => {
		// Kills Regex mutation: ^-+ → ^- (only strips one leading hyphen)
		expect(slugify("!!hello")).toBe("hello");
	});

	it("strips both leading and trailing hyphens", () => {
		expect(slugify("---hello world---")).toBe("hello-world");
	});

	it("collapses internal runs of hyphens produced by adjacent special chars", () => {
		expect(slugify("hello!!world")).toBe("hello-world");
	});

	it("handles leading and trailing whitespace without explicit trim", () => {
		expect(slugify("  hello  ")).toBe("hello");
	});

	it("returns empty string for all non-alphanumeric input", () => {
		expect(slugify("!!!")).toBe("");
	});

	it("trims whitespace before processing", () => {
		expect(slugify("  hello world  ")).toBe("hello-world");
	});
});

describe("parseIdList — boundary cases", () => {
	it("filters out zero (entry > 0 not >=)", () => {
		expect(parseIdList("[0]")).toEqual([]);
	});

	it("parses mixed valid and invalid values", () => {
		expect(parseIdList("[1, 0, -5, 3]")).toEqual([1, 3]);
	});
});

describe("normalizeEmail — individual transforms", () => {
	it("lowercases without trimming when no whitespace present", () => {
		expect(normalizeEmail("ADMIN@EXAMPLE.COM")).toBe("admin@example.com");
	});

	it("trims without case-folding when already lowercase", () => {
		expect(normalizeEmail("  admin@example.com  ")).toBe("admin@example.com");
	});
});

describe("normalizePath — whitespace without slash", () => {
	it("prepends slash to a path with inner whitespace stripped", () => {
		expect(normalizePath("  about  ")).toBe("/about");
	});
});

describe("normalizeRedirectPath — additional branches", () => {
	it("rejects path that is exactly '//'", () => {
		expect(normalizeRedirectPath("//")).toBe("");
	});

	it("accepts a single slash", () => {
		expect(normalizeRedirectPath("/")).toBe("/");
	});
});

tests/content-scheduling.test.ts.source:
import type { DatabaseSync } from "node:sqlite";
import { describe, expect, it } from "vitest";

import type { ContentStoreRecord } from "../src/platform-contracts";
import { createSqliteContentStore } from "../src/sqlite-runtime/content.js";
import { makeDb } from "./helpers/make-db.js";

function makeStore(db: DatabaseSync) {
	let id = 0;
	return createSqliteContentStore(
		() => db,
		() => `rec_${++id}`,
	);
}

function seedPost(db: DatabaseSync, slug: string) {
	db.prepare(
		`INSERT INTO content_entries (slug, legacy_url, title, kind, template_key, source_html_path, updated_at, body, summary, seo_title, meta_description)
     VALUES (?, ?, ?, 'post', 'content', 'runtime://content/' || ?, CURRENT_TIMESTAMP, 'body', '', ?, '')`,
	).run(slug, `/${slug}`, `Title for ${slug}`, slug, `Title for ${slug}`);

	db.prepare(
		`INSERT INTO content_overrides (slug, title, status, seo_title, meta_description, updated_at, updated_by)
     VALUES (?, ?, 'draft', ?, '', CURRENT_TIMESTAMP, 'seed@test.local')`,
	).run(slug, `Title for ${slug}`, `Title for ${slug}`);
}

// ─── ContentStoreRecord shape ─────────────────────────────────────────────────

describe("ContentStoreRecord scheduledAt field", () => {
	it("scheduledAt is optional on ContentStoreRecord", () => {
		const record: ContentStoreRecord = {
			id: "rec_01",
			kind: "post",
			slug: "my-post",
			status: "draft",
		};
		expect(record.scheduledAt).toBeUndefined();
	});

	it("scheduledAt can be set to an ISO string", () => {
		const scheduled = "2026-06-01T09:00:00Z";
		const record: ContentStoreRecord = {
			id: "rec_02",
			kind: "post",
			slug: "future-post",
			status: "draft",
			scheduledAt: scheduled,
		};
		expect(record.scheduledAt).toBe(scheduled);
	});

	it("scheduledAt can be null (cleared)", () => {
		const record: ContentStoreRecord = {
			id: "rec_03",
			kind: "post",
			slug: "unscheduled-post",
			status: "draft",
			scheduledAt: null,
		};
		expect(record.scheduledAt).toBeNull();
	});
});

// ─── Content scheduling store operations ─────────────────────────────────────

describe("Content scheduling store operations", () => {
	it("scheduleContentPublish sets scheduled_at and keeps status as draft", () => {
		const db = makeDb();
		const { sqliteSchedulingRepository } = makeStore(db);
		seedPost(db, "future-post");

		const futureDate = new Date(Date.now() + 86_400_000).toISOString(); // tomorrow
		sqliteSchedulingRepository.schedulePublish("future-post", futureDate);

		const row = db
			.prepare("SELECT scheduled_at, status FROM content_overrides WHERE slug = ?")
			.get("future-post") as { scheduled_at: string; status: string };
		expect(row.scheduled_at).toBe(futureDate);
		expect(row.status).toBe("draft");
	});

	it("listScheduledContent returns only records with a future scheduled_at", () => {
		const db = makeDb();
		const { sqliteSchedulingRepository } = makeStore(db);
		seedPost(db, "post-a");
		seedPost(db, "post-b");

		const future = new Date(Date.now() + 86_400_000).toISOString();
		const past = new Date(Date.now() - 86_400_000).toISOString();

		sqliteSchedulingRepository.schedulePublish("post-a", future);
		// Set post-b to a past timestamp directly so it doesn't appear in listScheduled
		db.prepare("UPDATE content_overrides SET scheduled_at = ? WHERE slug = ?").run(past, "post-b");

		const scheduled = sqliteSchedulingRepository.listScheduled();
		const slugs = scheduled.map((s) => s.slug);
		expect(slugs).toContain("post-a");
		expect(slugs).not.toContain("post-b");
	});

	it("cancelScheduledPublish clears scheduled_at leaving status as draft", () => {
		const db = makeDb();
		const { sqliteSchedulingRepository } = makeStore(db);
		seedPost(db, "cancel-me");

		const future = new Date(Date.now() + 86_400_000).toISOString();
		sqliteSchedulingRepository.schedulePublish("cancel-me", future);
		sqliteSchedulingRepository.cancelScheduledPublish("cancel-me");

		const row = db
			.prepare("SELECT scheduled_at, status FROM content_overrides WHERE slug = ?")
			.get("cancel-me") as { scheduled_at: string | null; status: string };
		expect(row.scheduled_at).toBeNull();
		expect(row.status).toBe("draft");
	});

	it("scheduler run publishes records whose scheduled_at is in the past", () => {
		const db = makeDb();
		const { sqliteSchedulingRepository } = makeStore(db);
		seedPost(db, "past-post");

		// Directly set a past scheduled_at
		const past = new Date(Date.now() - 1000).toISOString();
		db.prepare("UPDATE content_overrides SET scheduled_at = ? WHERE slug = ?").run(
			past,
			"past-post",
		);

		const published = sqliteSchedulingRepository.runScheduledPublishes();
		expect(published).toBeGreaterThanOrEqual(1);

		const row = db
			.prepare("SELECT scheduled_at, status FROM content_overrides WHERE slug = ?")
			.get("past-post") as { scheduled_at: string | null; status: string };
		expect(row.status).toBe("published");
		expect(row.scheduled_at).toBeNull();
	});

	it("scheduling a post does not immediately make it publicly visible", () => {
		const db = makeDb();
		const { sqliteSchedulingRepository } = makeStore(db);
		seedPost(db, "not-yet-visible");

		const future = new Date(Date.now() + 86_400_000).toISOString();
		sqliteSchedulingRepository.schedulePublish("not-yet-visible", future);

		const row = db
			.prepare("SELECT status FROM content_overrides WHERE slug = ?")
			.get("not-yet-visible") as { status: string };
		expect(row.status).toBe("draft");
	});
});

