import { afterAll, afterEach, describe, expect, it, vi } from "vitest";

async function importRuntimeEnv() {
	vi.resetModules();
	return import("../src/runtime-prod.js");
}

async function importUtils() {
	vi.resetModules();
	return import("../src/sqlite-runtime/utils.js");
}

afterAll(() => {
	vi.resetModules();
});

describe("devRootSecretOrThrow (#126 / #132)", () => {
	afterEach(() => vi.unstubAllEnvs());

	it("returns DEV_ROOT_SECRET_FALLBACK in non-production runtimes", async () => {
		vi.stubEnv("PROD", false);
		const env = await importRuntimeEnv();
		expect(env.devRootSecretOrThrow()).toBe(env.DEV_ROOT_SECRET_FALLBACK);
	});

	it("throws in production with a message naming ASTROPRESS_ROOT_SECRET", async () => {
		vi.stubEnv("PROD", "true");
		const env = await importRuntimeEnv();
		expect(() => env.devRootSecretOrThrow()).toThrow(/ASTROPRESS_ROOT_SECRET/);
		// Assert the full operator-facing message (all three concatenated
		// fragments) so a StringLiteral mutant blanking any fragment is caught.
		let message = "";
		try {
			env.devRootSecretOrThrow();
		} catch (err) {
			message = (err as Error).message;
		}
		expect(message).toContain("must be configured in production");
		expect(message).toContain("Refusing to fall back to the public development root secret");
		expect(message).toContain("for session/token/integration-seal protection.");
	});
});

describe("resolveTokenHashSecret (#132 token-hash path)", () => {
	afterEach(() => vi.unstubAllEnvs());

	it("returns the explicit secret unchanged when one is configured", async () => {
		vi.stubEnv("PROD", "true"); // even in prod, explicit secret flows through
		const env = await importRuntimeEnv();
		expect(env.resolveTokenHashSecret("real-secret")).toBe("real-secret");
	});

	it("preserves an explicit empty-string secret (does not collapse to fallback)", async () => {
		vi.stubEnv("PROD", false);
		const env = await importRuntimeEnv();
		expect(env.resolveTokenHashSecret("")).toBe("");
	});

	it("falls back to DEV_ROOT_SECRET_FALLBACK when secret is null/undefined (dev)", async () => {
		vi.stubEnv("PROD", false);
		const env = await importRuntimeEnv();
		expect(env.resolveTokenHashSecret(undefined)).toBe(env.DEV_ROOT_SECRET_FALLBACK);
		expect(env.resolveTokenHashSecret(null)).toBe(env.DEV_ROOT_SECRET_FALLBACK);
	});

	it("throws in production when secret is null/undefined (fail-closed)", async () => {
		vi.stubEnv("PROD", "true");
		const env = await importRuntimeEnv();
		expect(() => env.resolveTokenHashSecret(undefined)).toThrow(/ASTROPRESS_ROOT_SECRET/);
	});
});

describe("hashOpaqueToken default secret resolution (#132)", () => {
	afterEach(() => vi.unstubAllEnvs());

	it("hashes successfully in dev when no secret is threaded", async () => {
		vi.stubEnv("PROD", false);
		const { hashOpaqueToken } = await importUtils();
		expect(hashOpaqueToken("invite-token")).toMatch(/^[a-f0-9]+$/);
	});

	it("throws in production when no secret is threaded (fail-closed for D1 invite/reset/api-token paths)", async () => {
		vi.stubEnv("PROD", "true");
		const { hashOpaqueToken } = await importUtils();
		expect(() => hashOpaqueToken("invite-token")).toThrow(/ASTROPRESS_ROOT_SECRET/);
	});

	it("in production, a configured secret hashes successfully", async () => {
		vi.stubEnv("PROD", "true");
		const { hashOpaqueToken } = await importUtils();
		expect(hashOpaqueToken("invite-token", "configured-secret")).toMatch(/^[a-f0-9]+$/);
	});
});

tests/integration-error-sanitizer.test.t.source:
import { describe, expect, it } from "vitest";
import {
	isIntegrationErrorCode,
	sanitizeIntegrationError,
} from "../src/integration-error-sanitizer";

describe("sanitizeIntegrationError", () => {
	it("returns the explicit hint when valid", () => {
		expect(sanitizeIntegrationError(new Error("upstream"), "INTEGRATION_AUTH_REJECTED")).toBe(
			"INTEGRATION_AUTH_REJECTED",
		);
	});

	it("recognises typed `code` on the thrown object", () => {
		expect(sanitizeIntegrationError({ code: "INTEGRATION_RATE_LIMITED" })).toBe(
			"INTEGRATION_RATE_LIMITED",
		);
	});

	it("maps AbortError → INTEGRATION_TIMEOUT", () => {
		const err = new Error("aborted");
		err.name = "AbortError";
		expect(sanitizeIntegrationError(err)).toBe("INTEGRATION_TIMEOUT");
	});

	it("maps TypeError (fetch failure shape) → INTEGRATION_NETWORK_ERROR", () => {
		const err = new TypeError("Failed to fetch");
		expect(sanitizeIntegrationError(err)).toBe("INTEGRATION_NETWORK_ERROR");
	});

	it("falls back to INTEGRATION_UNKNOWN_ERROR for arbitrary thrown values", () => {
		expect(sanitizeIntegrationError("upstream-401-credentials-leaked")).toBe(
			"INTEGRATION_UNKNOWN_ERROR",
		);
		expect(sanitizeIntegrationError(undefined)).toBe("INTEGRATION_UNKNOWN_ERROR");
		expect(sanitizeIntegrationError(new Error("Bearer abcd1234"))).toBe(
			"INTEGRATION_UNKNOWN_ERROR",
		);
	});

	it("never echoes the original error message", () => {
		const code = sanitizeIntegrationError(new Error("API_KEY=sk-secret-do-not-leak"));
		expect(code).not.toContain("sk-secret-do-not-leak");
		expect(code).not.toContain("API_KEY");
	});

	it("isIntegrationErrorCode rejects arbitrary strings", () => {
		expect(isIntegrationErrorCode("INTEGRATION_VERIFY_FAILED")).toBe(true);
		expect(isIntegrationErrorCode("anything-else")).toBe(false);
		expect(isIntegrationErrorCode(undefined)).toBe(false);
	});

	it("isIntegrationErrorCode rejects non-string types", () => {
		expect(isIntegrationErrorCode(123)).toBe(false);
		expect(isIntegrationErrorCode({})).toBe(false);
		expect(isIntegrationErrorCode(null)).toBe(false);
	});

	it("rejects an unknown hint string and falls through to typed code lookup", () => {
		const code = sanitizeIntegrationError(
			{ code: "INTEGRATION_VERIFY_FAILED" },
			"NOT_A_REAL_CODE" as never,
		);
		expect(code).toBe("INTEGRATION_VERIFY_FAILED");
	});

	it("ignores objects whose `code` is not a known IntegrationErrorCode", () => {
		expect(sanitizeIntegrationError({ code: "garbage-code" })).toBe("INTEGRATION_UNKNOWN_ERROR");
	});

	it("falls through when err is an object without `code` property", () => {
		expect(sanitizeIntegrationError({ unrelated: true })).toBe("INTEGRATION_UNKNOWN_ERROR");
	});

	it("maps TimeoutError → INTEGRATION_TIMEOUT", () => {
		const err = new Error("timed out");
		err.name = "TimeoutError";
		expect(sanitizeIntegrationError(err)).toBe("INTEGRATION_TIMEOUT");
	});

	it("non-matching error names fall through to INTEGRATION_UNKNOWN_ERROR", () => {
		const err = new Error("generic");
		err.name = "RangeError";
		expect(sanitizeIntegrationError(err)).toBe("INTEGRATION_UNKNOWN_ERROR");
	});

	it("null and primitive throws fall through to INTEGRATION_UNKNOWN_ERROR", () => {
		expect(sanitizeIntegrationError(null)).toBe("INTEGRATION_UNKNOWN_ERROR");
		expect(sanitizeIntegrationError(42)).toBe("INTEGRATION_UNKNOWN_ERROR");
	});
});

tests/sitemap-plugin.test.ts.source:
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { createSitemapPlugin } from "../src/plugins/sitemap-plugin.js";

const event = {
	slug: "my-post",
	kind: "post" as const,
	status: "published" as const,
	actor: "admin@example.com",
};

describe("createSitemapPlugin", () => {
	let fetchSpy: ReturnType<typeof vi.spyOn>;

	beforeEach(() => {
		fetchSpy = vi.spyOn(globalThis, "fetch").mockResolvedValue(new Response(null, { status: 200 }));
	});
	afterEach(() => {
		fetchSpy.mockRestore();
	});

	it("does NOT call fetch when purgeUrl is omitted", async () => {
		const plugin = createSitemapPlugin();
		await plugin.onContentPublish?.(event);
		expect(fetchSpy).not.toHaveBeenCalled();
	});

	it("does NOT call onPublish when callback is omitted (no-op safe)", async () => {
		const plugin = createSitemapPlugin();
		await expect(plugin.onContentPublish?.(event)).resolves.toBeUndefined();
	});

	it("POSTs to purgeUrl with JSON content-type and slug+event body", async () => {
		const plugin = createSitemapPlugin({ purgeUrl: "https://h.example/purge" });
		await plugin.onContentPublish?.(event);
		expect(fetchSpy).toHaveBeenCalledTimes(1);
		const [url, init] = fetchSpy.mock.calls[0] as [string, RequestInit];
		expect(url).toBe("https://h.example/purge");
		expect(init.method).toBe("POST");
		expect((init.headers as Record<string, string>)["Content-Type"]).toBe("application/json");
		const body = JSON.parse(init.body as string) as Record<string, unknown>;
		expect(body.slug).toBe("my-post");
		expect(body.event).toBe("content.publish");
		expect(typeof body.purgedAt).toBe("string");
		// purgedAt is an ISO timestamp.
		expect(body.purgedAt).toMatch(/^\d{4}-\d{2}-\d{2}T/);
	});

	it("swallows fetch failures and warns to console.warn (non-fatal)", async () => {
		fetchSpy.mockRejectedValueOnce(new Error("network down"));
		const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
		const plugin = createSitemapPlugin({ purgeUrl: "https://h.example/p" });
		await expect(plugin.onContentPublish?.(event)).resolves.toBeUndefined();
		expect(warnSpy).toHaveBeenCalledTimes(1);
		const msg = String(warnSpy.mock.calls[0]?.[0] ?? "");
		expect(msg).toContain("astropress-sitemap");
		expect(msg).toContain("my-post");
		warnSpy.mockRestore();
	});

	it("invokes onPublish before POSTing to purgeUrl", async () => {
		const order: string[] = [];
		fetchSpy.mockImplementation(async () => {
			order.push("fetch");
			return new Response(null, { status: 200 });
		});
		const plugin = createSitemapPlugin({
			purgeUrl: "https://h.example/p",
			onPublish: () => {
				order.push("onPublish");
			},
		});
		await plugin.onContentPublish?.(event);
		expect(order).toEqual(["onPublish", "fetch"]);
	});

	it("awaits an async onPublish callback", async () => {
		let resolved = false;
		const plugin = createSitemapPlugin({
			onPublish: async () => {
				await new Promise((r) => setTimeout(r, 10));
				resolved = true;
			},
		});
		await plugin.onContentPublish?.(event);
		expect(resolved).toBe(true);
	});

	it("default options ({}) yields a plugin with no fetch and no callback effects", async () => {
		const plugin = createSitemapPlugin({});
		await plugin.onContentPublish?.(event);
		expect(fetchSpy).not.toHaveBeenCalled();
	});
});

tests/translation-state.test.ts.source:
import { describe, expect, it } from "vitest";

import {
	isPublishedTranslationState,
	normalizeTranslationState,
	translationStates,
} from "../src/translation-state";

describe("translationStates manifest", () => {
	it("exposes the canonical 6-state vocabulary", () => {
		expect(translationStates).toEqual([
			"not_started",
			"partial",
			"fallback_en",
			"translated",
			"reviewed",
			"published",
		]);
	});
});

describe("normalizeTranslationState", () => {
	it("returns the provided fallback when value is null", () => {
		expect(normalizeTranslationState(null)).toBe("not_started");
		expect(normalizeTranslationState(null, "published")).toBe("published");
	});

	it("returns the provided fallback when value is undefined", () => {
		expect(normalizeTranslationState(undefined)).toBe("not_started");
		expect(normalizeTranslationState(undefined, "reviewed")).toBe("reviewed");
	});

	it("returns the provided fallback when value is empty string", () => {
		expect(normalizeTranslationState("")).toBe("not_started");
		expect(normalizeTranslationState("", "translated")).toBe("translated");
	});

	it("returns the same canonical state when input already matches", () => {
		for (const s of translationStates) {
			expect(normalizeTranslationState(s)).toBe(s);
		}
	});

	it("trims surrounding whitespace before matching", () => {
		expect(normalizeTranslationState("  published  ")).toBe("published");
	});

	it("lowercases input before matching", () => {
		expect(normalizeTranslationState("Published")).toBe("published");
		expect(normalizeTranslationState("PARTIAL")).toBe("partial");
	});

	it("maps each known legacy alias to its canonical state", () => {
		expect(normalizeTranslationState("original")).toBe("not_started");
		expect(normalizeTranslationState("in-progress")).toBe("partial");
		expect(normalizeTranslationState("pending-review")).toBe("translated");
		expect(normalizeTranslationState("approved")).toBe("reviewed");
		expect(normalizeTranslationState("needs-revision")).toBe("partial");
		expect(normalizeTranslationState("archived")).toBe("fallback_en");
		expect(normalizeTranslationState("complete")).toBe("published");
	});

	it("falls back when the value is neither canonical nor a legacy alias", () => {
		expect(normalizeTranslationState("unknown")).toBe("not_started");
		expect(normalizeTranslationState("unknown", "reviewed")).toBe("reviewed");
	});
});

describe("isPublishedTranslationState", () => {
	it("returns true for the canonical 'published' state", () => {
		expect(isPublishedTranslationState("published")).toBe(true);
	});

	it("returns true for the legacy 'complete' alias", () => {
		expect(isPublishedTranslationState("complete")).toBe(true);
	});

	it("returns false for any other canonical state", () => {
		for (const s of translationStates) {
			if (s === "published") continue;
			expect(isPublishedTranslationState(s)).toBe(false);
		}
	});

	it("returns false for null/undefined/empty inputs", () => {
		expect(isPublishedTranslationState(null)).toBe(false);
		expect(isPublishedTranslationState(undefined)).toBe(false);
		expect(isPublishedTranslationState("")).toBe(false);
	});
});

tests/media.test.ts.source:
import {
	getRuntimeMediaResolutionOptions,
	resolveMediaUrl,
	resolveRuntimeMediaUrl,
} from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";

const sampleRecord = {
	id: "img-001",
	sourceUrl: "https://legacy.example.org/wp-content/uploads/hero.jpg",
	localPath: "/images/home/community-garden-hero.jpg",
	r2Key: "images/home/community-garden-hero.jpg",
};

describe("resolveMediaUrl()", () => {
	it("returns localPath in development mode", () => {
		const url = resolveMediaUrl(sampleRecord, { mode: "development" });
		expect(url).toBe(sampleRecord.localPath);
	});

	it("development mode short-circuits even when r2BaseUrl is set (kills dev-branch mutants)", () => {
		// Critical: dev mode must NOT build an R2 URL even if one is configured.
		// Original returns localPath; if the dev short-circuit were removed we'd
		// fall through to the deployment branch and synthesize an R2 URL.
		const url = resolveMediaUrl(sampleRecord, {
			mode: "development",
			r2BaseUrl: "https://cdn.example.org",
		});
		expect(url).toBe(sampleRecord.localPath);
		expect(url).not.toContain("cdn.example.org");
	});

	it("returns localPath in deployment mode when no r2BaseUrl is provided", () => {
		const url = resolveMediaUrl(sampleRecord, { mode: "deployment" });
		expect(url).toBe(sampleRecord.localPath);
	});

	it("returns r2 URL in deployment mode when r2BaseUrl is provided", () => {
		const url = resolveMediaUrl(sampleRecord, {
			mode: "deployment",
			r2BaseUrl: "https://cdn.example.org",
		});
		expect(url).toBe("https://cdn.example.org/images/home/community-garden-hero.jpg");
	});

	it("strips trailing slash from r2BaseUrl before joining", () => {
		const url = resolveMediaUrl(sampleRecord, {
			mode: "deployment",
			r2BaseUrl: "https://cdn.example.org/",
		});
		expect(url).not.toContain("//images");
		expect(url).toBe("https://cdn.example.org/images/home/community-garden-hero.jpg");
	});

	it("keeps localPath when no r2 key exists", () => {
		const url = resolveMediaUrl(
			{ ...sampleRecord, r2Key: null },
			{ mode: "deployment", r2BaseUrl: "https://cdn.example.org" },
		);
		expect(url).toBe(sampleRecord.localPath);
	});

	it("builds runtime media options from env defaults", () => {
		expect(getRuntimeMediaResolutionOptions()).toEqual({
			mode: "development",
			r2BaseUrl: undefined,
		});
	});

	it("switches runtime media options to deployment when an R2 base URL is configured", () => {
		expect(
			getRuntimeMediaResolutionOptions({
				runtime: { env: { PUBLIC_R2_BASE_URL: "https://cdn.example.org" } },
			} as App.Locals),
		).toEqual({
			mode: "deployment",
			r2BaseUrl: "https://cdn.example.org",
		});
	});

	it("resolves runtime media URLs with local defaults", () => {
		expect(resolveRuntimeMediaUrl(sampleRecord)).toBe(sampleRecord.localPath);
	});

	it("resolves runtime media URLs to R2 when configured through runtime bindings", () => {
		expect(
			resolveRuntimeMediaUrl(sampleRecord, {
				runtime: { env: { PUBLIC_R2_BASE_URL: "https://cdn.example.org" } },
			} as App.Locals),
		).toBe("https://cdn.example.org/images/home/community-garden-hero.jpg");
	});
});

tests/adapters/supabase-sqlite.test.ts.source:
import { mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";

import { createAstropressSupabaseSqliteAdapter } from "../../src/adapters/supabase-sqlite";

const workspaces: string[] = [];
afterEach(() => {
	workspaces.length = 0;
});

async function freshWorkspace(): Promise<string> {
	const w = await mkdtemp(join(tmpdir(), "astropress-supabase-sqlite-"));
	workspaces.push(w);
	return w;
}

describe("createAstropressSupabaseSqliteAdapter", () => {
	it("returns an adapter with the supabase capability profile", async () => {
		const workspace = await freshWorkspace();
		const adapter = createAstropressSupabaseSqliteAdapter({
			workspaceRoot: workspace,
			dbPath: join(workspace, "supabase-admin.sqlite"),
		});
		expect(adapter).toBeDefined();
		// supabase wraps sqlite: the resulting adapter must expose the
		// supabase identity, not the bare sqlite identity.
		expect(adapter.capabilities.name).toBe("supabase");
	});

	it("accepts an empty options object via the default argument", async () => {
		// Pins the default-arg mutation: `options = {}` → `options = "Stryker was here"`.
		const adapter = createAstropressSupabaseSqliteAdapter();
		expect(adapter).toBeDefined();
		expect(adapter.capabilities.name).toBe("supabase");
	});

	it("propagates the workspaceRoot through to the wrapped sqlite adapter", async () => {
		const workspace = await freshWorkspace();
		const adapter = createAstropressSupabaseSqliteAdapter({
			workspaceRoot: workspace,
		});
		// The supabase wrapper exposes the inner sqlite adapter via the
		// capability profile; both should agree the adapter is set up.
		expect(adapter.capabilities.database).toBe(true);
	});

	it("end-to-end: sign-in works (proves backingAdapter actually wires sqlite)", async () => {
		// Pins the ObjectLiteral mutation that drops the backingAdapter:
		// without sqlite underneath, signIn would not resolve a user record.
		const workspace = await freshWorkspace();
		const adapter = createAstropressSupabaseSqliteAdapter({
			workspaceRoot: workspace,
			dbPath: join(workspace, "supabase-admin.sqlite"),
		});
		const user = await adapter.auth.signIn("admin@example.com", "password");
		// The sqlite-backed signIn returns an admin user envelope shaped
		// { id, email, isAdmin }. The hosted-API path either throws at
		// config-read time (no SUPABASE_URL) or resolves over fetch — either
		// way it cannot produce this exact local-sqlite shape with the seed
		// admin's email and admin role flag.
		expect(user).toMatchObject({
			email: "admin@example.com",
			isAdmin: true,
		});
		expect(typeof user?.id).toBe("string");
		// Distinguishes the sqlite-backed signIn from the in-memory fallback:
		// sqlite returns a generated session id, while the default in-memory
		// auth store always returns the seed user's literal id "admin-1".
		// This kills the ObjectLiteral mutation that drops backingAdapter.
		expect(user?.id).not.toBe("admin-1");
	});
});

tests/vite-integration.test.ts.source:
import { describe, expect, it, vi } from "vitest";

vi.mock("../src/vite-runtime-alias", () => {
	return {
		createAstropressLocalRuntimeModulePlugin: vi.fn((path: string) => ({
			name: "local-runtime",
			__path: path,
		})),
		createAstropressPackageResolverPlugin: vi.fn((root: string) => ({
			name: "package-resolver",
			__root: root,
		})),
		createAstropressViteAliases: vi.fn((options) => [
			{ find: "alias", replacement: String(options?.localRuntimeModulesPath) },
		]),
	};
});

import { createAstropressViteIntegration } from "../src/vite-integration";
import {
	createAstropressLocalRuntimeModulePlugin,
	createAstropressPackageResolverPlugin,
	createAstropressViteAliases,
} from "../src/vite-runtime-alias";

describe("createAstropressViteIntegration", () => {
	it("returns the local-runtime plugin and aliases when astropressPackageRoot is unset", () => {
		const r = createAstropressViteIntegration({
			localRuntimeModulesPath: "/runtime.ts",
		} as never);
		expect(r.plugins).toHaveLength(1);
		expect((r.plugins[0] as { name: string }).name).toBe("local-runtime");
		expect((r.plugins[0] as { __path: string }).__path).toBe("/runtime.ts");
		expect(createAstropressLocalRuntimeModulePlugin).toHaveBeenCalledWith("/runtime.ts");
		expect(createAstropressPackageResolverPlugin).not.toHaveBeenCalled();
	});

	it("appends the package-resolver plugin when astropressPackageRoot is set", () => {
		const r = createAstropressViteIntegration({
			localRuntimeModulesPath: "/runtime.ts",
			astropressPackageRoot: "/pkg",
		} as never);
		expect(r.plugins).toHaveLength(2);
		expect((r.plugins[1] as { name: string }).name).toBe("package-resolver");
		expect((r.plugins[1] as { __root: string }).__root).toBe("/pkg");
		expect(createAstropressPackageResolverPlugin).toHaveBeenCalledWith("/pkg");
	});

	it("returns aliases produced by createAstropressViteAliases verbatim", () => {
		const r = createAstropressViteIntegration({
			localRuntimeModulesPath: "/x.ts",
		} as never);
		expect(r.aliases).toEqual([{ find: "alias", replacement: "/x.ts" }]);
		expect(createAstropressViteAliases).toHaveBeenCalledWith({
			localRuntimeModulesPath: "/x.ts",
		});
	});

	it("plugins array order: local-runtime first, package-resolver second", () => {
		const r = createAstropressViteIntegration({
			localRuntimeModulesPath: "/r.ts",
			astropressPackageRoot: "/pkg",
		} as never);
		expect((r.plugins[0] as { name: string }).name).toBe("local-runtime");
		expect((r.plugins[1] as { name: string }).name).toBe("package-resolver");
	});

	it("does not invoke package-resolver when astropressPackageRoot is empty string (falsy)", () => {
		// Pins ConditionalExpression on `if (options.astropressPackageRoot)`.
		(createAstropressPackageResolverPlugin as { mockClear?: () => void }).mockClear?.();
		const r = createAstropressViteIntegration({
			localRuntimeModulesPath: "/r.ts",
			astropressPackageRoot: "",
		} as never);
		expect(r.plugins).toHaveLength(1);
		expect(createAstropressPackageResolverPlugin).not.toHaveBeenCalled();
	});
});

tests/flash-d1.test.ts.source:
// Behavioral + mutation-coverage tests for the D1 flash store
// (src/sqlite-runtime/flash-d1.ts), exercised through the SqliteBackedD1Database
// fixture. The D1 sibling must behave identically to the sqlite store on every
// host that provides a D1 binding — same single-use + expiry guarantees that
// make the opaque `flash=<id>` redirect safe. See #113/#115/#133.
import { describe, expect, it, vi } from "vitest";

import { createD1FlashStore } from "../src/sqlite-runtime/flash-d1.js";
import { makeDb } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

function makeStore() {
	const db = makeDb();
	const d1 = new SqliteBackedD1Database(db);
	return { db, store: createD1FlashStore(d1) };
}

describe("createD1FlashStore", () => {
	it("put then consume returns the payload exactly once", async () => {
		const { store } = makeStore();
		const { id } = await store.put("d1-secret");
		expect(id).toMatch(/^flash_[0-9a-f]{36}$/);
		expect(await store.consume(id)).toBe("d1-secret");
		expect(await store.consume(id)).toBeNull();
	});

	it("consume deletes the row (no residue)", async () => {
		const { db, store } = makeStore();
		const { id } = await store.put("gone");
		await store.consume(id);
		expect(db.prepare("SELECT id FROM admin_flash WHERE id = ?").get(id)).toBeUndefined();
	});

	it("unknown id returns null", async () => {
		const { store } = makeStore();
		expect(await store.consume("flash_nope")).toBeNull();
	});

	it("expired entry is not readable and is deleted on read", async () => {
		const { db, store } = makeStore();
		const { id } = await store.put("stale", -1);
		expect(await store.consume(id)).toBeNull();
		expect(db.prepare("SELECT id FROM admin_flash WHERE id = ?").get(id)).toBeUndefined();
	});

	it("put sweeps expired rows", async () => {
		const { db, store } = makeStore();
		await store.put("old", -1);
		await store.put("fresh");
		const remaining = db.prepare("SELECT payload FROM admin_flash").all() as Array<{
			payload: string;
		}>;
		expect(remaining.map((r) => r.payload)).toEqual(["fresh"]);
	});

	it("treats an entry whose expiry equals the current instant as expired (boundary: <=)", async () => {
		const fixed = 1_700_000_000_000;
		const spy = vi.spyOn(Date, "now").mockReturnValue(fixed);
		try {
			const { db, store } = makeStore();
			const { id } = await store.put("edge", 0); // expires_at_ms = fixed
			expect(await store.consume(id)).toBeNull();
			expect(db.prepare("SELECT id FROM admin_flash WHERE id = ?").get(id)).toBeUndefined();
		} finally {
			spy.mockRestore();
		}
	});

	it("round-trips a JSON payload (webhook verification bundle shape)", async () => {
		const { store } = makeStore();
		const payload = JSON.stringify({ algorithm: "ml-dsa-65", publicKey: "abc123" });
		const { id } = await store.put(payload);
		expect(JSON.parse((await store.consume(id)) ?? "")).toEqual({
			algorithm: "ml-dsa-65",
			publicKey: "abc123",
		});
	});
});

